INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('9', '1sam', '1 Samuel', 16, 14, 'Tetapi Roh TUHAN telah mundur dari pada Saul, dan sekarang ia diganggu oleh roh jahat yang dari pada TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 15, 'Lalu berkatalah hamba-hamba Saul kepadanya: "Ketahuilah, roh jahat yang dari pada Allah mengganggu engkau;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 16, 'baiklah tuanku menitahkan hamba-hambamu yang di depanmu ini mencari seorang yang pandai main kecapi. Apabila roh jahat yang dari pada Allah itu hinggap padamu, haruslah ia main kecapi, maka engkau merasa nyaman."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 17, 'Berkatalah Saul kepada hamba-hambanya itu: "Carilah bagiku seorang yang dapat main kecapi dengan baik, dan bawalah dia kepadaku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 18, 'Lalu jawab salah seorang hamba itu, katanya: "Sesungguhnya, aku telah melihat salah seorang anak laki-laki Isai, orang Betlehem itu, yang pandai main kecapi. Ia seorang pahlawan yang gagah perkasa, seorang prajurit, yang pandai bicara, elok perawakannya; dan TUHAN menyertai dia."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 19, 'Kemudian Saul mengirim suruhan kepada Isai dengan pesan: "Suruhlah kepadaku anakmu Daud, yang ada pada kambing domba itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 20, 'Lalu Isai mengambil seekor keledai yang dimuati roti, sekirbat anggur dan seekor anak kambing, maka dikirimkannyalah itu kepada Saul dengan perantaraan Daud, anaknya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 21, 'Demikianlah Daud sampai kepada Saul dan menjadi pelayannya. Saul sangat mengasihinya, dan ia menjadi pembawa senjatanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 22, 'Sebab itu Saul menyuruh orang kepada Isai mengatakan: "Biarkanlah Daud tetap menjadi pelayanku, sebab aku suka kepadanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 16, 23, 'Dan setiap kali apabila roh yang dari pada Allah itu hinggap pada Saul, maka Daud mengambil kecapi dan memainkannya; Saul merasa lega dan nyaman, dan roh yang jahat itu undur dari padanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 1, 'Orang Filistin mengumpulkan tentaranya untuk berperang; mereka berkumpul di Sokho yang di tanah Yehuda dan berkemah antara Sokho dan Azeka di Efes-Damim.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 2, 'Saul dan orang-orang Israel juga berkumpul dan berkemah di Lembah Tarbantin; mereka mengatur barisan perangnya berhadapan dengan orang Filistin.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 3, 'Orang Filistin berdiri di bukit sebelah sini dan orang Israel berdiri di bukit sebelah sana, dan lembah ada di antara mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 4, 'Lalu tampillah keluar seorang pendekar dari tentara orang Filistin. Namanya Goliat, dari Gat. Tingginya enam hasta sejengkal.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 5, 'Ketopong tembaga ada di kepalanya, dan ia memakai baju zirah yang bersisik; berat baju zirah ini lima ribu syikal tembaga.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 6, 'Dia memakai penutup kaki dari tembaga, dan di bahunya ia memanggul lembing tembaga.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 7, 'Gagang tombaknya seperti pesa tukang tenun, dan mata tombaknya itu enam ratus syikal besi beratnya. Dan seorang pembawa perisai berjalan di depannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 8, 'Ia berdiri dan berseru kepada barisan Israel, katanya kepada mereka: "Mengapa kamu keluar untuk mengatur barisan perangmu? Bukankah aku seorang Filistin dan kamu adalah hamba Saul? Pilihlah bagimu seorang, dan biarlah ia turun mendapatkan daku.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 9, 'Jika ia dapat berperang melawan aku dan mengalahkan aku, maka kami akan menjadi hambamu; tetapi jika aku dapat mengungguli dia dan mengalahkannya, maka kamu akan menjadi hamba kami dan takluk kepada kami."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 10, 'Pula kata orang Filistin itu: "Aku menantang hari ini barisan Israel; berikanlah kepadaku seorang, supaya kami berperang seorang lawan seorang."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 11, 'Ketika Saul dan segenap orang Israel mendengar perkataan orang Filistin itu, maka cemaslah hati mereka dan sangat ketakutan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 12, 'Daud adalah anak seorang dari Efrata, dari Betlehem-Yehuda, yang bernama Isai. Isai mempunyai delapan anak laki-laki. Pada zaman Saul orang itu telah tua dan lanjut usianya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 13, 'Ketiga anak Isai yang besar-besar telah pergi berperang mengikuti Saul; nama ketiga anaknya yang pergi berperang itu ialah Eliab, anak sulung, anak yang kedua ialah Abinadab, dan anak yang ketiga adalah Syama.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 14, 'Daudlah yang bungsu. Jadi ketiga anak yang besar-besar itu pergi mengikuti Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 15, 'Tetapi Daud selalu pulang dari pada Saul untuk menggembalakan domba ayahnya di Betlehem.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 16, 'Orang Filistin itu maju mendekat pada pagi hari dan pada petang hari. Demikianlah ia tampil ke depan empat puluh hari lamanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 17, 'Isai berkata kepada Daud, anaknya: "Ambillah untuk kakak-kakakmu bertih gandum ini seefa dan roti yang sepuluh ini; bawalah cepat-cepat ke perkemahan, kepada kakak-kakakmu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 18, 'Dan baiklah sampaikan keju yang sepuluh ini kepada kepala pasukan seribu. Tengoklah apakah kakak-kakakmu selamat dan bawalah pulang suatu tanda dari mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 19, 'Saul dan mereka itu dan semua orang Israel ada di Lembah Tarbantin tengah berperang melawan orang Filistin."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 20, 'Lalu Daud bangun pagi-pagi, ditinggalkannyalah kambing dombanya pada seorang penjaga, lalu mengangkat muatan dan pergi, seperti yang diperintahkan Isai kepadanya. Sampailah ia ke perkemahan, ketika tentara keluar untuk mengatur barisannya dan mengangkat sorak perang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 21, 'Orang Israel dan orang Filistin itu mengatur barisannya, barisan berhadapan dengan barisan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 22, 'Lalu Daud menurunkan barang-barangnya dan meninggalkannya di tangan penjaga barang-barang tentara. Berlari-larilah Daud ke tempat barisan; sesampai di sana, bertanyalah ia kepada kakak-kakaknya apakah mereka selamat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 23, 'Sedang ia berbicara dengan mereka, tampillah maju pendekar itu. Namanya Goliat, orang Filistin dari Gat, dari barisan orang Filistin. Ia mengucapkan kata-kata yang tadi juga, dan Daud mendengarnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 24, 'Ketika semua orang Israel melihat orang itu, larilah mereka dari padanya dengan sangat ketakutan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 25, 'Berkatalah orang-orang Israel itu: "Sudahkah kamu lihat orang yang maju itu? Sesungguhnya ia maju untuk mencemoohkan orang Israel! Orang yang mengalahkan dia akan dianugerahi raja kekayaan yang besar, raja akan memberikan anaknya yang perempuan kepadanya dan kaum keluarganya akan dibebaskannya dari pajak di Israel."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 26, 'Lalu berkatalah Daud kepada orang-orang yang berdiri di dekatnya: "Apakah yang akan dilakukan kepada orang yang mengalahkan orang Filistin itu dan yang menghindarkan cemooh dari Israel? Siapakah orang Filistin yang tak bersunat ini, sampai ia berani mencemoohkan barisan dari pada Allah yang hidup?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 27, 'Rakyat itupun menjawabnya dengan perkataan tadi: "Begitulah akan dilakukan kepada orang yang mengalahkan dia."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 28, 'Ketika Eliab, kakaknya yang tertua, mendengar perkataan Daud kepada orang-orang itu, bangkitlah amarah Eliab kepada Daud sambil berkata: "Mengapa engkau datang? Dan pada siapakah kautinggalkan kambing domba yang dua tiga ekor itu di padang gurun? Aku kenal sifat pemberanimu dan kejahatan hatimu: engkau datang ke mari dengan maksud melihat pertempuran."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 29, 'Tetapi jawab Daud: "Apa yang telah kuperbuat? Hanya bertanya saja!"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 30, 'Lalu berpalinglah ia dari padanya kepada orang lain dan menanyakan yang sama. Dan rakyat memberi jawab kepadanya seperti tadi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 31, 'Terdengarlah kepada orang perkataan yang diucapkan oleh Daud, lalu diberitahukanlah kepada Saul. Dan Saul menyuruh memanggil dia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 32, 'Berkatalah Daud kepada Saul: "Janganlah seseorang menjadi tawar hati karena dia; hambamu ini akan pergi melawan orang Filistin itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 33, 'Tetapi Saul berkata kepada Daud: "Tidak mungkin engkau dapat menghadapi orang Filistin itu untuk melawan dia, sebab engkau masih muda, sedang dia sejak dari masa mudanya telah menjadi prajurit."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 34, 'Tetapi Daud berkata kepada Saul: "Hambamu ini biasa menggembalakan kambing domba ayahnya. Apabila datang singa atau beruang, yang menerkam seekor domba dari kawanannya,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 35, 'maka aku mengejarnya, menghajarnya dan melepaskan domba itu dari mulutnya. Kemudian apabila ia berdiri menyerang aku, maka aku menangkap janggutnya lalu menghajarnya dan membunuhnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 36, 'Baik singa maupun beruang telah dihajar oleh hambamu ini. Dan orang Filistin yang tidak bersunat itu, ia akan sama seperti salah satu dari pada binatang itu, karena ia telah mencemooh barisan dari pada Allah yang hidup."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 37, 'Pula kata Daud: "TUHAN yang telah melepaskan aku dari cakar singa dan dari cakar beruang, Dia juga akan melepaskan aku dari tangan orang Filistin itu." Kata Saul kepada Daud: "Pergilah! TUHAN menyertai engkau."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 38, 'Lalu Saul mengenakan baju perangnya kepada Daud, ditaruhnya ketopong tembaga di kepalanya dan dikenakannya baju zirah kepadanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 39, 'Lalu Daud mengikatkan pedangnya di luar baju perangnya, kemudian ia berikhtiar berjalan, sebab belum pernah dicobanya. Maka berkatalah Daud kepada Saul: "Aku tidak dapat berjalan dengan memakai ini, sebab belum pernah aku mencobanya." Kemudian ia menanggalkannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 40, 'Lalu Daud mengambil tongkatnya di tangannya, dipilihnya dari dasar sungai lima batu yang licin dan ditaruhnya dalam kantung gembala yang dibawanya, yakni tempat batu-batu, sedang umbannya dipegangnya di tangannya. Demikianlah ia mendekati orang Filistin itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 41, 'Orang Filistin itu kian dekat menghampiri Daud dan di depannya orang yang membawa perisainya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 42, 'Ketika orang Filistin itu menujukan pandangnya ke arah Daud serta melihat dia, dihinanya Daud itu karena ia masih muda, kemerah-merahan dan elok parasnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 43, 'Orang Filistin itu berkata kepada Daud: "Anjingkah aku, maka engkau mendatangi aku dengan tongkat?" Lalu demi para allahnya orang Filistin itu mengutuki Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 44, 'Pula orang Filistin itu berkata kepada Daud: "Hadapilah aku, maka aku akan memberikan dagingmu kepada burung-burung di udara dan kepada binatang-binatang di padang."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 45, 'Tetapi Daud berkata kepada orang Filistin itu: "Engkau mendatangi aku dengan pedang dan tombak dan lembing, tetapi aku mendatangi engkau dengan nama TUHAN semesta alam, Allah segala barisan Israel yang kautantang itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 46, 'Hari ini juga TUHAN akan menyerahkan engkau ke dalam tanganku dan aku akan mengalahkan engkau dan memenggal kepalamu dari tubuhmu; hari ini juga aku akan memberikan mayatmu dan mayat tentara orang Filistin kepada burung-burung di udara dan kepada binatang-binatang liar, supaya seluruh bumi tahu, bahwa Israel mempunyai Allah,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 47, 'dan supaya segenap jemaah ini tahu, bahwa TUHAN menyelamatkan bukan dengan pedang dan bukan dengan lembing. Sebab di tangan Tuhanlah pertempuran dan Iapun menyerahkan kamu ke dalam tangan kami."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 48, 'Ketika orang Filistin itu bergerak maju untuk menemui Daud, maka segeralah Daud berlari ke barisan musuh untuk menemui orang Filistin itu;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 49, 'lalu Daud memasukkan tangannya dalam kantungnya, diambilnyalah sebuah batu dari dalamnya, diumbannya, maka kenalah dahi orang Filistin itu, sehingga batu itu terbenam ke dalam dahinya, dan terjerumuslah ia dengan mukanya ke tanah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 50, 'Demikianlah Daud mengalahkan orang Filistin itu dengan umban dan batu; ia mengalahkan orang Filistin itu dan membunuhnya, tanpa pedang di tangan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 51, 'Daud berlari mendapatkan orang Filistin itu, lalu berdiri di sebelahnya; diambilnyalah pedangnya, dihunusnya dari sarungnya, lalu menghabisi dia. Dipancungnyalah kepalanya dengan pedang itu. Ketika orang-orang Filistin melihat, bahwa pahlawan mereka telah mati, maka larilah mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 52, 'Maka bangkitlah orang-orang Israel dan Yehuda, mereka bersorak-sorak lalu mengejar orang-orang Filistin sampai dekat Gat dan sampai pintu gerbang Ekron. Dan orang-orang yang terbunuh dari orang Filistin bergelimpangan di jalan ke Saaraim, sampai Gat dan sampai Ekron.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 53, 'Kemudian pulanglah orang Israel dari pemburuan hebat atas orang Filistin, lalu menjarah perkemahan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 54, 'Dan Daud mengambil kepala orang Filistin yang dipancungnya itu dan membawanya ke Yerusalem, tetapi senjata-senjata orang itu ditaruhnya dalam kemahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 55, 'Ketika Saul melihat Daud pergi menemui orang Filistin itu, berkatalah ia kepada Abner, panglima tentaranya: "Anak siapakah orang muda itu, Abner?" Jawab Abner: "Demi tuanku hidup, ya raja, sesungguhnya aku tidak tahu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 56, 'Kemudian raja berkata: "Tanyakanlah, anak siapakah orang muda itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 57, 'Ketika Daud kembali sesudah mengalahkan orang Filistin itu, maka Abner memanggilnya dan membawanya menghadap Saul, sedang kepala orang Filistin itu masih ada di tangannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 17, 58, 'Kata Saul kepadanya: "Anak siapakah engkau, ya orang muda?" Jawab Daud: "Anak hamba tuanku, Isai, orang Betlehem itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 1, 'Ketika Daud habis berbicara dengan Saul, berpadulah jiwa Yonatan dengan jiwa Daud; dan Yonatan mengasihi dia seperti jiwanya sendiri.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 2, 'Pada hari itu Saul membawa dia dan tidak membiarkannya pulang ke rumah ayahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 3, 'Yonatan mengikat perjanjian dengan Daud, karena ia mengasihi dia seperti dirinya sendiri.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 4, 'Yonatan menanggalkan jubah yang dipakainya, dan memberikannya kepada Daud, juga baju perangnya, sampai pedangnya, panahnya dan ikat pinggangnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 5, 'Daud maju berperang dan selalu berhasil ke mana juga Saul menyuruhnya, sehingga Saul mengangkat dia mengepalai para prajurit. Hal ini dipandang baik oleh seluruh rakyat dan juga oleh pegawai-pegawai Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 6, 'Tetapi pada waktu mereka pulang, ketika Daud kembali sesudah mengalahkan orang Filistin itu, keluarlah orang-orang perempuan dari segala kota Israel menyongsong raja Saul sambil menyanyi dan menari-nari dengan memukul rebana, dengan bersukaria dan dengan membunyikan gerincing;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 7, 'dan perempuan yang menari-nari itu menyanyi berbalas-balasan, katanya: "Saul mengalahkan beribu-ribu musuh, tetapi Daud berlaksa-laksa."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 8, 'Lalu bangkitlah amarah Saul dengan sangat; dan perkataan itu menyebalkan hatinya, sebab pikirnya: "Kepada Daud diperhitungkan mereka berlaksa-laksa, tetapi kepadaku diperhitungkannya beribu-ribu; akhir-akhirnya jabatan raja itupun jatuh kepadanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 9, 'Sejak hari itu maka Saul selalu mendengki Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 10, 'Keesokan harinya roh jahat yang dari pada Allah itu berkuasa atas Saul, sehingga ia kerasukan di tengah-tengah rumah, sedang Daud main kecapi seperti sehari-hari. Adapun Saul ada tombak di tangannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 11, 'Saul melemparkan tombak itu, karena pikirnya: "Baiklah aku menancapkan Daud ke dinding." Tetapi Daud mengelakkannya sampai dua kali.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 12, 'Saul menjadi takut kepada Daud, karena TUHAN menyertai Daud, sedang dari pada Saul Ia telah undur.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 13, 'Sebab itu Saul menjauhkan Daud dari dekatnya dan mengangkat dia menjadi kepala pasukan seribu, sehingga ia berada di depan dalam segala gerakan tentara.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 14, 'Daud berhasil di segala perjalanannya, sebab TUHAN menyertai dia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 15, 'Ketika dilihat Saul, bahwa Daud sangat berhasil, makin takutlah ia kepadanya;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 16, 'tetapi seluruh orang Israel dan orang Yehuda mengasihi Daud, karena ia memimpin segala gerakan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 17, 'Berkatalah Saul kepada Daud: "Ini dia anakku perempuan yang tertua, Merab; dia akan kuberikan kepadamu menjadi isterimu, hanya jadilah bagiku seorang yang gagah perkasa dan lakukanlah perang TUHAN." Sebab pikir Saul: "Janganlah tanganku memukul dia, tetapi biarlah ia dipukul oleh tangan orang Filistin."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 18, 'Tetapi Daud berkata kepada Saul: "Siapakah aku dan siapakah sanak saudaraku, kaum ayahku, di antara orang Israel, sehingga aku menjadi menantu raja?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 19, 'Tetapi ketika tiba waktunya untuk memberikan Merab, anak Saul itu, kepada Daud, maka anak perempuan itu diberikan kepada Adriel, orang Mehola, menjadi isterinya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 20, 'Tetapi Mikhal, anak perempuan Saul, jatuh cinta kepada Daud; ketika hal itu diberitahukan kepada Saul, maka iapun menyetujuinya;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 21, 'sebab pikir Saul: "Baiklah Mikhal kuberikan kepadanya; biarlah ia menjadi jerat bagi Daud, dan biarlah tangan orang Filistin memukul dia!" Lalu berkatalah Saul kepada Daud untuk kedua kalinya: "Pada hari ini engkau boleh menjadi menantuku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 22, 'Lagi Saul memerintahkan kepada para pegawainya: "Katakanlah kepada Daud dengan diam-diam, demikian: Sesungguhnya, raja suka kepadamu dan para pegawainya mengasihi engkau; maka sebab itu, jadilah engkau menantu raja."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 23, 'Lalu para pegawai Saul menyampaikan perkataan itu kepada Daud, tetapi Daud menjawab: "Perkara ringankah pada pemandanganmu menjadi menantu raja? Bukankah aku seorang yang miskin dan rendah?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 24, 'Para pegawai Saul memberitahukan kepada raja, katanya: "Demikianlah jawab yang diberi Daud."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 25, 'Kemudian berkatalah Saul: "Beginilah kamu katakan kepada Daud: Raja tidak menghendaki mas kawin selain dari seratus kulit khatan orang Filistin sebagai pembalasan kepada musuh raja." Saul bermaksud untuk menjatuhkan Daud dengan perantaraan orang Filistin.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 26, 'Ketika para pegawainya memberitahukan perkataan itu kepada Daud, maka setujulah Daud menjadi menantu raja. Waktunya belum genap,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 27, 'tetapi Daud sudah bersiap, ia pergi dengan orang-orangnya dan menewaskan dari orang Filistin itu dua ratus orang serta membawa kulit khatan mereka; dan dalam jumlah yang genap diberikan merekalah semuanya itu kepada raja, supaya Daud menjadi menantu raja. Kemudian Saul memberikan Mikhal, anaknya, kepadanya menjadi isterinya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 28, 'Lalu mengertilah Saul dan tahulah ia, bahwa TUHAN menyertai Daud, dan bahwa seluruh orang Israel mengasihi Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 29, 'Maka makin takutlah Saul kepada Daud. Saul tetap menjadi musuh Daud seumur hidupnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 18, 30, 'Apabila raja-raja orang Filistin maju berperang, setiap kali mereka maju berperang, maka Daud lebih berhasil dari semua pegawai Saul, sehingga namanya sangat masyhur.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 1, 'Saul mengatakan kepada Yonatan, anaknya, dan kepada semua pegawainya, bahwa Daud harus dibunuh. Tetapi Yonatan, anak Saul, sangat suka kepada Daud,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 2, 'sehingga Yonatan memberitahukan kepada Daud: "Ayahku Saul berikhtiar untuk membunuh engkau; oleh sebab itu, hati-hatilah besok pagi, duduklah di suatu tempat perlindungan dan bersembunyilah di sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 3, 'Aku akan keluar dan berdiri di sisi ayahku di padang tempatmu itu. Maka aku akan berbicara dengan ayahku perihalmu; aku akan melihat bagaimana keadaannya, lalu memberitahukannya kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 4, 'Lalu Yonatan mengatakan yang baik tentang Daud kepada Saul, ayahnya, katanya: "Janganlah raja berbuat dosa terhadap Daud, hambanya, sebab ia tidak berbuat dosa terhadapmu; bukankah apa yang diperbuatnya sangat baik bagimu!', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 5, 'Ia telah mempertaruhkan nyawanya dan telah mengalahkan orang Filistin itu, dan TUHAN telah memberikan kemenangan yang besar kepada seluruh Israel. Engkau sudah melihatnya dan bersukacita karenanya. Mengapa engkau hendak berbuat dosa terhadap darah orang yang tidak bersalah dengan membunuh Daud tanpa alasan?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 6, 'Saul mendengarkan perkataan Yonatan dan Saul bersumpah: "Demi TUHAN yang hidup, ia tidak akan dibunuh."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 7, 'Lalu Yonatan memanggil Daud dan Yonatan memberitahukan kepadanya segala perkataan itu. Yonatan membawa Daud kepada Saul dan ia bekerja padanya seperti dahulu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 8, 'Ketika perang pecah pula, maka majulah Daud dan berperang melawan orang Filistin; ia menimbulkan kekalahan besar di antara mereka, sehingga mereka melarikan diri dari depannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 9, 'Tetapi roh jahat yang dari pada TUHAN hinggap pada Saul, ketika ia duduk di rumahnya, dengan tombaknya di tangannya; dan Daud sedang main kecapi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 10, 'Lalu Saul berikhtiar menancapkan Daud ke dinding dengan tombaknya, tetapi Daud mengelakkan tikaman Saul, sehingga Saul mengenai dinding dengan tombak itu. Sesudah itu Daud melarikan diri dan luputlah ia pada malam itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 11, 'Kemudian Saul mengirim orang-orang suruhan ke rumah Daud untuk mengamat-amatinya dan untuk membunuh dia pada waktu pagi. Tetapi Mikhal, isteri Daud, memberitahukan kepadanya, demikian: "Jika engkau tidak dapat meluputkan dirimu malam ini, maka besok engkau akan dibunuh."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 12, 'Lalu Mikhal menurunkan Daud dari jendela, ia pergi melarikan diri dan luputlah ia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 13, 'Sesudah itu Mikhal mengambil terafim dan menaruhnya di tempat tidur; ditaruhnya sehelai tenunan bulu kambing di bagian kepala dan ditutupinya dengan selimut.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 14, 'Lalu Saul mengirim orang-orang suruhan untuk mengambil Daud, tetapi perempuan itu berkata: "Ia sakit."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 15, 'Sesudah itu Saul mengirim orang-orang suruhan itu untuk melihat Daud, katanya: "Bawalah dia di atas tempat tidur itu ke mari, supaya ia dibunuh."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 16, 'Lalu masuklah para suruhan itu ke dalam, dan tampaklah ada terafim di tempat tidur dengan sehelai tenunan bulu kambing di bagian kepala.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 17, 'Berkatalah Saul kepada Mikhal: "Mengapa engkau menipu aku demikian itu dan melepas musuhku pergi, sehingga ia luput?" Tetapi jawab Mikhal kepada Saul: "Ia berkata kepadaku: Biarkanlah aku pergi, apa perlunya aku membunuh engkau?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 18, 'Setelah Daud melarikan diri dan luput, sampailah ia kepada Samuel di Rama dan memberitahukan kepadanya segala yang dilakukan Saul kepadanya. Kemudian pergilah ia bersama-sama dengan Samuel dan tinggallah mereka di Nayot.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 19, 'Ketika diberitahukan kepada Saul, demikian: "Ketahuilah, Daud ada di Nayot, dekat Rama,"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 20, 'maka Saul mengirim orang-orang suruhan untuk mengambil Daud. Tetapi orang-orang ini melihat sekumpulan nabi kepenuhan, dengan dikepalai oleh Samuel. Dan Roh Allah hinggap pada orang-orang suruhan Saul, sehingga merekapun kepenuhan seperti nabi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 21, 'Lalu hal itu diberitahukan kepada Saul; ia mengirim orang-orang suruhan yang lain, tetapi orang-orang itupun juga kepenuhan seperti nabi. Saul mengirim sekali lagi orang-orang suruhan, rombongan yang ketiga, dan orang-orang inipun juga kepenuhan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 22, 'Lalu ia sendiri pergi ke Rama. Sesampainya ke dekat perigi besar yang di Sekhu, bertanyalah ia, katanya: "Di mana Samuel dan Daud?" Jawab orang: "Ada di Nayot, dekat Rama."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 23, 'Lalu pergilah ia ke sana, ke Nayot, dekat Rama dan pada diapun hinggaplah Roh Allah, dan selama ia melanjutkan perjalanannya ia kepenuhan seperti nabi, hingga ia sampai ke Nayot dekat Rama.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 19, 24, 'Iapun menanggalkan pakaiannya, dan iapun juga kepenuhan di depan Samuel. Ia rebah terhantar dengan telanjang sehari-harian dan semalam-malaman itu. Itulah sebabnya orang berkata: "Apakah juga Saul termasuk golongan nabi?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 1, 'Maka larilah Daud dari Nayot, dekat Rama; sampailah ia kepada Yonatan, lalu berkata: "Apakah yang telah kuperbuat? Apakah kesalahanku dan apakah dosaku terhadap ayahmu, sehingga ia ingin mencabut nyawaku?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 2, 'Tetapi Yonatan berkata kepadanya: "Jauhlah yang demikian itu! engkau tidak akan mati dibunuh. Ingatlah, ayahku tidak berbuat sesuatu, baik perkara besar maupun perkara kecil, dengan tidak menyatakannya kepadaku. Mengapa ayahku harus menyembunyikan perkara ini kepadaku? Tidak mungkin!"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 3, 'Tetapi Daud menjawab, katanya: "Ayahmu tahu benar, bahwa engkau suka kepadaku. Sebab itu pikirnya: Tidak boleh Yonatan mengetahui hal ini, nanti ia bersusah hati. Namun, demi TUHAN yang hidup dan demi hidupmu, hanya satu langkah jaraknya antara aku dan maut."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 4, 'Yonatan berkata kepada Daud: "Apapun kehendak hatimu, aku akan melakukannya bagimu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 5, 'Lalu kata Daud kepada Yonatan: "Kautahu, besok bulan baru, maka sebenarnya aku harus duduk makan bersama-sama dengan raja. Jika engkau membiarkan aku pergi, maka aku akan bersembunyi di padang sampai lusa petang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 6, 'Apabila ayahmu menanyakan aku, haruslah kaukatakan: Daud telah meminta dengan sangat kepadaku untuk pergi dengan segera ke Betlehem, kotanya, karena di sana ada upacara pengorbanan tahunan bagi segenap kaumnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 7, 'Jika begini dikatakannya: Baiklah! maka hambamu ini selamat. Tetapi jika amarahnya bangkit dengan segera, ketahuilah, bahwa ia telah mengambil keputusan untuk mendatangkan celaka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 8, 'Jika demikian, tunjukkanlah kesetiaanmu kepada hambamu ini, sebab engkau telah mengikat perjanjian di hadapan TUHAN dengan hambamu ini. Tetapi jika ada kesalahan padaku, engkau sendirilah membunuh aku. Mengapa engkau harus menyerahkan aku kepada ayahmu?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 9, 'Tetapi jawab Yonatan: "Jauhlah yang demikian itu! Sebab jika kuketahui dengan pasti, bahwa ayahku telah mengambil keputusan untuk mendatangkan celaka kepadamu, masakan aku tidak memberitahukannya kepadamu?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 10, 'Lalu bertanyalah Daud kepada Yonatan: "Siapakah yang akan memberitahukan kepadaku, apabila ayahmu menjawab engkau dengan keras?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 11, 'Kata Yonatan kepada Daud: "Marilah kita keluar ke padang." Maka keluarlah keduanya ke padang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 12, 'Lalu berkatalah Yonatan kepada Daud: "Demi TUHAN, Allah Israel, besok atau lusa kira-kira waktu ini aku akan memeriksa perasaan ayahku. Apabila baik keadaannya bagi Daud, masakan aku tidak akan menyuruh orang kepadamu dan memberitahukannya kepadamu?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 13, 'Tetapi apabila ayahku memandang baik untuk mendatangkan celaka kepadamu, beginilah kiranya TUHAN menghukum Yonatan, bahkan lebih lagi dari pada itu, sekiranya aku tidak menyatakannya kepadamu dan membiarkan engkau pergi, sehingga engkau dapat berjalan dengan selamat. TUHAN kiranya menyertai engkau, seperti Ia menyertai ayahku dahulu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 14, 'Jika aku masih hidup, bukankah engkau akan menunjukkan kepadaku kasih setia TUHAN? Tetapi jika aku sudah mati,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 15, 'janganlah engkau memutuskan kasih setiamu terhadap keturunanku sampai selamanya. Dan apabila TUHAN melenyapkan setiap orang dari musuh Daud dari muka bumi,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 16, 'janganlah nama Yonatan terhapus dari keturunan Daud, melainkan kiranya TUHAN menuntut balas dari pada musuh-musuh Daud."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 17, 'Dan Yonatan menyuruh Daud sekali lagi bersumpah demi kasihnya kepadanya, sebab ia mengasihi Daud seperti dirinya sendiri.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 18, 'Kemudian berkatalah Yonatan kepadanya: "Besok bulan baru; maka engkau nanti akan ditanyakan, sebab tempat dudukmu akan tinggal kosong.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 19, 'Tetapi lusa engkau pasti akan dicari; engkau harus datang ke tempat engkau bersembunyi pada hari peristiwa itu, dan duduklah dekat bukit batu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 20, 'Maka aku akan memanahkan tiga anak panah ke samping batu itu, seolah-olah aku membidik suatu sasaran.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 21, 'Dan ketahuilah, aku akan menyuruh bujangku: Pergilah mencari anak-anak panah itu. Jika tegas kukatakan kepada bujang itu: Lihat anak-anak panah itu lebih ke mari, ambillah! ?maka datanglah, sebab, demi TUHAN yang hidup, engkau selamat dan tidak ada bahaya apa-apa.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 22, 'Tetapi jika begini kukatakan kepada orang muda itu: Lihat anak-anak panah itu lebih ke sana! ?maka pergilah, sebab TUHAN menyuruh engkau pergi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 23, 'Tentang hal yang kita janjikan itu, antara aku dan engkau, sesungguhnya, TUHAN ada di antara aku dan engkau sampai selamanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 24, 'Sesudah itu bersembunyilah Daud di padang. Ketika bulan baru tiba, duduklah raja pada meja untuk makan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 25, 'Raja duduk di tempatnya seperti biasa, dekat dinding. Yonatan berhadapan dengan dia, Abner duduk di sisi Saul, tetapi tempat Daud tinggal kosong.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 26, 'Dan Saul tidak berkata apa-apa pada hari itu, sebab pikirnya: "Barangkali ada sesuatu yang terjadi kepadanya; mungkin ia tidak tahir; ya, tentu ia tidak tahir."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 27, 'Tetapi pada hari sesudah bulan baru itu, pada hari yang kedua, ketika tempat Daud masih tinggal kosong, bertanyalah Saul kepada Yonatan, anaknya: "Mengapa anak Isai tidak datang makan, baik kemarin maupun hari ini?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 28, 'Jawab Yonatan kepada Saul: "Daud telah meminta dengan sangat kepadaku untuk pergi ke Betlehem,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 29, 'katanya: Biarkanlah aku pergi, sebab ada upacara pengorbanan bagi kaum kami di kota, dan saudara-saudaraku sendirilah yang memanggil aku. Oleh sebab itu, jika engkau mengasihi aku, berilah izin kepadaku untuk menengok saudara-saudaraku. Itulah sebabnya ia tidak datang ke perjamuan raja."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 30, 'Lalu bangkitlah amarah Saul kepada Yonatan, katanya kepadanya: "Anak sundal yang kurang ajar! Bukankah aku tahu, bahwa engkau telah memilih pihak anak Isai dan itu noda bagi kau sendiri dan bagi perut ibumu?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 31, 'Sebab sesungguhnya selama anak Isai itu hidup di muka bumi, engkau dan kerajaanmu tidak akan kokoh. Dan sekarang suruhlah orang memanggil dan membawa dia kepadaku, sebab ia harus mati."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 32, 'Tetapi Yonatan menjawab Saul, ayahnya itu, katanya kepadanya: "Mengapa ia harus dibunuh? Apa yang dilakukannya?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 33, 'Lalu Saul melemparkan tombaknya kepada Yonatan untuk membunuhnya. Maka tahulah Yonatan, bahwa ayahnya telah mengambil keputusan untuk membunuh Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 34, 'Sebab itu Yonatan bangkit dan meninggalkan perjamuan itu dengan kemarahan yang bernyala-nyala. Pada hari yang kedua bulan baru itu ia tidak makan apa-apa, sebab ia bersusah hati karena Daud, sebab ayahnya telah menghina Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 35, 'Pada waktu pagi keluarlah Yonatan ke padang bersama-sama seorang budak kecil sesuai dengan janjinya kepada Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 36, 'Berkatalah ia kepada budaknya: "Larilah, carilah anak-anak panah yang kupanahkan." Baru saja budak itu berlari, maka Yonatan melepaskan sebatang anak panah lewat kepala budak itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 37, 'Ketika budak itu sampai ke tempat letaknya anak panah yang dilepaskan Yonatan itu, maka berserulah Yonatan dari belakang budak itu, katanya: "Bukankah anak panah itu lebih ke sana?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 38, 'Kemudian berserulah Yonatan dari belakang budak itu: "Ayo, cepat, jangan berdiri saja!" Lalu budak Yonatan memungut anak panah itu dan kembali kepada tuannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 39, 'Tetapi budak itu tidak tahu apa-apa, hanya Yonatan dan Daudlah yang mengetahui hal itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 40, 'Sesudah itu Yonatan memberikan senjatanya kepada budak yang menyertai dia, dan berkata kepadanya: "Pergilah, bawalah ke kota."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 41, 'Maka pulanglah budak itu, lalu tampillah Daud dari sebelah bukit batu; ia sujud dengan mukanya ke tanah dan menyembah tiga kali. Mereka bercium-ciuman dan bertangis-tangisan. Akhirnya Daud dapat menahan diri.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 20, 42, 'Kemudian berkatalah Yonatan kepada Daud: "Pergilah dengan selamat; bukankah kita berdua telah bersumpah demi nama TUHAN, demikian: TUHAN akan ada di antara aku dan engkau serta di antara keturunanku dan keturunanmu sampai selamanya." (20-43) Setelah itu bangunlah Daud dan pergi; dan Yonatanpun pulang ke kota.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 1, 'Sampailah Daud ke Nob kepada Ahimelekh, imam itu. Dengan gemetar Ahimelekh pergi menemui Daud dan berkata kepadanya: "Mengapa engkau seorang diri dan tidak ada orang bersama-sama dengan engkau?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 2, 'Jawab Daud kepada imam Ahimelekh: "Raja menugaskan sesuatu kepadaku, katanya kepadaku: Siapapun juga tidak boleh mengetahui sesuatu dari hal yang kusuruh kepadamu dan yang kutugaskan kepadamu ini. Sebab itu orang-orangku telah kusuruh pergi ke suatu tempat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 3, 'Maka sekarang, apa yang ada padamu? Berikanlah kepadaku lima roti atau apapun yang ada."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 4, 'Lalu jawab imam itu kepada Daud: "Tidak ada roti biasa padaku, hanya roti kudus yang ada; asal saja orang-orangmu itu menjaga diri terhadap perempuan."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 5, 'Daud menjawab imam itu, katanya kepadanya: "Memang, kami tidak diperbolehkan bergaul dengan perempuan, seperti sediakala apabila aku maju berperang. Tubuh orang-orangku itu tahir, sekalipun pada perjalanan biasa, apalagi pada hari ini, masing-masing mereka tahir tubuhnya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 6, 'Lalu imam itu memberikan kepadanya roti kudus itu, karena tidak ada roti di sana kecuali roti sajian; roti itu biasa diangkat orang dari hadapan TUHAN, supaya pada hari roti itu diambil, ditaruh lagi roti baru.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 7, 'Maka pada hari itu juga ada di sana salah seorang pegawai Saul, yang dikhususkan melayani TUHAN; namanya Doeg, seorang Edom, pengawas atas gembala-gembala Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 8, 'Berkatalah Daud kepada Ahimelekh: "Tidak adakah padamu di sini tombak atau pedang? Sebab baik pedangku maupun senjataku, tidak dapat kubawa, karena perintah raja itu mendesak."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 9, 'Kemudian berkatalah imam itu: "Pedang Goliat, orang Filistin, yang kaupukul kalah di Lembah Tarbantin, itulah yang ada di sini, terbungkus dalam kain di belakang efod itu. Jika engkau hendak mengambilnya, ambillah; yang lain tidak ada, hanya ini." Kata Daud: "Tidak ada yang seperti itu; berikanlah itu kepadaku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 10, 'Kemudian bersiaplah Daud dan larilah ia pada hari itu juga dari Saul; sampailah ia kepada Akhis, raja kota Gat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 11, 'Pegawai-pegawai Akhis berkata kepada tuannya: "Bukankah ini Daud raja negeri itu? Bukankah tentang dia orang-orang menyanyi berbalas-balasan sambil menari-nari, demikian: Saul mengalahkan beribu-ribu musuh, tetapi Daud berlaksa-laksa?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 12, 'Daud memperhatikan perkataan itu, dan dia menjadi takut sekali kepada Akhis, raja kota Gat itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 13, 'Sebab itu ia berlaku seperti orang yang sakit ingatan di depan mata mereka dan berbuat pura-pura gila di dekat mereka; ia menggores-gores pintu gerbang dan membiarkan ludahnya meleleh ke janggutnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 14, 'Lalu berkatalah Akhis kepada para pegawainya: "Tidakkah kamu lihat, bahwa orang itu gila? Mengapa kamu membawa dia kepadaku?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 21, 15, 'Kekurangan orang gilakah aku, maka kamu bawa orang ini kepadaku supaya ia menunjukkan gilanya dekat aku? Patutkah orang yang demikian masuk ke rumahku?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 1, 'Lalu Daud pergi dari sana dan melarikan diri ke gua Adulam. Ketika saudara-saudaranya dan seluruh keluarganya mendengar hal itu, pergilah mereka ke sana mendapatkan dia.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 2, 'Berhimpunlah juga kepadanya setiap orang yang dalam kesukaran, setiap orang yang dikejar-kejar tukang piutang, setiap orang yang sakit hati, maka ia menjadi pemimpin mereka. Bersama-sama dengan dia ada kira-kira empat ratus orang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 3, 'Dari sana Daud pergi ke Mizpa di Moab dan berkata kepada raja negeri Moab: "Izinkanlah ayahku dan ibuku tinggal padamu, sampai aku tahu, apa yang dilakukan Allah kepadaku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 4, 'Lalu diantarkannyalah mereka kepada raja negeri Moab, dan mereka tinggal bersama dia selama Daud ada di kubu gunung.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 5, 'Tetapi Gad, nabi itu, berkata kepada Daud: "Janganlah tinggal di kubu gunung itu, pergilah dan pulanglah ke tanah Yehuda." Lalu pergilah Daud dan masuk ke hutan Keret.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 6, 'Hal itu terdengar oleh Saul, sebab Daud dan orang-orang yang bersama-sama dengan dia telah diketahui tempatnya. Adapun Saul ada di Gibea, sedang duduk di bawah pohon tamariska di bukit, dengan tombaknya di tangan dan semua pegawainya berdiri di dekatnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 7, 'Lalu berkatalah Saul kepada para pegawainya yang berdiri di dekatnya: "Cobalah dengar, ya orang-orang Benyamin! Apakah anak Isai itu juga akan memberikan kepada kamu sekalian ladang dan kebun anggur, apakah ia akan mengangkat kamu sekalian menjadi kepala atas pasukan seribu dan atas pasukan seratus,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 8, 'sehingga kamu sekalian mengadakan persepakatan melawan aku dan tidak ada seorangpun yang menyatakan kepadaku, bahwa anakku mengikat diri dengan anak Isai itu? Tidak ada seorangpun dari kamu yang cemas karena aku, atau yang menyatakan kepadaku, bahwa anakku telah menghasut pegawaiku melawan aku menjadi penghadang seperti sekarang ini."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 9, 'Lalu menjawablah Doeg, orang Edom itu, yang berdiri dekat para pegawai Saul, katanya: "Telah kulihat, bahwa anak Isai itu datang ke Nob, kepada Ahimelekh bin Ahitub.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 10, 'Ia menanyakan TUHAN bagi Daud dan memberikan bekal kepadanya; juga pedang Goliat, orang Filistin itu, diberikannya kepadanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 11, 'Lalu raja menyuruh memanggil Ahimelekh bin Ahitub, imam itu, bersama-sama dengan seluruh keluarganya, para imam yang di Nob; dan datanglah sekaliannya menghadap raja.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 12, 'Kata Saul: "Cobalah dengar, ya anak Ahitub!" Jawabnya: "Ya, tuanku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 13, 'Kemudian bertanyalah Saul kepadanya: "Mengapa kamu mengadakan persepakatan melawan aku, engkau dengan anak Isai itu, dengan memberikan roti dan pedang kepadanya, menanyakan Allah baginya, sehingga ia bangkit melawan aku menjadi penghadang seperti sekarang ini?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 14, 'Lalu Ahimelekh menjawab raja: "Tetapi siapakah di antara segala pegawaimu yang dapat dipercaya seperti Daud, apalagi ia menantu raja dan kepala para pengawalmu, dan dihormati dalam rumahmu?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 15, 'Bukan ini pertama kali aku menanyakan Allah bagi dia. Sekali-kali tidak! Janganlah kiranya raja melontarkan tuduhan kepada hambamu ini, bahkan kepada seluruh keluargaku, sebab hambamu ini tidak tahu apa-apa tentang semuanya itu, baik tentang perkara kecil maupun perkara besar."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 16, 'Tetapi raja berkata: "Engkau mesti dibunuh, Ahimelekh, engkau dan seluruh keluargamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 17, 'Lalu raja memerintahkan kepada bentara yang berdiri di dekatnya: "Majulah dan bunuhlah para imam TUHAN itu sebab mereka membantu Daud; sebab walaupun mereka tahu, bahwa ia melarikan diri, mereka tidak memberitahukan hal itu kepadaku." Tetapi para pegawai raja tidak mau mengangkat tangannya untuk memarang imam-imam TUHAN itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 18, 'Lalu berkatalah raja kepada Doeg: "Majulah engkau dan paranglah para imam itu." Maka majulah Doeg, orang Edom itu, lalu memarang para imam itu. Ia membunuh pada hari itu delapan puluh lima orang, yang memakai baju efod dari kain lenan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 19, 'Juga penduduk Nob, kota imam itu, dibunuh raja dengan mata pedang; laki-laki maupun perempuan, kanak-kanak maupun anak yang menyusu, pula lembu, keledai dan domba dibunuhnya dengan mata pedang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 20, 'Tetapi seorang anak Ahimelekh bin Ahitub, namanya Abyatar luput; ia melarikan diri menjadi pengikut Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 21, 'Ketika Abyatar memberitahukan kepada Daud, bahwa Saul telah membunuh para imam TUHAN,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 22, 'berkatalah Daud kepada Abyatar: "Memang pada hari itu juga ketika Doeg, orang Edom itu, ada di sana, aku telah tahu, bahwa pasti ia akan memberitahukannya kepada Saul. Akulah sebab utama dari pada kematian seluruh keluargamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 22, 23, 'Tinggallah padaku, janganlah takut; sebab siapa yang ingin mencabut nyawamu, ia juga ingin mencabut nyawaku; di dekatku engkau aman."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 1, 'Diberitahukanlah kepada Daud, begini: "Ketahuilah, orang Filistin berperang melawan kota Kehila dan menjarah tempat-tempat pengirikan."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 2, 'Lalu bertanyalah Daud kepada TUHAN: "Apakah aku akan pergi mengalahkan orang Filistin itu?" Jawab TUHAN kepada Daud: "Pergilah, kalahkanlah orang Filistin itu dan selamatkanlah Kehila."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 3, 'Tetapi orang-orang Daud berkata kepadanya: "Ingatlah, sedangkan di sini di Yehuda kita sudah dalam ketakutan, apalagi kalau kita pergi ke Kehila, melawan barisan perang orang Filistin."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 4, 'Lalu bertanya pulalah Daud kepada TUHAN, maka TUHAN menjawab dia, firman-Nya: "Bersiaplah, pergilah ke Kehila, sebab Aku akan menyerahkan orang Filistin itu ke dalam tanganmu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 5, 'Kemudian pergilah Daud dengan orang-orangnya ke Kehila; ia berperang melawan orang Filistin itu, dihalaunya ternak mereka dan ditimbulkannya kekalahan besar di antara mereka. Demikianlah Daud menyelamatkan penduduk Kehila.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 6, 'Ketika Abyatar bin Ahimelekh melarikan diri kepada Daud ke Kehila, ia turun dengan membawa efod di tangannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 7, 'Kepada Saul diberitahukan, bahwa Daud telah masuk Kehila. Lalu berkatalah Saul: "Allah telah menyerahkan dia ke dalam tanganku, sebab dengan masuk ke dalam kota yang berpintu dan berpalang ia telah mengurung dirinya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 8, 'Maka Saul memanggil seluruh rakyat pergi berperang ke Kehila dan mengepung Daud dengan orang-orangnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 9, 'Ketika diketahui Daud, bahwa Saul berniat jahat terhadap dia, berkatalah ia kepada imam Abyatar: "Bawalah efod itu ke mari."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 10, 'Berkatalah Daud: "TUHAN, Allah Israel, hamba-Mu ini telah mendengar kabar pasti, bahwa Saul berikhtiar untuk datang ke Kehila dan memusnahkan kota ini oleh karena aku.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 11, 'Akan diserahkan oleh warga-warga kota Kehila itukah aku ke dalam tangannya? Akan datangkah Saul seperti yang telah didengar oleh hamba-Mu ini? TUHAN, Allah Israel, beritahukanlah kiranya kepada hamba-Mu ini." Jawab TUHAN: "Ia akan datang."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 12, 'Kemudian bertanyalah Daud: "Akan diserahkan oleh warga-warga kota Kehila itukah aku dengan orang-orangku ke dalam tangan Saul?" Firman TUHAN: "Akan mereka serahkan."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 13, 'Lalu bersiaplah Daud dan orang-orangnya, kira-kira enam ratus orang banyaknya, mereka keluar dari Kehila dan pergi ke mana saja mereka dapat pergi. Apabila kepada Saul diberitahukan, bahwa Daud telah meluputkan diri dari Kehila, maka tidak jadilah ia maju berperang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 14, 'Maka Daud tinggal di padang gurun, di tempat-tempat perlindungan. Ia tinggal di pegunungan, di padang gurun Zif. Dan selama waktu itu Saul mencari dia, tetapi Allah tidak menyerahkan dia ke dalam tangannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 15, 'Daud takut, karena Saul telah keluar dengan maksud mencabut nyawanya. Ketika Daud ada di padang gurun Zif di Koresa,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 16, 'maka bersiaplah Yonatan, anak Saul, lalu pergi kepada Daud di Koresa. Ia menguatkan kepercayaan Daud kepada Allah', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 17, 'dan berkata kepadanya: "Janganlah takut, sebab tangan ayahku Saul tidak akan menangkap engkau; engkau akan menjadi raja atas Israel, dan aku akan menjadi orang kedua di bawahmu. Juga ayahku Saul telah mengetahui yang demikian itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 18, 'Kemudian kedua orang itu mengikat perjanjian di hadapan TUHAN. Dan Daud tinggal di Koresa, tetapi Yonatan pulang ke rumahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 19, 'Tetapi beberapa orang Zif pergi menghadap Saul di Gibea dan berkata: "Daud menyembunyikan diri dekat kami di kubu-kubu gunung dekat Koresa, di bukit Hakhila, di sebelah selatan padang belantara.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 20, 'Oleh sebab itu, jika tuanku raja berkenan datang, silakanlah datang; tanggungan kamilah untuk menyerahkan dia ke dalam tangan raja."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 21, 'Berkatalah Saul: "Diberkatilah kiranya kamu oleh TUHAN, karena kamu menunjukkan sayangmu kepadaku.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 22, 'Baiklah pergi, carilah kepastian lagi, berusahalah mengetahui di mana ia berada dan siapa yang telah melihat dia di sana; sebab telah dikatakan orang kepadaku, bahwa ia sangat cerdik.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 23, 'Berusahalah mengetahui segala tempat persembunyiannya. Kemudian datanglah kembali kepadaku dengan kabar yang pasti; dan aku akan pergi bersama-sama dengan kamu. Sesungguhnya, jika ia ada di dalam negeri, maka aku akan meneliti dia di antara segala ribuan orang Yehuda."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 24, 'Lalu berkemaslah mereka pergi ke Zif, mendahului Saul. Daud dan orang-orangnya ada di padang gurun Maon, di dataran di sebelah selatan padang belantara.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 25, 'Ketika Saul dengan orang-orangnya pergi mencari Daud, diberitahukanlah hal itu kepada Daud, lalu pergilah ia ke gunung batu dan tinggal di padang gurun Maon. Saul mendengar hal itu, lalu mengejar Daud di padang gurun Maon;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 26, 'Saul berjalan dari sisi gunung sebelah sini dan Daud dengan orang-orangnya dari sisi gunung sebelah sana. Daud cepat-cepat mengelakkan Saul; tetapi Saul dengan orang-orangnya sudah hampir mengepung Daud serta orang-orangnya untuk menangkap mereka,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 27, 'ketika seorang suruhan datang kepada Saul dengan pesan: "Segeralah undur, sebab orang Filistin telah menyerbu negeri."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 28, 'Maka berhentilah Saul mengejar Daud dan pergi menghadapi orang Filistin. Itulah sebabnya orang menyebut tempat itu: Gunung Batu Keluputan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 23, 29, '(24-1) Daud pergi dari sana, lalu tinggal di kubu-kubu gunung di En-Gedi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 1, '(24-2) Ketika Saul pulang sesudah memburu orang Filistin itu, diberitahukanlah kepadanya, demikian: "Ketahuilah, Daud ada di padang gurun En-Gedi."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 2, '(24-3) Kemudian Saul mengambil tiga ribu orang yang terpilih dari seluruh orang Israel, lalu pergi mencari Daud dan orang-orangnya di gunung batu Kambing Hutan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 3, '(24-4) Ia sampai ke kandang-kandang domba di tepi jalan. Di sana ada gua dan Saul masuk ke dalamnya untuk membuang hajat, tetapi Daud dan orang-orangnya duduk di bagian belakang gua itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 4, '(24-5) Lalu berkatalah orang-orangnya kepada Daud: "Telah tiba hari yang dikatakan TUHAN kepadamu: Sesungguhnya, Aku menyerahkan musuhmu ke dalam tanganmu, maka perbuatlah kepadanya apa yang kaupandang baik." Maka Daud bangun, lalu memotong punca jubah Saul dengan diam-diam.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 5, '(24-6) Kemudian berdebar-debarlah hati Daud, karena ia telah memotong punca Saul;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 6, '(24-7) lalu berkatalah ia kepada orang-orangnya: "Dijauhkan Tuhanlah kiranya dari padaku untuk melakukan hal yang demikian kepada tuanku, kepada orang yang diurapi TUHAN, yakni menjamah dia, sebab dialah orang yang diurapi TUHAN."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 7, '(24-8) Dan Daud mencegah orang-orangnya dengan perkataan itu; ia tidak mengizinkan mereka bangkit menyerang Saul. Sementara itu Saul telah bangun meninggalkan gua itu hendak melanjutkan perjalanannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 8, '(24-9) Kemudian bangunlah Daud, ia keluar dari dalam gua itu dan berseru kepada Saul dari belakang, katanya: "Tuanku raja!" Saul menoleh ke belakang, lalu Daud berlutut dengan mukanya ke tanah dan sujud menyembah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 9, '(24-10) Lalu berkatalah Daud kepada Saul: "Mengapa engkau mendengarkan perkataan orang-orang yang mengatakan: Sesungguhnya Daud mengikhtiarkan celakamu?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 10, '(24-11) Ketahuilah, pada hari ini matamu sendiri melihat, bahwa TUHAN sekarang menyerahkan engkau ke dalam tanganku dalam gua itu; ada orang yang telah menyuruh aku membunuh engkau, tetapi aku merasa sayang kepadamu karena pikirku: Aku tidak akan menjamah tuanku itu, sebab dialah orang yang diurapi TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 11, '(24-12) Lihatlah dahulu, ayahku, lihatlah kiranya punca jubahmu dalam tanganku ini! Sebab dari kenyataan bahwa aku memotong punca jubahmu dengan tidak membunuh engkau, dapatlah kauketahui dan kaulihat, bahwa tanganku bersih dari pada kejahatan dan pengkhianatan, dan bahwa aku tidak berbuat dosa terhadap engkau, walaupun engkau ini mengejar-ngejar aku untuk mencabut nyawaku.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 12, '(24-13) TUHAN kiranya menjadi hakim di antara aku dan engkau, TUHAN kiranya membalaskan aku kepadamu, tetapi tanganku tidak akan memukul engkau;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 13, '(24-14) seperti peribahasa orang tua-tua mengatakan: Dari orang fasik timbul kefasikan. Tetapi tanganku tidak akan memukul engkau.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 14, '(24-15) Terhadap siapakah raja Israel keluar berperang? Siapakah yang kaukejar? Anjing mati! Seekor kutu saja!', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 15, '(24-16) Sebab itu TUHAN kiranya menjadi hakim yang memutuskan antara aku dan engkau; Dia kiranya memperhatikannya, memperjuangkan perkaraku dan memberi keadilan kepadaku dengan melepaskan aku dari tanganmu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 16, '(24-17) Setelah Daud selesai menyampaikan perkataan itu kepada Saul, berkatalah Saul: "Suaramukah itu, ya anakku Daud?" Sesudah itu dengan suara nyaring menangislah Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 17, '(24-18) Katanya kepada Daud: "Engkau lebih benar dari pada aku, sebab engkau telah melakukan yang baik kepadaku, padahal aku melakukan yang jahat kepadamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 18, '(24-19) Telah kautunjukkan pada hari ini, betapa engkau telah melakukan yang baik kepadaku: walaupun TUHAN telah menyerahkan aku ke dalam tanganmu, engkau tidak membunuh aku.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 19, '(24-20) Apabila seseorang mendapat musuhnya, masakan dilepaskannya dia berjalan dengan selamat? TUHAN kiranya membalaskan kepadamu kebaikan ganti apa yang kaulakukan kepadaku pada hari ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 20, '(24-21) Oleh karena itu, sesungguhnya aku tahu, bahwa engkau pasti menjadi raja dan jabatan raja Israel akan tetap kokoh dalam tanganmu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 21, '(24-22) Oleh sebab itu, bersumpahlah kepadaku demi TUHAN, bahwa engkau tidak akan melenyapkan keturunanku dan tidak akan menghapuskan namaku dari kaum keluargaku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 24, 22, '(24-23) Lalu bersumpahlah Daud kepada Saul. Kemudian pulanglah Saul ke rumahnya, sedang Daud dan orang-orangnya pergi ke kubu gunung.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 1, 'Dan matilah Samuel; seluruh orang Israel berkumpul meratapi dia dan menguburkan dia di rumahnya di Rama. Dan Daud berkemas, lalu pergi ke padang gurun Paran.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 2, 'Ketika itu ada seorang laki-laki di Maon, yang mempunyai perusahaan di Karmel. Orang itu sangat kaya: ia mempunyai tiga ribu ekor domba dan seribu ekor kambing. Ia ada di Karmel pada pengguntingan bulu domba-dombanya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 3, 'Nama orang itu Nabal dan nama isterinya Abigail. Perempuan itu bijak dan cantik, tetapi laki-laki itu kasar dan jahat kelakuannya. Ia seorang keturunan Kaleb.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 4, 'Ketika didengar Daud di padang gurun, bahwa Nabal sedang menggunting bulu domba-dombanya,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 5, 'maka Daud menyuruh sepuluh orang dan kepada orang-orang itu Daud berkata: "Pergilah ke Karmel dan temuilah Nabal. Tanyakanlah keselamatannya atas namaku', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 6, 'dan sampaikanlah salam ini kepadanya: Selamat! Selamatlah engkau, selamatlah keluargamu, selamatlah segala yang ada padamu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 7, 'Baru-baru ini aku mendengar bahwa engkau mengadakan pengguntingan bulu domba. Adapun gembala-gembalamu yang ada dengan kami, tidak kami ganggu dan tidak ada sesuatu yang hilang dari pada mereka selama mereka ada di Karmel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 8, 'Tanyakanlah kepada orang-orangmu, mereka tentu akan memberitahukan kepadamu. Sebab itu biarlah orang-orang ini mendapat belas kasihanmu; bukankah kami ini datang pada hari raya? Berikanlah kepada hamba-hambamu ini dan kepada anakmu Daud apa yang ada padamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 9, 'Ketika orang-orang Daud sampai ke sana, berkatalah mereka kepada Nabal atas nama Daud tepat seperti yang dikatakan kepada mereka, kemudian mereka menanti.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 10, 'Tetapi Nabal menjawab anak buah Daud itu, katanya: "Siapakah Daud? Siapakah anak Isai itu? Pada waktu sekarang ini ada banyak hamba-hamba yang lari dari tuannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 11, 'Masakan aku mengambil rotiku, air minumku dan hewan bantaian yang kubantai bagi orang-orang pengguntingku untuk memberikannya kepada orang-orang yang aku tidak tahu dari mana mereka datang?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 12, 'Lalu orang-orang Daud itu berbalik pulang dan setelah sampai, mereka memberitahukan kepadanya tepat seperti yang dikatakan kepada mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 13, 'Kemudian berkatalah Daud kepada orang-orangnya: "Kamu masing-masing, sandanglah pedang!" Lalu mereka masing-masing menyandang pedangnya; Daud sendiripun menyandang pedangnya. Sesudah itu kira-kira empat ratus orang maju mengikuti Daud, sedang dua ratus orang tinggal menjaga barang-barang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 14, 'Tetapi kepada Abigail, isteri Nabal, telah diberitahukan oleh salah seorang bujangnya, katanya: "Ketahuilah, Daud menyuruh orang dari padang gurun untuk memberi salam kepada tuan kita, tetapi ia memaki-maki mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 15, 'Padahal orang-orang itu sangat baik kepada kami; mereka tidak mengganggu kami dan kami tidak kehilangan apa-apa selama kami lalu-lalang di dekat mereka, ketika kami ada di ladang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 16, 'Mereka seperti pagar tembok sekeliling kami siang malam, selama kami menggembalakan domba-domba di dekat mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 17, 'Oleh sebab itu, pikirkanlah dan pertimbangkanlah apa yang harus kauperbuat, sebab telah diputuskan bahwa celaka akan didatangkan kepada tuan kita dan kepada seisi rumahnya, dan ia seorang yang dursila, sehingga orang tidak dapat berbicara dengan dia."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 18, 'Lalu segeralah Abigail mengambil dua ratus roti, dua buyung anggur, lima domba yang telah diolah, lima sukat bertih gandum, seratus buah kue kismis dan dua ratus kue ara, dimuatnyalah semuanya ke atas keledai,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 19, 'lalu berkata kepada bujang-bujangnya: "Berjalanlah mendahului aku; aku segera menyusul kamu." Tetapi Nabal, suaminya, tidaklah diberitahunya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 20, 'Ketika perempuan itu dengan menunggang keledainya, turun dengan terlindung oleh gunung, tampaklah Daud dan orang-orangnya turun ke arahnya, dan perempuan itu bertemu dengan mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 21, 'Daud tadinya telah berkata: "Sia-sialah aku melindungi segala kepunyaan orang ini di padang gurun, sehingga tidak ada sesuatupun yang hilang dari segala kepunyaannya; ia membalas kebaikanku dengan kejahatan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 22, 'Beginilah kiranya Allah menghukum Daud, bahkan lebih lagi dari pada itu, jika kutinggalkan hidup sampai pagi seorang laki-laki sajapun dari semua yang ada padanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 23, 'Ketika Abigail melihat Daud, segeralah ia turun dari atas keledainya, lalu sujud menyembah di depan Daud dengan mukanya sampai ke tanah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 24, 'Ia sujud pada kaki Daud serta berkata: "Aku sajalah, ya tuanku, yang menanggung kesalahan itu. Izinkanlah hambamu ini berbicara kepadamu, dan dengarkanlah perkataan hambamu ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 25, 'Janganlah kiranya tuanku mengindahkan Nabal, orang yang dursila itu, sebab seperti namanya demikianlah ia: Nabal namanya dan bebal orangnya. Tetapi aku, hambamu ini, tidak melihat orang-orang yang tuanku suruh.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 26, 'Oleh sebab itu, tuanku, demi TUHAN yang hidup dan demi hidupmu yang dicegah TUHAN dari pada melakukan hutang darah dan dari pada bertindak sendiri dalam mencari keadilan, biarlah menjadi sama seperti Nabal musuhmu dan orang yang bermaksud jahat terhadap tuanku!', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 27, 'Oleh sebab itu, pemberian yang dibawa kepada tuanku oleh budakmu ini, biarlah diberikan kepada orang-orang yang mengikuti tuanku.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 28, 'Ampunilah kiranya kecerobohan hambamu ini, sebab pastilah TUHAN akan membangun bagi tuanku keturunan yang teguh, karena tuanku ini melakukan perang TUHAN dan tidak ada yang jahat terdapat padamu selama hidupmu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 29, 'Jika sekiranya ada seorang bangkit mengejar engkau dan ingin mencabut nyawamu, maka nyawa tuanku akan terbungkus dalam bungkusan tempat orang-orang hidup pada TUHAN, Allahmu, tetapi nyawa para musuhmu akan diumbankan-Nya dari dalam salang umban.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 30, 'Apabila TUHAN melakukan kepada tuanku sesuai dengan segala kebaikan yang difirmankan-Nya kepadamu dan menunjuk engkau menjadi raja atas Israel,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 31, 'maka tak usahlah tuanku bersusah hati dan menyesal karena menumpahkan darah tanpa alasan, dan karena tuanku bertindak sendiri dalam mencari keadilan. Dan apabila TUHAN berbuat baik kepada tuanku, ingatlah kepada hambamu ini."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 32, 'Lalu berkatalah Daud kepada Abigail: "Terpujilah TUHAN, Allah Israel, yang mengutus engkau menemui aku pada hari ini;', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 33, 'terpujilah kebijakanmu dan terpujilah engkau sendiri, bahwa engkau pada hari ini menahan aku dari pada melakukan hutang darah dan dari pada bertindak sendiri dalam mencari keadilan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 34, 'Tetapi demi TUHAN, Allah Israel yang hidup, yang mencegah aku dari pada berbuat jahat kepadamu?jika engkau tadinya tidak segera datang menemui aku, pasti tidak akan ada seorang laki-lakipun tinggal hidup pada Nabal sampai fajar menyingsing."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 35, 'Lalu Daud menerima dari perempuan itu apa yang dibawanya untuk dia, dan berkata kepadanya: "Pulanglah dengan selamat ke rumahmu; lihatlah, aku mendengarkan perkataanmu dan menerima permintaanmu dengan baik."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 36, 'Sampailah Abigail kepada Nabal dan tampaklah, Nabal mengadakan perjamuan di rumahnya, seperti perjamuan raja-raja. Nabal riang gembira dan mabuk sekali. Sebab itu tidaklah diceriterakan perempuan itu sepatah katapun kepadanya, sampai fajar menyingsing.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 37, 'Tetapi pada waktu pagi, ketika sudah hilang mabuk Nabal itu, diceriterakanlah kepadanya oleh isterinya segala perkara itu. Lalu terhentilah jantungnya dalam dada dan ia membatu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 38, 'Dan kira-kira sepuluh hari sesudah itu TUHAN memukul Nabal, sehingga ia mati.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 39, 'Ketika didengar Daud, bahwa Nabal telah mati, berkatalah ia: "Terpujilah TUHAN, yang membela aku dalam perkara penghinaan Nabal terhadap aku dan yang mencegah hamba-Nya dari pada berbuat jahat. TUHAN telah membalikkan kejahatan Nabal ke atas kepalanya sendiri." Kemudian Daud menyuruh orang untuk berbicara dengan Abigail tentang mengambil dia menjadi isterinya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 40, 'Para hamba Daud datang kepada Abigail di Karmel dan berkata kepadanya, demikian: "Daud menyuruh kami kepadamu untuk mengambil engkau menjadi isterinya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 41, 'Lalu bangkitlah perempuan itu berdiri, sujudlah ia menyembah dengan mukanya ke tanah sambil berkata: "Sesungguhnya, hambamu ini ingin menjadi budak yang membasuh kaki para hamba tuanku itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 42, 'Kemudian berkemaslah Abigail dengan segera; ia menunggang keledainya, dengan diiringi lima orang pelayan perempuan. Ia mengikuti suruhan Daud itu dan menjadi isteri Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 43, 'Juga Ahinoam dari Yizreel telah diambil Daud menjadi isterinya; kedua perempuan itu menjadi isterinya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 25, 44, 'Tetapi Saul telah memberikan Mikhal, anaknya perempuan, isteri Daud, kepada Palti bin Lais, yang dari Galim itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 1, 'Datanglah orang Zif kepada Saul di Gibea serta berkata: "Daud menyembunyikan diri di bukit Hakhila di padang belantara."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 2, 'Lalu berkemaslah Saul dan turun ke padang gurun Zif dengan tiga ribu orang yang terpilih dari orang Israel untuk mencari Daud di padang gurun Zif.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 3, 'Berkemahlah Saul di bukit Hakhila yang di tepi jalan di padang belantara, sedang Daud tinggal di padang gurun. Ketika diketahui Daud, bahwa Saul datang mengikuti dia ke padang gurun,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 4, 'disuruhnyalah pengintai-pengintai, maka diketahuinyalah, bahwa Saul benar-benar datang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 5, 'Berkemaslah Daud, lalu sampai ke tempat Saul berkemah. Waktu Daud melihat tempat Saul berbaring dengan Abner bin Ner, panglima tentaranya, ?Saul berbaring di tengah-tengah perkemahan, sedang rakyat berkemah sekelilingnya?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 6, 'berbicaralah Daud kepada Ahimelekh, orang Het itu, dan kepada Abisai, anak Zeruya, saudara Yoab, katanya: "Siapa turun bersama-sama dengan aku kepada Saul ke tempat perkemahan itu?" Jawab Abisai: "Aku turun bersama-sama dengan engkau."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 7, 'Datanglah Daud dengan Abisai kepada rakyat itu pada waktu malam, dan tampaklah di sana Saul berbaring tidur di tengah-tengah perkemahan, dengan tombaknya terpancung di tanah pada sebelah kepalanya, sedang Abner dan rakyat itu berbaring sekelilingnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 8, 'Lalu berkatalah Abisai kepada Daud: "Pada hari ini Allah telah menyerahkan musuhmu ke dalam tanganmu, oleh sebab itu izinkanlah kiranya aku menancapkan dia ke tanah dengan tombak ini, dengan satu tikaman saja, tidak usah dia kutancapkan dua kali."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 9, 'Tetapi kata Daud kepada Abisai: "Jangan musnahkan dia, sebab siapakah yang dapat menjamah orang yang diurapi TUHAN, dan bebas dari hukuman?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 10, 'Lagi kata Daud: "Demi TUHAN yang hidup, niscaya TUHAN akan membunuh dia: entah karena sampai ajalnya dan ia mati, entah karena ia pergi berperang dan hilang lenyap di sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 11, 'Kiranya TUHAN menjauhkan dari padaku untuk menjamah orang yang diurapi TUHAN. Ambillah sekarang tombak yang ada di sebelah kepalanya dan kendi itu, dan marilah kita pergi."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 12, 'Kemudian Daud mengambil tombak dan kendi itu dari sebelah kepala Saul, lalu mereka pergi. Tidak ada yang melihatnya, tidak ada yang mengetahuinya, tidak ada yang terbangun, sebab sekaliannya tidur, karena TUHAN membuat mereka tidur nyenyak.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 13, 'Setelah Daud sampai ke seberang, berdirilah ia jauh-jauh di puncak gunung, sehingga ada jarak yang besar antara mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 14, 'Dan berserulah Daud kepada tentara itu dan kepada Abner bin Ner, katanya: "Tidakkah engkau menjawab, Abner?" Maka jawab Abner, katanya: "Siapakah engkau ini yang berseru-seru kepada raja?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 15, 'Kemudian berkatalah Daud kepada Abner: "Apakah engkau ini bukan laki-laki? Siapakah yang seperti engkau di antara orang Israel? Mengapa engkau tidak mengawal tuanmu raja? Sebab ada seorang dari rakyat yang datang untuk memusnahkan raja, tuanmu itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 16, 'Tidak baik hal yang kauperbuat itu. Demi TUHAN yang hidup, kamu ini harus mati, karena kamu tidak mengawal tuanmu, orang yang diurapi TUHAN itu. Sekarang, lihatlah, di mana tombak raja dan kendi yang ada di sebelah kepalanya?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 17, 'Saul mengenal suara Daud, lalu ia berkata: "Suaramukah itu, anakku Daud?" Jawab Daud: "Suaraku, tuanku raja."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 18, 'Lalu berkatalah ia: "Mengapa pula tuanku mengejar hambanya ini? Apa yang telah kuperbuat? Apakah kejahatan yang melekat pada tanganku?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 19, 'Oleh sebab itu, kiranya tuanku raja mendengarkan perkataan hambanya ini. Jika TUHAN yang membujuk engkau melawan aku, maka biarlah Ia mencium bau korban persembahan; tetapi jika itu anak-anak manusia, terkutuklah mereka di hadapan TUHAN, karena mereka sekarang mengusir aku, sehingga aku tidak mendapat bagian dari pada milik TUHAN, dengan berkata: Pergilah, beribadahlah kepada allah lain.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 20, 'Sebab itu, janganlah kiranya darahku tertumpah ke tanah, jauh dari hadapan TUHAN. Sebab raja Israel keluar untuk mencabut nyawaku, seperti orang memburu seekor ayam hutan di gunung-gunung."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 21, 'Lalu berkatalah Saul: "Aku telah berbuat dosa, pulanglah, anakku Daud, sebab aku tidak akan berbuat jahat lagi kepadamu, karena nyawaku pada hari ini berharga di matamu. Sesungguhnya, perbuatanku itu bodoh dan aku sesat sama sekali."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 22, 'Tetapi Daud menjawab: "Inilah tombak itu, ya tuanku raja! Baiklah salah seorang dari orang-orangmu menyeberang untuk mengambilnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 23, 'TUHAN akan membalas kebenaran dan kesetiaan setiap orang, sebab TUHAN menyerahkan engkau pada hari ini ke dalam tanganku, tetapi aku tidak mau menjamah orang yang diurapi TUHAN.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 24, 'Dan sesungguhnya, seperti nyawamu pada hari ini berharga di mataku, demikianlah hendaknya nyawaku berharga di mata TUHAN, dan hendaknya Ia melepaskan aku dari segala kesusahan."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 26, 25, 'Lalu berkatalah Saul kepada Daud: "Diberkatilah kiranya engkau, anakku Daud. Apa juapun yang kauperbuat, pastilah engkau sanggup melakukannya." Lalu pergilah Daud meneruskan perjalanannya dan pulanglah Saul ke tempatnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 1, 'Tetapi Daud berpikir dalam hatinya: "Bagaimanapun juga pada suatu hari aku akan binasa oleh tangan Saul. Jadi tidak ada yang lebih baik bagiku selain meluputkan diri dengan segera ke negeri orang Filistin; maka tidak ada harapan bagi Saul untuk mencari aku lagi di seluruh daerah Israel dan aku akan terluput dari tangannya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 2, 'Bersiaplah Daud, lalu berjalan ke sana, ia dan keenam ratus orang yang bersama-sama dengan dia itu, kepada Akhis bin Maokh, raja kota Gat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 3, 'Daud dan semua orangnya menetap pada Akhis di Gat, masing-masing dengan rumah tangganya; Daud dengan kedua orang isterinya, yakni Ahinoam, perempuan Yizreel, dan Abigail, bekas isteri Nabal, perempuan Karmel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 4, 'Setelah diberitahukan kepada Saul, bahwa Daud telah melarikan diri ke Gat, ia tidak lagi mencarinya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 5, 'Berkatalah Daud kepada Akhis: "Jika kiranya aku mendapat belas kasihanmu, biarlah diberikan kepadaku tempat di salah satu kota di tanah datar, supaya aku tinggal di sana. Mengapa hambamu ini tinggal padamu di kota kerajaan ini?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 6, 'Maka pada hari itu Akhis memberikan Ziklag kepadanya; itulah sebabnya Ziklag menjadi kepunyaan raja-raja Yehuda sampai sekarang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 7, 'Dan lamanya Daud tinggal di daerah orang Filistin adalah satu tahun empat bulan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 8, 'Maka Daud dan orang-orangnya bergerak maju dan menyerbu orang Gesur, orang Girzi dan orang Amalek; sebab orang-orang inilah penduduk negeri itu yang membentang dari Telam ke arah Syur sampai tanah Mesir.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 9, 'Apabila Daud memusnahkan negeri itu, seorangpun tidak dibiarkannya hidup, baik laki-laki maupun perempuan; ia merampas kambing domba, lembu, keledai, unta dan pakaian, kemudian pulanglah ia dan kembali kepada Akhis.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 10, 'Jika Akhis bertanya: "Di mana kamu menyerbu pada hari ini?" maka jawab Daud: "Di Tanah Negeb Yehuda," atau: "Di Tanah Negeb orang Yerahmeel," atau: "Di Tanah Negeb orang Keni."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 11, 'Daud tidak membiarkan hidup seorangpun, baik laki-laki maupun perempuan, untuk dibawa ke Gat, sebab pikirnya: "Jangan-jangan mereka mengabarkan tentang kami, dengan berkata: Beginilah dilakukan Daud." Itulah kebiasaannya, selama ia tinggal di daerah orang Filistin.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 27, 12, 'Tetapi Akhis mempercayai Daud, sebab pikirnya: "Tentulah ia telah membuat diri dibenci di antara orang Israel, bangsanya; ia akan menjadi hambaku sampai selamanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 1, 'Pada waktu itu orang Filistin mengerahkan tentaranya untuk berperang melawan orang Israel. Lalu berkatalah Akhis kepada Daud: "Ketahuilah baik-baik, bahwa engkau beserta orang-orangmu harus maju berperang bersama-sama dengan aku dalam tentara."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 2, 'Jawab Daud kepada Akhis: "Baik, engkau akan tahu, apa yang dapat diperbuat hambamu ini." Lalu Akhis berkata kepada Daud: "Sebab itu aku mengangkat engkau menjadi pengawalku sendiri sampai selamanya."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 3, 'Adapun Samuel sudah mati. Seluruh orang Israel sudah meratapi dia dan mereka telah menguburkan dia di Rama, di kotanya. Dan Saul telah menyingkirkan dari dalam negeri para pemanggil arwah dan roh peramal.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 4, 'Orang Filistin itu berkumpul, lalu bergerak maju, dan berkemah dekat Sunem. Saul mengumpulkan seluruh orang Israel, lalu mereka berkemah di Gilboa.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 5, 'Ketika Saul melihat tentara Filistin itu, maka takutlah ia dan hatinya sangat gemetar.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 6, 'Dan Saul bertanya kepada TUHAN, tetapi TUHAN tidak menjawab dia, baik dengan mimpi, baik dengan Urim, baik dengan perantaraan para nabi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 7, 'Lalu berkatalah Saul kepada para pegawainya: "Carilah bagiku seorang perempuan yang sanggup memanggil arwah; maka aku hendak pergi kepadanya dan meminta petunjuk kepadanya." Para pegawainya menjawab dia: "Di En-Dor ada seorang perempuan yang sanggup memanggil arwah."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 8, 'Lalu menyamarlah Saul, ia mengenakan pakaian lain dan pergilah ia dengan dua orang. Ketika mereka pada waktu malam sampai kepada perempuan itu, berkatalah Saul: "Cobalah engkau menenung bagiku dengan perantaraan arwah, dan panggillah supaya muncul kepadaku orang yang akan kusebut kepadamu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 9, 'Tetapi perempuan itu menjawabnya: "Tentu engkau mengetahui apa yang diperbuat Saul, bahwa ia telah melenyapkan dari dalam negeri para pemanggil arwah dan roh peramal. Mengapa engkau memasang jerat terhadap nyawaku untuk membunuh aku?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 10, 'Lalu bersumpahlah Saul kepadanya demi TUHAN, katanya: "Demi TUHAN yang hidup, tidak akan ada kesalahan tertimpa kepadamu karena perkara ini."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 11, 'Sesudah itu bertanyalah perempuan itu: "Siapakah yang harus kupanggil supaya muncul kepadamu?" Jawabnya: "Panggillah Samuel supaya muncul kepadaku."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 12, 'Ketika perempuan itu melihat Samuel, berteriaklah ia dengan suara nyaring. Lalu perempuan itu berkata kepada Saul, demikian: "Mengapa engkau menipu aku? Engkau sendirilah Saul!"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 13, 'Maka berbicaralah raja kepadanya: "Janganlah takut; tetapi apakah yang kaulihat?" Perempuan itu menjawab Saul: "Aku melihat sesuatu yang ilahi muncul dari dalam bumi."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 14, 'Kemudian bertanyalah ia kepada perempuan itu: "Bagaimana rupanya?" Jawabnya: "Ada seorang tua muncul, berselubungkan jubah." Maka tahulah Saul, bahwa itulah Samuel, lalu berlututlah ia dengan mukanya sampai ke tanah dan sujud menyembah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 15, 'Sesudah itu berbicaralah Samuel kepada Saul: "Mengapa engkau mengganggu aku dengan memanggil aku muncul?" Kata Saul: "Aku sangat dalam keadaan terjepit: orang Filistin berperang melawan aku, dan Allah telah undur dari padaku. Ia tidak menjawab aku lagi, baik dengan perantaraan nabi maupun dengan mimpi. Sebab itu aku memanggil engkau, supaya engkau memberitahukan kepadaku, apa yang harus kuperbuat."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 16, 'Lalu berbicaralah Samuel: "Mengapa engkau bertanya kepadaku, padahal TUHAN telah undur dari padamu dan telah menjadi musuhmu?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 17, 'TUHAN telah melakukan kepadamu seperti yang difirmankan-Nya dengan perantaraanku, yakni TUHAN telah mengoyakkan kerajaan dari tanganmu dan telah memberikannya kepada orang lain, kepada Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 18, 'Karena engkau tidak mendengarkan suara TUHAN dan tidak melaksanakan murka-Nya yang bernyala-nyala itu atas Amalek, itulah sebabnya TUHAN melakukan hal itu kepadamu pada hari ini.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 19, 'Juga orang Israel bersama-sama dengan engkau akan diserahkan TUHAN ke dalam tangan orang Filistin, dan besok engkau serta anak-anakmu sudah ada bersama-sama dengan daku. Juga tentara Israel akan diserahkan TUHAN ke dalam tangan orang Filistin."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 20, 'Pada saat itu juga rebahlah Saul memanjang ke tanah sebab ia sangat ketakutan oleh karena perkataan Samuel itu. Juga tidak ada lagi kekuatannya, karena sehari semalam itu ia tidak makan apa-apa.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 21, 'Perempuan itu mendekati Saul lalu melihat, bahwa Saul sangat terkejut. Kemudian berkatalah perempuan itu kepadanya: "Lihat, budakmu ini telah mendengarkan permintaanmu; aku telah mempertaruhkan nyawaku dan mendengarkan perkataan yang kaukatakan kepadaku.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 22, 'Oleh sebab itu, kiranya engkaupun mendengarkan permintaan budakmu ini. Izinkanlah aku menyajikan kepadamu sepotong roti; makanlah, supaya ada kekuatanmu, apabila engkau berjalan pula."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 23, 'Tetapi Saul menolak dan berkata: "Aku tidak mau makan." Tetapi ketika para pegawainya serta perempuan itu juga mendesak, maka didengarkannyalah permintaan mereka, lalu bangkitlah ia dari tanah dan duduk di balai-balai.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 24, 'Perempuan itu mempunyai seekor anak lembu tambun di rumahnya maka segeralah ia menyembelih itu. Ia mengambil tepung, diremasnya dan dibakarnya menjadi roti yang tidak beragi.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 28, 25, 'Dihidangkannyalah semuanya itu ke depan Saul dan ke depan para pegawainya, lalu mereka makan. Kemudian bangkitlah mereka dan pergi pada malam itu juga.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 1, 'Orang Filistin mengumpulkan segala tentara mereka ke Afek, sedang orang Israel berkemah dekat mata air yang di Yizreel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 2, 'Maka ketika raja-raja kota orang Filistin berjalan lewat dalam pasukan-pasukan seratus dan seribu, dan ketika juga Daud beserta orang-orangnya berjalan lewat di belakangnya bersama-sama dengan Akhis,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 3, 'berkatalah para panglima orang Filistin itu: "Apa gunanya orang-orang Ibrani ini?" Jawab Akhis kepada para panglima orang Filistin itu: "Bukankah dia itu Daud, hamba Saul, raja Israel, yang sudah satu dua tahun bersama-sama dengan aku, tanpa kudapati sesuatupun kesalahan padanya sejak saat ia membelot sampai hari ini?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 4, 'Tetapi para panglima orang Filistin itu menjadi marah kepadanya; serta berkata kepadanya: "Suruhlah orang itu pulang, supaya ia kembali ke tempat, yang kautunjukkan kepadanya, dan janganlah ia pergi berperang, bersama-sama dengan kita, supaya jangan ia menjadi lawan kita dalam peperangan. Sebab dengan apakah orang ini dapat menyukakan hati tuannya, kecuali dengan memberi kepala-kepala orang-orang ini?', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 5, 'Bukankah dia ini Daud yang dinyanyikan orang secara berbalas-balasan sambil menari-nari, demikian: Saul mengalahkan beribu-ribu musuh, tetapi Daud berlaksa-laksa?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 6, 'Lalu Akhis memanggil Daud, dan berkata kepadanya: "Demi TUHAN yang hidup, engkau ini orang jujur dan aku memandang baik, jika engkau keluar masuk bersama-sama dengan aku dalam tentara, sebab aku tidak mendapati sesuatu kejahatan padamu, sejak saat engkau datang kepadaku sampai hari ini; tetapi engkau ini tidak disukai oleh raja-raja kota.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 7, 'Sebab itu, pulanglah, pergilah dengan selamat dan jangan lakukan apa yang jahat di mata raja-raja kota orang Filistin itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 8, 'Tetapi Daud berkata kepada Akhis: "Apa yang telah kuperbuat? Dan kesalahan apa yang kaudapati pada hambamu ini, sejak saat aku menjadi hamba kepadamu, sampai hari ini, sehingga aku tidak boleh ikut pergi berperang melawan musuh tuanku raja?"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 9, 'Lalu Akhis menjawab Daud: "Aku tahu, engkau ini memang kusukai seperti utusan Allah. Hanya, para panglima orang Filistin telah berkata: Ia tidak boleh pergi berperang bersama-sama dengan kita.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 10, 'Jadi, bangunlah pagi-pagi beserta orang-orang tuanmu ini yang datang bersama-sama dengan engkau; bangunlah kamu pagi-pagi, segera sesudah hari cukup terang bagimu, dan pergilah."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 29, 11, 'Lalu bangunlah Daud dan orang-orangnya pagi-pagi untuk berjalan pulang ke negeri orang Filistin, sedang orang Filistin itu bergerak maju ke Yizreel.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 1, 'Ketika Daud serta orang-orangnya sampai ke Ziklag pada hari yang ketiga, orang Amalek telah menyerbu Tanah Negeb dan Ziklag; Ziklag telah dikalahkan oleh mereka dan dibakar habis.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 2, 'Perempuan-perempuan dan semua orang yang ada di sana, tua dan muda, telah ditawan mereka, dengan tidak membunuh seorangpun; mereka menggiring sekaliannya, kemudian meneruskan perjalanannya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 3, 'Ketika Daud dan orang-orangnya sampai ke kota itu, tampaklah kota itu terbakar habis, dan isteri mereka serta anak mereka yang laki-laki dan perempuan telah ditawan.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 4, 'Lalu menangislah Daud dan rakyat yang bersama-sama dengan dia itu dengan nyaring, sampai mereka tidak kuat lagi menangis.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 5, 'Juga kedua isteri Daud ditawan, yakni Ahinoam, perempuan Yizreel, dan Abigail, bekas isteri Nabal, orang Karmel itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 6, 'Dan Daud sangat terjepit, karena rakyat mengatakan hendak melempari dia dengan batu. Seluruh rakyat itu telah pedih hati, masing-masing karena anaknya laki-laki dan perempuan. Tetapi Daud menguatkan kepercayaannya kepada TUHAN, Allahnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 7, 'Lalu Daud memberi perintah kepada imam Abyatar bin Ahimelekh: "Bawalah efod itu kepadaku." Maka Abyatar membawa efod itu kepada Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 8, 'Kemudian bertanyalah Daud kepada TUHAN, katanya: "Haruskah aku mengejar gerombolan itu? Akan dapatkah mereka kususul?" Dan Ia berfirman kepadanya: "Kejarlah, sebab sesungguhnya, engkau akan dapat menyusul mereka dan melepaskan para tawanan."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 9, 'Lalu pergilah Daud beserta keenam ratus orang yang bersama-sama dengan dia, dan sampailah mereka ke sungai Besor. Sementara orang-orang yang mau tinggal di belakang berhenti di sana,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 10, 'maka Daud melanjutkan pengejaran itu beserta empat ratus orang. Dua ratus orang yang terlalu lelah untuk menyeberangi sungai Besor itu, berhenti di sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 11, 'Kemudian mereka menemui seorang Mesir di padang lalu membawanya kepada Daud. Mereka memberi dia roti, lalu makanlah ia, kemudian mereka memberi dia minum air,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 12, 'dan memberikan kepadanya sepotong kue ara dan dua buah kue kismis, dan setelah dimakannya, ia segar kembali, sebab ia tidak makan dan minum selama tiga hari tiga malam.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 13, 'Kemudian bertanyalah Daud kepadanya: "Budak siapakah engkau dan dari manakah engkau?" Jawabnya: "Aku ini seorang pemuda Mesir, budak kepunyaan seorang Amalek. Tuanku meninggalkan aku, karena tiga hari yang lalu aku jatuh sakit.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 14, 'Kami telah menyerbu Tanah Negeb orang Kreti dan daerah Yehuda dan Tanah Negeb Kaleb, dan Ziklag telah kami bakar habis."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 15, 'Daud bertanya kepadanya: "Dapatkah engkau menunjuk jalan kepadaku ke gerombolan itu?" Katanya: "Bersumpahlah kepadaku demi Allah, bahwa engkau tidak akan membunuh aku, dan tidak akan menyerahkan aku ke dalam tangan tuanku itu, maka aku akan menunjuk jalan kepadamu ke gerombolan itu."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 16, 'Ia menunjuk jalan kepada Daud ke sana, dan tampaklah orang-orang itu berpencar-pencar di atas seluruh daerah itu, sambil makan, minum dan mengadakan perayaan karena jarahan yang besar, yang telah dirampas mereka dari tanah orang Filistin dan dari tanah Yehuda.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 17, 'Dan pada keesokan harinya Daud menghancurkan mereka dari pagi-pagi buta sampai matahari terbenam; tidak ada seorangpun dari mereka yang lolos, kecuali empat ratus orang muda yang melarikan diri dengan menunggang unta.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 18, 'Daud melepaskan semua apa yang dirampas oleh orang Amalek itu; juga kedua isterinya dapat dilepaskan Daud.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 19, 'Tidak ada yang hilang pada mereka, dari hal yang kecil sampai hal yang besar, sampai anak laki-laki dan anak perempuan, dan dari jarahan sampai segala sesuatu yang telah dirampas mereka; semuanya itu dibawa Daud kembali.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 20, 'Daud mengambil segala kambing domba dan lembu; semuanya itu digiring mereka di hadapannya, serta berkata: "Inilah jarahan Daud."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 21, 'Ketika Daud sampai kepada kedua ratus orang yang telah terlalu lelah untuk mengikuti Daud, yang telah dibiarkannya tinggal di dekat sungai Besor, maka keluarlah orang-orang ini menyongsong Daud dan menyongsong rakyat yang bersama-sama dengan dia. Daud mendekati orang-orang itu dan memberi salam kepada mereka.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 22, 'Kemudian mulailah berbicara semua orang jahat dan orang dursila di antara orang-orang, yang ikut pergi bersama-sama dengan Daud itu, katanya: "Karena mereka tidak ikut pergi bersama-sama dengan kita, janganlah kita berikan kepada mereka apa-apa dari jarahan yang kita selamatkan itu, kecuali kepada masing-masing mereka isterinya dan anak-anaknya. Itu boleh mereka bawa, dan biarlah mereka pergi!"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 23, 'Tetapi Daud berkata: "Janganlah kamu, saudara-saudaraku, berbuat demikian, dengan apa yang diberikan TUHAN kepada kita; sebab Ia telah melindungi kita, dan menyerahkan ke dalam tangan kita gerombolan yang menyerang kita.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 24, 'Siapa yang mau mendengarkan kamu dalam perkara ini? Sebab, bagian orang yang tinggal di dekat barang-barang adalah sama seperti bagian orang yang pergi berperang; itu akan dibagi sama-sama."', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 25, 'Dan demikianlah halnya sejak hari itu dan seterusnya; hal itu ditentukannya menjadi ketetapan dan peraturan bagi orang Israel sampai sekarang.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 26, 'Ketika Daud sampai ke Ziklag, dikirimnyalah sebagian dari jarahan itu kepada para tua-tua di Yehuda, kepada teman-temannya, dengan pesan: "Inilah pemberian kepadamu dari jarahan yang dirampas dari musuh TUHAN,"', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 27, 'yakni kepada yang di Betel, kepada yang di Ramot di Tanah Selatan, kepada yang di Yatir,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 28, 'kepada yang di Aroer, kepada yang di Sifmot, kepada yang di Estemoa,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 29, 'kepada yang di Rakhal, kepada yang di kota-kota orang Yerahmeel, kepada yang di kota-kota orang Keni,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 30, 'kepada yang di Horma, kepada yang di Bor-Asan, kepada yang di Atakh,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 30, 31, 'kepada yang di Hebron dan kepada segala tempat di mana Daud dengan orang-orangnya mengembara.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 1, 'Sementara itu orang Filistin berperang melawan orang Israel. Orang-orang Israel melarikan diri dari hadapan orang Filistin dan banyak yang mati terbunuh di pegunungan Gilboa.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 2, 'Orang Filistin terus mengejar Saul dan anak-anaknya dan menewaskan Yonatan, Abinadab dan Malkisua, anak-anak Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 3, 'Kemudian makin beratlah pertempuran itu bagi Saul; para pemanah menjumpainya, dan melukainya dengan parah.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 4, 'Lalu berkatalah Saul kepada pembawa senjatanya: "Hunuslah pedangmu dan tikamlah aku, supaya jangan datang orang-orang yang tidak bersunat ini menikam aku dan memperlakukan aku sebagai permainan." Tetapi pembawa senjatanya tidak mau, karena ia sangat segan. Kemudian Saul mengambil pedang itu dan menjatuhkan dirinya ke atasnya.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 5, 'Ketika pembawa senjatanya melihat, bahwa Saul telah mati, iapun menjatuhkan dirinya ke atas pedangnya, lalu mati bersama-sama dengan Saul.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 6, 'Jadi Saul, ketiga anaknya dan pembawa senjatanya, dan seluruh tentaranya sama-sama mati pada hari itu.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 7, 'Ketika dilihat orang-orang Israel, yang di seberang lembah dan yang di seberang sungai Yordan, bahwa tentara Israel telah melarikan diri, dan bahwa Saul serta anak-anaknya sudah mati, maka mereka meninggalkan kota-kota mereka lalu melarikan diri juga; kemudian datanglah orang Filistin dan menetap di sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 8, 'Ketika keesokan harinya orang Filistin datang merampasi orang-orang yang mati terbunuh itu, didapati mereka Saul dan ketiga anaknya tergelimpang di pegunungan Gilboa.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 9, 'Mereka memancung kepala Saul, merampas senjata-senjatanya dan menyuruh orang berkeliling di negeri orang Filistin untuk menyampaikan kabar itu di kuil berhalanya dan kepada rakyat.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 10, 'Kemudian mereka menaruh senjata-senjata Saul di kuil Asytoret, dan mayatnya dipakukan mereka di tembok kota Bet-Sean.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 11, 'Ketika penduduk Yabesh-Gilead mendengar tentang apa yang telah dilakukan orang Filistin kepada Saul,', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 12, 'maka bersiaplah segenap orang gagah perkasa, mereka berjalan terus semalam-malaman, lalu mengambil mayat Saul dan mayat anak-anaknya dari tembok kota Bet-Sean. Kemudian pulanglah mereka ke Yabesh dan membakar mayat-mayat itu di sana.', 'id', 'TB'),
  ('9', '1sam', '1 Samuel', 31, 13, 'Mereka mengambil tulang-tulangnya lalu menguburkannya di bawah pohon tamariska di Yabesh. Sesudah itu berpuasalah mereka tujuh hari lamanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 1, 'Setelah Saul mati, dan ketika Daud kembali sesudah memukul kalah orang Amalek dan tinggal dua hari di Ziklag,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 2, 'maka datanglah pada hari ketiga seorang dari tentara, dari pihak Saul, dengan pakaian terkoyak-koyak dan tanah di atas kepala. Ketika ia sampai kepada Daud, sujudlah ia ke tanah dan menyembah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 3, 'Bertanyalah Daud kepadanya: "Dari manakah engkau?" Jawabnya kepadanya: "Aku lolos dari tentara Israel."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 4, 'Bertanyalah pula Daud kepadanya: "Apakah yang terjadi? Coba ceriterakan kepadaku." Jawabnya: "Rakyat telah melarikan diri dari pertempuran; bukan saja banyak dari rakyat yang gugur dan mati, tetapi Saul dan Yonatan, anaknya, juga sudah mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 5, 'Lalu Daud berkata kepada orang muda yang membawa kabar kepadanya itu: "Bagaimana kauketahui, bahwa Saul dan Yonatan, anaknya, sudah mati?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 6, 'Orang muda yang membawa kabar kepadanya itu berkata: "Kebetulan aku ada di pegunungan Gilboa; maka tampaklah Saul bertelekan pada tombaknya, sedang kereta-kereta dan orang-orang berkuda mengejarnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 7, 'Ketika menoleh ke belakang, ia melihat aku, lalu memanggil aku; dan aku berkata: Ya tuanku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 8, 'Ia bertanya kepadaku: Siapakah engkau? Jawabku kepadanya: Aku seorang Amalek.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 9, 'Lalu katanya kepadaku: Datanglah ke mari dan bunuhlah aku, sebab kekejangan telah menyerang aku, tetapi aku masih bernyawa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 10, 'Aku datang ke dekatnya dan membunuh dia, sebab aku tahu, ia tidak dapat hidup terus setelah jatuh. Aku mengambil jejamang yang ada di kepalanya, dan gelang yang ada pada lengannya, dan inilah dia kubawa kepada tuanku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 11, 'Lalu Daud memegang pakaiannya dan mengoyakkannya; dan semua orang yang bersama-sama dengan dia berbuat demikian juga.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 12, 'Dan mereka meratap, menangis dan berpuasa sampai matahari terbenam karena Saul, karena Yonatan, anaknya, karena umat TUHAN dan karena kaum Israel, sebab mereka telah gugur oleh pedang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 13, 'Kemudian bertanyalah Daud kepada orang muda yang membawa kabar itu kepadanya: "Asalmu dari mana?" Jawabnya: "Aku ini anak perantau, orang Amalek."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 14, 'Kemudian berkatalah Daud kepadanya: "Bagaimana? Tidakkah engkau segan mengangkat tanganmu memusnahkan orang yang diurapi TUHAN?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 15, 'Lalu Daud memanggil salah seorang dari anak buahnya dan berkata: "Ke mari, paranglah dia." Orang itu memarangnya, sehingga mati.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 16, 'Dan Daud berkata kepadanya: "Kautanggung sendiri darahmu, sebab mulutmulah yang menjadi saksi menentang engkau, karena berkata: Aku telah membunuh orang yang diurapi TUHAN."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 17, 'Daud menyanyikan nyanyian ratapan ini karena Saul dan Yonatan, anaknya,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 18, 'dan ia memberi perintah untuk mengajarkan nyanyian ini kepada bani Yehuda; itu ada tertulis dalam Kitab Orang Jujur.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 19, 'Kepermaianmu, hai Israel, mati terbunuh di bukit-bukitmu! Betapa gugur para pahlawan!', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 20, 'Janganlah kabarkan itu di Gat, janganlah beritakan itu di lorong-lorong Askelon, supaya jangan bersukacita anak-anak perempuan orang Filistin, supaya jangan beria-ria anak-anak perempuan orang-orang yang tidak bersunat!', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 21, 'Hai gunung-gunung di Gilboa! jangan ada embun, jangan ada hujan di atas kamu, hai padang-padang pembawa kematian! Sebab di sanalah perisai para pahlawan dilumuri, perisai Saul yang tidak diurapi dengan minyak.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 22, 'Tanpa darah orang-orang yang mati terbunuh dan tanpa lemak para pahlawan panah Yonatan tidak pernah berpaling pulang, dan pedang Saul tidak kembali dengan hampa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 23, 'Saul dan Yonatan, orang-orang yang dicintai dan yang ramah, dalam hidup dan matinya tidak terpisah. Mereka lebih cepat dari burung rajawali, mereka lebih kuat dari singa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 24, 'Hai anak-anak perempuan Israel, menangislah karena Saul, yang mendandani kamu dengan pakaian mewah dari kain kirmizi, yang menyematkan perhiasan emas pada pakaianmu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 25, 'Betapa gugur para pahlawan di tengah-tengah pertempuran! Yonatan mati terbunuh di bukit-bukitmu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 26, 'Merasa susah aku karena engkau, saudaraku Yonatan, engkau sangat ramah kepadaku; bagiku cintamu lebih ajaib dari pada cinta perempuan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 1, 27, 'Betapa gugur para pahlawan dan musnah senjata-senjata perang!', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 1, 'Kemudian bertanyalah Daud kepada TUHAN, katanya: "Apakah aku harus pergi ke salah satu kota di Yehuda?" Firman TUHAN kepadanya: "Pergilah." Lalu kata Daud: "Ke mana aku pergi?" Firman-Nya: "Ke Hebron."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 2, 'Lalu pergilah Daud ke sana dengan kedua isterinya: Ahinoam, perempuan Yizreel, dan Abigail, bekas isteri Nabal, orang Karmel itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 3, 'Juga Daud membawa serta orang-orangnya yang mengiringinya masing-masing dengan rumah tangganya, dan menetaplah mereka di kota-kota Hebron.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 4, 'Kemudian datanglah orang-orang Yehuda, lalu mengurapi Daud di sana menjadi raja atas kaum Yehuda. Ketika kepada Daud diberitahukan bahwa orang-orang Yabesh-Gilead menguburkan Saul,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 5, 'maka Daud mengirim orang kepada orang-orang Yabesh-Gilead dengan pesan: "Diberkatilah kamu oleh TUHAN, karena kamu telah menunjukkan kasihmu kepada tuanmu, Saul, dengan menguburkannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 6, 'Oleh sebab itu, TUHAN kiranya menunjukkan kasih dan setia-Nya kepadamu. Akupun akan berbuat kebaikan yang sama kepadamu, karena kamu telah melakukan hal yang demikian.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 7, 'Kuatkanlah hatimu sekarang dan jadilah orang-orang yang gagah perkasa, sekalipun tuanmu Saul sudah mati; dan aku telah diurapi oleh kaum Yehuda menjadi raja atas mereka."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 8, 'Abner bin Ner, panglima Saul, telah mengambil Isyboset, anak Saul, dan membawanya ke Mahanaim', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 9, 'serta menjadikannya raja atas Gilead, atas orang Asyuri, atas Yizreel, atas Efraim dan atas Benyamin, bahkan atas seluruh Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 10, 'Isyboset bin Saul berumur empat puluh tahun pada waktu ia menjadi raja atas Israel dan ia memerintah dua tahun lamanya. Hanyalah kaum Yehuda yang mengikuti Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 11, 'Dan lamanya Daud memerintah di Hebron atas kaum Yehuda adalah tujuh tahun dan enam bulan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 12, 'Lalu Abner bin Ner dengan anak buah Isyboset bin Saul bergerak maju dari Mahanaim ke Gibeon.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 13, 'Juga Yoab, anak Zeruya, dan anak buah Daud bergerak maju. Mereka saling bertemu di telaga Gibeon, lalu tinggal di sana, pihak yang satu di tepi telaga sebelah sini, dan pihak yang lain di tepi telaga sebelah sana.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 14, 'Berkatalah Abner kepada Yoab: "Biarlah orang-orang muda tampil dan mengadakan pertandingan di depan kita." Jawab Yoab: "Baik."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 15, 'Lalu tampillah mereka dan berjalan lewat dengan dihitung: dua belas orang dari suku Benyamin, dari Isyboset, anak Saul, dan dua belas orang dari anak buah Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 16, 'Kemudian mereka masing-masing menangkap kepala lawannya, dan menikamkan pedangnya ke lambung lawannya, sehingga rebahlah mereka bersama-sama. Sebab itu tempat itu disebutkan orang Helkat-Hazurim; letaknya dekat Gibeon.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 17, 'Pada hari itu pertempuran sangat hebat, dan Abner serta orang-orang Israel terpukul kalah oleh anak buah Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 18, 'Ketiga anak laki-laki Zeruya, yakni Yoab, Abisai dan Asael ada di sana; Asael cepat larinya seperti kijang di padang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 19, 'Asael mengejar Abner dan tidak menyimpang ke kanan atau ke kiri dalam membuntutinya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 20, 'Lalu Abner berpaling ke belakang dan bertanya: "Engkaukah itu Asael?" Jawabnya: "Ya, aku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 21, 'Kemudian berkatalah Abner kepadanya: "Menyimpanglah ke kiri atau ke kanan, tangkaplah salah seorang dari orang-orang muda itu dan ambillah senjatanya." Tetapi Asael tidak mau berhenti membuntuti Abner.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 22, 'Berkatalah sekali lagi Abner kepada Asael: "Berhentilah membuntuti aku. Apa aku harus memukul engkau sampai jatuh? Bagaimana aku dapat memandang muka Yoab, abangmu itu?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 23, 'Tetapi Asael menolak berhenti. Lalu Abner menusuk ke belakang ke perut Asael dengan tombaknya, sehingga tombak itu menembus belakangnya; dan rebahlah ia di sana dan mati di tempat itu juga. Semua orang yang datang ke tempat Asael rebah dan mati itu, berhenti di sana.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 24, 'Tetapi Yoab dan Abisai mengejar Abner. Ketika matahari masuk dan mereka sampai ke dekat bukit Ama, yang ada di sebelah timur Giah, ke arah padang gurun Gibeon,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 25, 'berhimpunlah bani Benyamin di belakang Abner menjadi satu gabungan dan bersiap-siap di puncak sebuah bukit.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 26, 'Berserulah Abner kepada Yoab: "Haruskah pedang makan terus-menerus? Tidak tahukah engkau, bahwa kepahitan datang pada akhirnya? Berapa lama lagi engkau tidak mau mengatakan kepada rakyat itu, supaya mereka berhenti memburu saudara-saudaranya?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 27, 'Jawab Yoab: "Demi Allah yang hidup, sekiranya engkau berbicara tadi, maka tentulah sudah dari tadi pagi rakyat menarik diri dari memburu saudara-saudaranya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 28, 'Lalu Yoab meniup sangkakala dan seluruh rakyat berhenti; mereka tidak lagi mengejar orang Israel dan tidak berperang lagi.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 29, 'Semalam-malaman Abner dan orang-orangnya berjalan melalui Araba-Yordan, menyeberangi sungai Yordan, berjalan terus hampir sepanjang siang, lalu sampai ke Mahanaim.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 30, 'Ketika Yoab berhenti memburu Abner dan menghimpunkan seluruh rakyat, ternyata sembilan belas orang dari anak buah Daud hilang termasuk Asael.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 31, 'Tetapi anak buah Daud menewaskan dari suku Benyamin, dari orang-orang Abner, tiga ratus enam puluh orang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 2, 32, 'Mereka mengangkat mayat Asael dan menguburkannya di dalam kubur ayahnya yang di Betlehem. Kemudian berjalanlah Yoab dan orang-orangnya semalam-malaman itu dan sampai ke Hebron, ketika hari sudah terang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 1, 'Peperangan antara keluarga Saul dan keluarga Daud berlarut-larut; Daud kian lama kian kuat, sedang keluarga Saul kian lama kian lemah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 2, 'Di Hebron lahirlah bagi Daud anak-anak lelaki. Anak sulungnya ialah Amnon, dari Ahinoam, perempuan Yizreel;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 3, 'anaknya yang kedua ialah Kileab, dari Abigail, bekas isteri Nabal, orang Karmel; yang ketiga ialah Absalom, anak dari Maakha, anak perempuan Talmai raja Gesur;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 4, 'yang keempat ialah Adonia, anak dari Hagit; yang kelima ialah Sefaca, anak Abital;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 5, 'dan yang keenam ialah Yitream, dari Egla, isteri Daud. Semuanya ini dilahirkan bagi Daud di Hebron.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 6, 'Selama ada peperangan antara keluarga Saul dan keluarga Daud, maka Abner makin mendapat pengaruh di antara keluarga Saul.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 7, 'Saul mempunyai gundik yang bernama Rizpa; dia anak perempuan Aya. Berkatalah Isyboset kepada Abner: "Mengapa kauhampiri gundik ayahku?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 8, 'Lalu sangat marahlah Abner karena perkataan Isyboset itu, katanya: "Kepala anjing dari Yehudakah aku? Sampai sekarang aku masih menunjukkan kesetiaanku kepada keluarga Saul, ayahmu, kepada saudara-saudaranya dan kepada sahabat-sahabatnya, dan aku tidak membiarkan engkau jatuh ke tangan Daud, tetapi sekarang engkau menuduh aku berlaku salah dengan seorang perempuan?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 9, 'Kiranya Allah menghukum Abner, bahkan lebih lagi dari pada itu, jika tidak kulakukan kepada Daud seperti yang dijanjikan TUHAN dengan bersumpah kepadanya,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 10, 'yakni memindahkan kerajaan dari keluarga Saul dan mendirikan takhta kerajaan Daud atas Israel dan atas Yehuda, dari Dan sampai Bersyeba."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 11, 'Dan Isyboset tidak dapat lagi menjawab sepatah katapun kepada Abner, karena takutnya kepadanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 12, 'Lalu Abner mengirim utusan kepada Daud dengan pesan: "Milik siapakah negeri ini? Adakanlah perjanjian dengan aku, maka sesungguhnya aku akan membantu engkau untuk membawa seluruh orang Israel memihak kepadamu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 13, 'Jawab Daud: "Baik, aku akan mengadakan perjanjian dengan engkau, hanya satu hal kuminta dari padamu, yakni engkau tidak akan menghadap aku, kecuali jika engkau membawa lebih dahulu Mikhal, anak perempuan Saul, apabila engkau datang menghadap aku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 14, 'Daud mengirim utusan juga kepada Isyboset, anak Saul, dengan pesan: "Berikanlah isteriku Mikhal, yang telah kuperoleh dengan seratus kulit khatan orang Filistin."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 15, 'Lalu Isyboset menyuruh mengambil perempuan itu dari pada suaminya, yakni Paltiel bin Lais.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 16, 'Dan suaminya berjalan bersama-sama dengan dia, sambil mengikuti dia dengan menangis sampai ke Bahurim. Lalu berkatalah Abner kepadanya: "Ayo, pulanglah." Maka pulanglah ia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 17, 'Sementara itu berundinglah Abner dengan para tua-tua orang Israel, katanya: "Telah lama kamu menghendaki Daud menjadi raja atas kamu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 18, 'Maka sekarang bertindaklah, sebab TUHAN sudah berfirman tentang Daud, demikian: Dengan perantaraan hamba-Ku Daud Aku akan menyelamatkan umat-Ku Israel dari tangan orang Filistin dan dari tangan semua musuhnya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 19, 'Abner berbicara dengan orang Benyamin; pula Abner pergi membicarakan dengan Daud di Hebron segala yang sudah dipandang baik oleh orang Israel dan oleh seluruh kaum Benyamin.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 20, 'Ketika Abner datang kepada Daud di Hebron bersama-sama dua puluh orang, maka Daud mengadakan perjamuan bagi Abner dan orang-orang yang menyertainya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 21, 'Berkatalah Abner kepada Daud: "Baiklah aku bersiap untuk pergi mengumpulkan seluruh orang Israel kepada tuanku raja, supaya mereka mengadakan perjanjian dengan tuanku dan tuanku menjadi raja atas segala yang dikehendaki hatimu." Lalu Daud membiarkan Abner pergi dan berjalanlah ia dengan selamat.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 22, 'Anak buah Daud dan Yoab baru saja pulang setelah mengadakan penggerebekan dan mereka membawa pulang jarahan yang banyak. Tetapi Abner tidak lagi bersama-sama Daud di Hebron, sebab ia telah dilepasnya pergi dengan selamat.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 23, 'Ketika Yoab bersama dengan segenap tentaranya sudah pulang, diberitahukan kepada Yoab, demikian: "Abner bin Ner telah datang kepada raja dan ia sudah dibiarkannya pergi dengan selamat."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 24, 'Kemudian pergilah Yoab kepada raja, katanya: "Apakah yang telah kauperbuat? Abner telah datang kepadamu; mengapa engkau membiarkannya begitu saja?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 25, 'Apakah engkau tidak kenal Abner bin Ner itu. Ia datang untuk memperdaya engkau dan untuk mengetahui gerak-gerikmu dan untuk mengetahui segala yang hendak kaulakukan."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 26, 'Sesudah itu keluarlah Yoab meninggalkan Daud dan menyuruh orang menyusul Abner, lalu mereka membawanya kembali dari perigi Sira tanpa diketahui Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 27, 'Ketika Abner kembali ke Hebron, maka Yoab membawanya sebentar ke samping di tengah-tengah pintu gerbang itu, seakan-akan hendak berbicara dengan dia dengan diam-diam; kemudian ditikamnyalah dia di sana pada perutnya, sehingga mati, membalas darah Asael, adiknya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 28, 'Ketika hal itu didengar Daud kemudian, berkatalah ia: "Aku dan kerajaanku tidak bersalah di hadapan TUHAN sampai selama-lamanya terhadap darah Abner bin Ner itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 29, 'Biarlah itu ditanggung oleh Yoab sendiri dan seluruh kaum keluarganya. Biarlah dalam keturunan Yoab tidak putus-putusnya ada orang yang mengeluarkan lelehan, yang sakit kusta, yang bertongkat, yang tewas oleh pedang atau yang kekurangan makanan."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 30, 'Demikianlah Yoab dan Abisai, adiknya, membunuh Abner, karena ia telah membunuh Asael, adik mereka, di Gibeon dalam pertempuran.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 31, 'Dan berkatalah Daud kepada Yoab dan kepada segala rakyat yang bersama-sama dengan dia: "Koyakkanlah pakaianmu dan lilitkanlah pada tubuhmu kain kabung dan merataplah di depan mayat Abner." Raja Daud sendiripun berjalan di belakang usungan mayat.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 32, 'Ketika orang menguburkan Abner di Hebron, maka menangislah raja dengan suara nyaring pada kubur Abner dan seluruh rakyatpun menangis.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 33, 'Karena Abner raja mengucapkan nyanyian ratapan ini: "Apakah Abner harus mati seperti orang bebal?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 34, 'Tanganmu tidak terikat dan kakimu tidak dirantai. Engkau gugur seperti orang gugur oleh orang-orang durjana." Dan seluruh rakyat itu makin menangis karena dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 35, 'Seluruh rakyat datang menawarkan kepada Daud untuk makan roti selagi hari siang, tetapi Daud bersumpah, katanya: "Kiranya Allah menghukum aku, bahkan lebih lagi dari pada itu, jika sebelum matahari terbenam aku mengecap roti atau apapun."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 36, 'Ketika seluruh rakyat melihat hal itu, mereka menganggap hal itu baik, seperti segala sesuatu yang dilakukan raja dianggap baik oleh seluruh rakyat.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 37, 'Maka tahulah seluruh rakyat dan seluruh Israel pada hari itu, bahwa pembunuhan Abner bin Ner bukanlah rancangan raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 38, 'Kemudian berkatalah raja kepada para pegawainya: "Tidak tahukah kamu, bahwa pada hari ini gugur seorang pemimpin, seorang besar, di Israel?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 3, 39, 'Tetapi aku ini sekarang masih lemah, sekalipun sudah diurapi menjadi raja, sedang orang-orang itu, yakni anak-anak Zeruya, melebihi aku dalam kekerasan. Kiranya TUHAN membalas kepada orang yang berbuat jahat setimpal dengan kejahatannya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 1, 'Ketika didengar anak Saul, bahwa Abner sudah mati di Hebron, maka hilanglah keberaniannya, dan terkejutlah seluruh orang Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 2, 'Anak Saul mempunyai dua orang sebagai kepala gerombolan, yang satu bernama Baana dan yang kedua bernama Rekhab, keduanya anak Rimon, orang Benyamin dari Beerot. ?Sebab Beerotpun terhitung daerah Benyamin.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 3, 'Orang Beerot sudah melarikan diri ke Gitaim dan menjadi pendatang di sana sampai sekarang. ?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 4, 'Yonatan, anak Saul, mempunyai seorang anak laki-laki, yang cacat kakinya. Ia berumur lima tahun, ketika datang kabar tentang Saul dan Yonatan dari Yizreel. Inang pengasuhnya mengangkat dia pada waktu itu, lalu lari, tetapi karena terburu-buru larinya, anak itu jatuh dan menjadi timpang. Ia bernama Mefiboset.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 5, 'Anak-anak Rimon, orang Beerot itu, yakni Rekhab dan Baana, pergi, lalu sampai pada waktu hari panas terik ke rumah Isyboset, ketika ia sedang berbaring siang hari.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 6, 'Kebetulan penjaga pintu rumah itu mengantuk dan tertidur, ketika sedang membersihkan gandum. Demikianlah Rekhab dan Baana menyusup ke dalam.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 7, 'Mereka masuk ke dalam rumah itu, ketika Isyboset sedang berbaring di atas tempat tidurnya di dalam kamar tidurnya, membunuh dia lalu memenggal kepalanya. Mereka membawa kepalanya itu, lalu berjalan semalam-malaman melalui jalan dari Araba-Yordan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 8, 'Kepala Isyboset itu dibawa mereka kepada Daud di Hebron dan mereka berkata kepada raja: "Inilah kepala Isyboset, anak Saul, musuhmu itu, yang ingin mencabut nyawamu; TUHAN pada hari ini telah membiarkan tuanku raja mengadakan pembalasan atas Saul dan atas keturunannya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 9, 'Tetapi Daud menjawab Rekhab dan Baana, saudaranya, anak-anak Rimon, orang Beerot itu, katanya kepada mereka: "Demi TUHAN yang hidup, yang telah membebaskan nyawaku dari segala kesesakan!', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 10, 'Ketika ada orang yang membawa kabar kepadaku demikian: Saul sudah mati! dan memandang dirinya sebagai orang yang menyampaikan kabar baik, maka aku menangkap dan membunuh dia di Ziklag, dan dengan demikian aku memberikan kepadanya upah kabarnya;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 11, 'terlebih lagi sekarang, setelah orang-orang fasik membunuh seorang yang benar, di rumahnya di atas tempat tidurnya, tidakkah aku menuntut darahnya dari pada kamu dan melenyapkan kamu dari muka bumi?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 4, 12, 'Sesudah itu Daud memberi perintah kepada anak buahnya untuk membunuh mereka; tangan dan kaki mereka dipotong, kemudian mayat mereka digantung di tepi telaga di Hebron. Tetapi kepala Isyboset diambil dan dikuburkan di dalam kubur Abner di Hebron.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 1, 'Lalu datanglah segala suku Israel kepada Daud di Hebron dan berkata: "Ketahuilah, kami ini darah dagingmu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 2, 'Telah lama, ketika Saul memerintah atas kami, engkaulah yang memimpin segala gerakan orang Israel. Dan TUHAN telah berfirman kepadamu: Engkaulah yang harus menggembalakan umat-Ku Israel, dan engkaulah yang menjadi raja atas Israel."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 3, 'Maka datanglah semua tua-tua Israel menghadap raja di Hebron, lalu raja Daud mengadakan perjanjian dengan mereka di Hebron di hadapan TUHAN; kemudian mereka mengurapi Daud menjadi raja atas Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 4, 'Daud berumur tiga puluh tahun, pada waktu ia menjadi raja; empat puluh tahun lamanya ia memerintah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 5, 'Di Hebron ia memerintah atas Yehuda tujuh tahun enam bulan, dan di Yerusalem ia memerintah tiga puluh tiga tahun atas seluruh Israel dan Yehuda.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 6, 'Lalu raja dengan orang-orangnya pergi ke Yerusalem, menyerang orang Yebus, penduduk negeri itu. Mereka itu berkata kepada Daud: "Engkau tidak sanggup masuk ke mari; orang-orang buta dan orang-orang timpang akan mengenyahkan engkau!" Maksud mereka: Daud tidak sanggup masuk ke mari.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 7, 'Tetapi Daud merebut kubu pertahanan Sion, yaitu kota Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 8, 'Daud telah berkata pada waktu itu: "Siapa yang hendak memukul kalah orang Yebus, haruslah ia masuk melalui saluran air itu; hati Daud benci kepada orang-orang timpang dan orang-orang buta." Sebab itu orang berkata: "Orang-orang buta dan orang-orang timpang tidak boleh masuk bait."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 9, 'Dan Daud menetap di kubu pertahanan itu dan menamainya: Kota Daud. Ia memperkuatnya sekelilingnya, mulai dari Milo ke bagian dalam.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 10, 'Lalu makin lama makin besarlah kuasa Daud, sebab TUHAN, Allah semesta alam, menyertainya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 11, 'Hiram, raja negeri Tirus, mengirim utusan kepada Daud dan kayu alas, tukang-tukang kayu dan tukang-tukang batu; mereka mendirikan istana bagi Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 12, 'Lalu tahulah Daud, bahwa TUHAN telah menegakkan dia sebagai raja atas Israel dan telah mengangkat martabat pemerintahannya oleh karena Israel, umat-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 13, 'Daud mengambil lagi beberapa gundik dan isteri dari Yerusalem, setelah ia datang dari Hebron dan bagi Daud masih lahir lagi anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 14, 'Inilah nama anak-anak yang lahir bagi dia di Yerusalem: Syamua, Sobab, Natan, Salomo,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 15, 'Yibhar, Elisua, Nefeg, Yafia,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 16, 'Elisama, Elyada dan Elifelet.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 17, 'Ketika didengar orang Filistin, bahwa Daud telah diurapi menjadi raja atas Israel, maka majulah semua orang Filistin untuk menangkap Daud. Tetapi Daud mendengar hal itu, lalu ia pergi ke kubu pertahanan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 18, 'Ketika orang Filistin itu datang dan memencar di lembah Refaim,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 19, 'bertanyalah Daud kepada TUHAN: "Apakah aku harus maju melawan orang Filistin itu? Akan Kauserahkankah mereka ke dalam tanganku?" TUHAN menjawab Daud: "Majulah, sebab Aku pasti akan menyerahkan orang Filistin itu ke dalam tanganmu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 20, 'Lalu datanglah Daud di Baal-Perasim dan memukul mereka kalah di sana. Berkatalah ia: "TUHAN telah menerobos musuhku di depanku seperti air menerobos." Sebab itu orang menamakan tempat itu Baal-Perasim.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 21, 'Orang Filistin itu meninggalkan berhalanya di sana, lalu Daud dan orang-orangnya mengangkatnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 22, 'Ketika orang Filistin maju sekali lagi dan memencar di lembah Refaim,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 23, 'maka bertanyalah Daud kepada TUHAN, dan Ia menjawab: "Janganlah maju, tetapi buatlah gerakan lingkaran sampai ke belakang mereka, sehingga engkau dapat menyerang mereka dari jurusan pohon-pohon kertau.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 24, 'Dan bila engkau mendengar bunyi derap langkah di puncak pohon-pohon kertau itu, maka haruslah engkau bertindak cepat, sebab pada waktu itu TUHAN telah keluar berperang di depanmu untuk memukul kalah tentara orang Filistin."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 5, 25, 'Dan Daud berbuat demikian, seperti yang diperintahkan TUHAN kepadanya, maka ia memukul kalah orang Filistin, mulai dari Geba sampai dekat Gezer.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 1, 'Daud mengumpulkan pula semua orang pilihan di antara orang Israel, tiga puluh ribu orang banyaknya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 2, 'Kemudian bersiaplah Daud, lalu berjalan dari Baale-Yehuda dengan seluruh rakyat yang menyertainya, untuk mengangkut dari sana tabut Allah, yang disebut dengan nama TUHAN semesta alam yang bertakhta di atas kerubim.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 3, 'Mereka menaikkan tabut Allah itu ke dalam kereta yang baru setelah mengangkatnya dari rumah Abinadab yang di atas bukit. Lalu Uza dan Ahyo, anak-anak Abinadab, mengantarkan kereta itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 4, 'Uza berjalan di samping tabut Allah itu, sedang Ahyo berjalan di depan tabut itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 5, 'Daud dan seluruh kaum Israel menari-nari di hadapan TUHAN dengan sekuat tenaga, diiringi nyanyian, kecapi, gambus, rebana, kelentung dan ceracap.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 6, 'Ketika mereka sampai ke tempat pengirikan Nakhon, maka Uza mengulurkan tangannya kepada tabut Allah itu, lalu memegangnya, karena lembu-lembu itu tergelincir.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 7, 'Maka bangkitlah murka TUHAN terhadap Uza, lalu Allah membunuh dia di sana karena keteledorannya itu; ia mati di sana dekat tabut Allah itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 8, 'Daud menjadi marah, karena TUHAN telah menyambar Uza demikian hebatnya; maka tempat itu disebut orang Peres-Uza sampai sekarang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 9, 'Pada waktu itu Daud menjadi takut kepada TUHAN, lalu katanya: "Bagaimana tabut TUHAN itu dapat sampai kepadaku?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 10, 'Sebab itu Daud tidak mau memindahkan tabut TUHAN itu ke tempatnya, ke kota Daud, tetapi Daud menyimpang dan membawanya ke rumah Obed-Edom, orang Gat itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 11, 'Tiga bulan lamanya tabut Tuhan itu tinggal di rumah Obed-Edom, orang Gat itu, dan TUHAN memberkati Obed-Edom dan seisi rumahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 12, 'Diberitahukanlah kepada raja Daud, demikian: "TUHAN memberkati seisi rumah Obed-Edom dan segala yang ada padanya oleh karena tabut Allah itu." Lalu Daud pergi mengangkut tabut Allah itu dari rumah Obed-Edom ke kota Daud dengan sukacita.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 13, 'Apabila pengangkat-pengangkat tabut TUHAN itu melangkah maju enam langkah, maka ia mengorbankan seekor lembu dan seekor anak lembu gemukan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 14, 'Dan Daud menari-nari di hadapan TUHAN dengan sekuat tenaga; ia berbaju efod dari kain lenan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 15, 'Daud dan seluruh orang Israel mengangkut tabut TUHAN itu dengan diiringi sorak dan bunyi sangkakala.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 16, 'Ketika tabut TUHAN itu masuk ke kota Daud, maka Mikhal, anak perempuan Saul, menjenguk dari jendela, lalu melihat raja Daud meloncat-loncat serta menari-nari di hadapan TUHAN. Sebab itu ia memandang rendah Daud dalam hatinya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 17, 'Tabut TUHAN itu dibawa masuk, lalu diletakkan di tempatnya, di dalam kemah yang dibentangkan Daud untuk itu, kemudian Daud mempersembahkan korban bakaran dan korban keselamatan di hadapan TUHAN.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 18, 'Setelah Daud selesai mempersembahkan korban bakaran dan korban keselamatan, diberkatinyalah bangsa itu demi nama TUHAN semesta alam.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 19, 'Lalu dibagikannya kepada seluruh bangsa itu, kepada seluruh khalayak ramai Israel, baik laki-laki maupun perempuan, kepada masing-masing seketul roti bundar, sekerat daging, dan sepotong kue kismis. Sesudah itu pergilah seluruh bangsa itu, masing-masing ke rumahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 20, 'Ketika Daud pulang untuk memberi salam kepada seisi rumahnya, maka keluarlah Mikhal binti Saul mendapatkan Daud, katanya: "Betapa raja orang Israel, yang menelanjangi dirinya pada hari ini di depan mata budak-budak perempuan para hambanya, merasa dirinya terhormat pada hari ini, seperti orang hina dengan tidak malu-malu menelanjangi dirinya!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 21, 'Tetapi berkatalah Daud kepada Mikhal: "Di hadapan TUHAN, yang telah memilih aku dengan menyisihkan ayahmu dan segenap keluarganya untuk menunjuk aku menjadi raja atas umat TUHAN, yakni atas Israel, ?di hadapan TUHAN aku menari-nari,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 22, 'bahkan aku akan menghinakan diriku lebih dari pada itu; engkau akan memandang aku rendah, tetapi bersama-sama budak-budak perempuan yang kaukatakan itu, bersama-sama merekalah aku mau dihormati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 6, 23, 'Mikhal binti Saul tidak mendapat anak sampai hari matinya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 1, 'Ketika raja telah menetap di rumahnya dan TUHAN telah mengaruniakan keamanan kepadanya terhadap semua musuhnya di sekeliling,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 2, 'berkatalah raja kepada nabi Natan: "Lihatlah, aku ini diam dalam rumah dari kayu aras, padahal tabut Allah diam di bawah tenda."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 3, 'Lalu berkatalah Natan kepada raja: "Baik, lakukanlah segala sesuatu yang dikandung hatimu, sebab TUHAN menyertai engkau."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 4, 'Tetapi pada malam itu juga datanglah firman TUHAN kepada Natan, demikian:', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 5, '"Pergilah, katakanlah kepada hamba-Ku Daud: Beginilah firman TUHAN: Masakan engkau yang mendirikan rumah bagi-Ku untuk Kudiami?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 6, 'Aku tidak pernah diam dalam rumah sejak Aku menuntun orang Israel dari Mesir sampai hari ini, tetapi Aku selalu mengembara dalam kemah sebagai kediaman.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 7, 'Selama Aku mengembara bersama-sama seluruh orang Israel, pernahkah Aku mengucapkan firman kepada salah seorang hakim orang Israel, yang Kuperintahkan menggembalakan umat-Ku Israel, demikian: Mengapa kamu tidak mendirikan bagi-Ku rumah dari kayu aras?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 8, 'Oleh sebab itu, beginilah kaukatakan kepada hamba-Ku Daud: Beginilah firman TUHAN semesta alam: Akulah yang mengambil engkau dari padang, ketika menggiring kambing domba, untuk menjadi raja atas umat-Ku Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 9, 'Aku telah menyertai engkau di segala tempat yang kaujalani dan telah melenyapkan segala musuhmu dari depanmu. Aku membuat besar namamu seperti nama orang-orang besar yang ada di bumi.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 10, 'Aku menentukan tempat bagi umat-Ku Israel dan menanamkannya, sehingga ia dapat diam di tempatnya sendiri dengan tidak lagi dikejutkan dan tidak pula ditindas oleh orang-orang lalim seperti dahulu,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 11, 'sejak Aku mengangkat hakim-hakim atas umat-Ku Israel. Aku mengaruniakan keamanan kepadamu dari pada semua musuhmu. Juga diberitahukan TUHAN kepadamu: TUHAN akan memberikan keturunan kepadamu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 12, 'Apabila umurmu sudah genap dan engkau telah mendapat perhentian bersama-sama dengan nenek moyangmu, maka Aku akan membangkitkan keturunanmu yang kemudian, anak kandungmu, dan Aku akan mengokohkan kerajaannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 13, 'Dialah yang akan mendirikan rumah bagi nama-Ku dan Aku akan mengokohkan takhta kerajaannya untuk selama-lamanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 14, 'Aku akan menjadi Bapanya, dan ia akan menjadi anak-Ku. Apabila ia melakukan kesalahan, maka Aku akan menghukum dia dengan rotan yang dipakai orang dan dengan pukulan yang diberikan anak-anak manusia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 15, 'Tetapi kasih setia-Ku tidak akan hilang dari padanya, seperti yang Kuhilangkan dari pada Saul, yang telah Kujauhkan dari hadapanmu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 16, 'Keluarga dan kerajaanmu akan kokoh untuk selama-lamanya di hadapan-Ku, takhtamu akan kokoh untuk selama-lamanya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 17, 'Tepat seperti perkataan ini dan tepat seperti penglihatan ini Natan berbicara kepada Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 18, 'Lalu masuklah raja Daud ke dalam, kemudian duduklah ia di hadapan TUHAN sambil berkata: "Siapakah aku ini, ya Tuhan ALLAH, dan siapakah keluargaku, sehingga Engkau membawa aku sampai sedemikian ini?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 19, 'Dan hal ini masih kurang di mata-Mu, ya Tuhan ALLAH; sebab itu Engkau telah berfirman juga tentang keluarga hamba-Mu ini dalam masa yang masih jauh dan telah memperlihatkan kepadaku serentetan manusia yang akan datang, ya Tuhan ALLAH.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 20, 'Apakah yang dapat dikatakan Daud kepada-Mu lebih lagi dari pada itu. Bukankah Engkau yang mengenal hamba-Mu ini, ya Tuhan ALLAH?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 21, 'Oleh karena firman-Mu dan menurut hati-Mu Engkau telah melakukan segala perkara yang besar ini dengan memberitahukannya kepada hamba-Mu ini.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 22, 'Sebab itu Engkau besar, ya Tuhan ALLAH, sebab tidak ada yang sama seperti Engkau dan tidak ada Allah selain Engkau menurut segala yang kami tangkap dengan telinga kami.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 23, 'Dan bangsa manakah di bumi seperti umat-Mu Israel, yang Allahnya pergi membebaskannya menjadi umat-Nya, untuk mendapat nama bagi-Nya dengan melakukan perbuatan-perbuatan yang besar dan dahsyat bagi mereka, dan dengan menghalau bangsa-bangsa dan para allah mereka dari depan umat-Nya?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 24, 'Engkau telah mengokohkan bagi-Mu umat-Mu Israel menjadi umat-Mu untuk selama-lamanya, dan Engkau, ya TUHAN, menjadi Allah mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 25, 'Dan sekarang, ya TUHAN Allah, tepatilah untuk selama-lamanya janji yang Kauucapkan mengenai hamba-Mu ini dan mengenai keluarganya dan lakukanlah seperti yang Kaujanjikan itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 26, 'Maka nama-Mu akan menjadi besar untuk selama-lamanya, sehingga orang berkata: TUHAN semesta alam ialah Allah atas Israel; maka keluarga hamba-Mu Daud akan tetap kokoh di hadapan-Mu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 27, 'Sebab Engkau, TUHAN semesta alam, Allah Israel, telah menyatakan kepada hamba-Mu ini, demikian: Aku akan membangun keturunan bagimu. Itulah sebabnya hamba-Mu ini telah memberanikan diri untuk memanjatkan doa ini kepada-Mu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 28, 'Oleh sebab itu, ya Tuhan ALLAH, Engkaulah Allah dan segala firman-Mulah kebenaran; Engkau telah menjanjikan perkara yang baik ini kepada hamba-Mu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 7, 29, 'Kiranya Engkau sekarang berkenan memberkati keluarga hamba-Mu ini, supaya tetap ada di hadapan-Mu untuk selama-lamanya. Sebab, ya Tuhan ALLAH, Engkau sendirilah yang berfirman dan oleh karena berkat-Mu keluarga hamba-Mu ini diberkati untuk selama-lamanya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 1, 'Sesudah itu Daud memukul kalah orang Filistin dan menundukkan mereka; lalu Daud mengambil kendali pemerintahan atas ibu kota dari tangan orang Filistin.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 2, 'Dan ia memukul kalah orang Moab, lalu sambil menyuruh mereka berbaring di tanah ia mengukur tempat mereka dengan tali; diukurnya dua kali panjang tali itu untuk mematikan dan satu tali penuh untuk membiarkan hidup. Maka orang Moab takluk kepada Daud dan harus mempersembahkan upeti.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 3, 'Selanjutnya Daud memukul kalah Hadadezer bin Rehob, raja Zoba, ketika ia pergi memulihkan kekuasaannya pada sungai Efrat.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 4, 'Daud menawan dari padanya seribu tujuh ratus orang pasukan berkuda dan dua puluh ribu orang pasukan berjalan kaki, lalu Daud menyuruh memotong urat keting segala kuda kereta, tetapi dengan meninggalkan seratus ekor kuda kereta.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 5, 'Lalu orang Aram dari Damsyik datang menolong Hadadezer, raja Zoba, tetapi dari antara orang Aram itu Daud menewaskan dua puluh dua ribu orang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 6, 'Kemudian Daud menempatkan pasukan-pasukan pendudukan di daerah orang Aram dari Damsyik. Orang Aram itu takluk kepada Daud dan harus mempersembahkan upeti. TUHAN memberi kemenangan kepada Daud ke manapun ia pergi berperang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 7, 'Sesudah itu Daud mengangkut perisai-perisai emas yang dipakai oleh anak buah Hadadezer, lalu membawanya ke Yerusalem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 8, 'Dan dari Betah dan dari Berotai, yaitu kota-kotanya Hadadezer, raja Daud mengangkut amat banyak tembaga.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 9, 'Ketika didengar Tou, raja Hamat, bahwa Daud telah memukul kalah seluruh tentara Hadadezer,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 10, 'maka Tou mengutus Yoram, anaknya, kepada raja Daud untuk menyampaikan salam dan mengucapkan selamat kepadanya, karena ia telah berperang melawan Hadadezer dan memukul dia kalah, sebab Hadadezer sering memerangi Tou. Dan Yoram membawa barang-barang perak, emas dan tembaga.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 11, 'Juga barang-barang ini dikhususkan raja Daud bagi TUHAN, bersama-sama perak dan emas yang berasal dari segala bangsa yang ditaklukkannya,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 12, 'yakni perak dan emas dari orang Aram, dari orang Moab, dari bani Amon, dari orang Filistin, dari orang Amalek, dan dari jarahan yang dirampas dari Hadadezer bin Rehob, raja Zoba.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 13, 'Demikianlah Daud mendapat nama, dan ketika ia pulang, ia menewaskan delapan belas ribu orang Edom di Lembah Asin.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 14, 'Lalu ia menempatkan pasukan-pasukan pendudukan di Edom; di seluruh Edom ditempatkannya pasukan-pasukan pendudukan, sehingga seluruh Edom diperbudak oleh Daud. TUHAN memberi kemenangan kepada Daud ke manapun ia pergi berperang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 15, 'Demikianlah Daud telah memerintah atas seluruh Israel, dan menegakkan keadilan dan kebenaran bagi seluruh bangsanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 16, 'Yoab, anak Zeruya, menjadi panglima; Yosafat bin Ahilud menjadi bendahara negara;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 17, 'Zadok bin Ahitub dan Ahimelekh bin Abyatar menjadi imam; Seraya menjadi panitera negara;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 8, 18, 'Benaya bin Yoyada menjadi panglima orang Kreti dan orang Pleti; dan anak-anak Daud menjadi imam.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 1, 'Berkatalah Daud: "Masih adakah orang yang tinggal dari keluarga Saul? Maka aku akan menunjukkan kasihku kepadanya oleh karena Yonatan."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 2, 'Adapun keluarga Saul mempunyai seorang hamba, yang bernama Ziba. Ia dipanggil menghadap Daud, lalu raja bertanya kepadanya: "Engkaukah Ziba?" Jawabnya: "Hamba tuanku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 3, 'Kemudian berkatalah raja: "Tidak adakah lagi orang yang tinggal dari keluarga Saul? Aku hendak menunjukkan kepadanya kasih yang dari Allah." Lalu berkatalah Ziba kepada raja: "Masih ada seorang anak laki-laki Yonatan, yang cacat kakinya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 4, 'Tanya raja kepadanya: "Di manakah ia?" Jawab Ziba kepada raja: "Dia ada di rumah Makhir bin Amiel, di Lodebar."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 5, 'Sesudah itu raja Daud menyuruh mengambil dia dari rumah Makhir bin Amiel, dari Lodebar.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 6, 'Dan Mefiboset bin Yonatan bin Saul masuk menghadap Daud, ia sujud dan menyembah. Kata Daud: "Mefiboset!" Jawabnya: "Inilah hamba tuanku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 7, 'Kemudian berkatalah Daud kepadanya: "Janganlah takut, sebab aku pasti akan menunjukkan kasihku kepadamu oleh karena Yonatan, ayahmu; aku akan mengembalikan kepadamu segala ladang Saul, nenekmu, dan engkau akan tetap makan sehidangan dengan aku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 8, 'Lalu sujudlah Mefiboset dan berkata: "Apakah hambamu ini, sehingga engkau menghiraukan anjing mati seperti aku?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 9, 'Lalu raja memanggil Ziba, hamba Saul itu, dan berkata kepadanya: "Segala sesuatu yang adalah milik Saul dan milik seluruh keluarganya kuberikan kepada cucu tuanmu itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 10, 'Engkau harus mengerjakan tanah baginya, engkau, anak-anakmu dan hamba-hambamu, dan harus membawa masuk tuaiannya, supaya cucu tuanmu itu ada makanannya. Mefiboset, cucu tuanmu itu, akan tetap makan sehidangan dengan aku." Ziba mempunyai lima belas orang anak laki-laki dan dua puluh orang hamba.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 11, 'Berkatalah Ziba kepada raja: "Hambamu ini akan melakukan tepat seperti yang diperintahkan tuanku raja kepadanya." Dan Mefiboset makan sehidangan dengan Daud sebagai salah seorang anak raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 12, 'Mefiboset mempunyai seorang anak laki-laki yang kecil, yang bernama Mikha. Semua orang yang diam di rumah Ziba adalah hamba-hamba Mefiboset.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 9, 13, 'Demikianlah Mefiboset diam di Yerusalem, sebab ia tetap makan sehidangan dengan raja. Adapun kedua kakinya timpang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 1, 'Sesudah itu matilah raja bani Amon; dan Hanun, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 2, 'Lalu berkatalah Daud: "Aku akan menunjukkan persahabatan kepada Hanun bin Nahas, sama seperti ayahnya telah menunjukkan persahabatan kepadaku." Sebab itu Daud menyuruh menyampaikan pesan turut berdukacita kepadanya dengan perantaraan pegawai-pegawainya karena kematian ayahnya. Tetapi ketika pegawai-pegawai Daud sampai ke negeri bani Amon itu,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 3, 'berkatalah pemuka-pemuka bani Amon itu kepada Hanun, tuan mereka: "Apakah menurut anggapanmu Daud hendak menghormati ayahmu, karena ia telah mengutus kepadamu orang-orang yang menyampaikan pesan turut berdukacita? Bukankah dengan maksud untuk menyelidik kota ini, untuk mengintainya dan menghancurkannya maka Daud mengutus pegawai-pegawainya itu kepadamu?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 4, 'Lalu Hanun menyuruh menangkap pegawai-pegawai Daud itu, disuruhnya mencukur setengah dari janggut mereka dan memotong pakaian mereka pada bagian tengah sampai pantat mereka, kemudian dilepasnya mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 5, 'Hal ini diberitahukan kepada Daud, lalu disuruhnya orang menemui mereka, sebab orang-orang itu sangat dipermalukan. Raja berkata: "Tinggallah di Yerikho sampai janggutmu itu tumbuh, kemudian datanglah kembali."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 6, 'Setelah dilihat bani Amon, bahwa mereka dibenci Daud, maka bani Amon itu menyuruh orang menyewa dari orang Aram-Bet-Rehob dan orang Aram dari Zoba dua puluh ribu orang pasukan berjalan kaki, dari raja negeri Maakha seribu orang dan dari orang-orang Tob dua belas ribu orang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 7, 'Ketika Daud mendengar hal itu, disuruhnyalah Yoab maju dengan segenap pasukan pahlawan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 8, 'Lalu bani Amon maju, diaturnya barisan perangnya di depan pintu gerbang, sedang orang Aram dari Zoba dan dari Rehob dan orang-orang Tob dan Maakha ada tersendiri di padang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 9, 'Ketika Yoab melihat, bahwa serangan itu mengancam dia dari depan dan dari belakang, maka dipilihnyalah sebagian dari orang pilihan Israel, lalu ia mengatur barisan mereka berhadapan dengan orang Aram itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 10, 'Selebihnya dari rakyat itu ditempatkannya di bawah pimpinan Abisai, adiknya, yang mengatur barisan mereka berhadapan dengan bani Amon itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 11, 'Lalu berkatalah Yoab: "Jika orang Aram itu lebih kuat dari padaku, maka haruslah engkau menolong aku, tetapi jika bani Amon itu lebih kuat dari padamu, maka aku akan datang menolong engkau.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 12, 'Kuatkanlah hatimu dan marilah kita menguatkan hati untuk bangsa kita dan untuk kota-kota Allah kita. TUHAN kiranya melakukan yang baik di mata-Nya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 13, 'Lalu Yoab dan tentara yang bersama-sama dengan dia maju berperang melawan orang Aram dan orang-orang itu melarikan diri dari hadapannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 14, 'Ketika bani Amon melihat, bahwa orang Aram sudah melarikan diri, maka merekapun larilah dari hadapan Abisai dan masuk ke dalam kota. Sesudah itu pulanglah Yoab setelah memerangi bani Amon dan sampailah ia ke Yerusalem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 15, 'Ketika orang Aram melihat, bahwa mereka telah terpukul kalah oleh orang Israel, maka berkumpullah mereka bersama-sama.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 16, 'Juga Hadadezer menyuruh orang Aram yang di seberang sungai Efrat maju berperang; mereka sampai ke Helam di bawah pimpinan Sobakh, panglima tentara Hadadezer.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 17, 'Setelah hal itu diberitahukan kepada Daud, maka dikumpulkannya seluruh orang Israel, diseberanginya sungai Yordan, lalu sampai ke Helam. Orang Aram mengatur barisannya berhadapan dengan Daud dan bertempur melawan dia,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 18, 'tetapi orang Aram itu lari dari hadapan orang Israel, dan Daud membunuh dari orang Aram itu tujuh ratus ekor kuda kereta dan empat puluh ribu orang pasukan berkuda. Sobakh, panglima tentara mereka, dilukainya sedemikian, hingga ia mati di sana.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 10, 19, 'Ketika dilihat semua raja, yang takluk kepada Hadadezer, bahwa mereka telah terpukul kalah oleh orang Israel, maka mereka mengadakan perdamaian dengan orang Israel dan takluk kepada mereka; sesudah itu takutlah orang Aram memberi pertolongan lagi kepada bani Amon.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 1, 'Pada pergantian tahun, pada waktu raja-raja biasanya maju berperang, maka Daud menyuruh Yoab maju beserta orang-orangnya dan seluruh orang Israel. Mereka memusnahkan bani Amon dan mengepung kota Raba, sedang Daud sendiri tinggal di Yerusalem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 2, 'Sekali peristiwa pada waktu petang, ketika Daud bangun dari tempat pembaringannya, lalu berjalan-jalan di atas sotoh istana, tampak kepadanya dari atas sotoh itu seorang perempuan sedang mandi; perempuan itu sangat elok rupanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 3, 'Lalu Daud menyuruh orang bertanya tentang perempuan itu dan orang berkata: "Itu adalah Batsyeba binti Eliam, isteri Uria orang Het itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 4, 'Sesudah itu Daud menyuruh orang mengambil dia. Perempuan itu datang kepadanya, lalu Daud tidur dengan dia. Perempuan itu baru selesai membersihkan diri dari kenajisannya. Kemudian pulanglah perempuan itu ke rumahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 5, 'Lalu mengandunglah perempuan itu dan disuruhnya orang memberitahukan kepada Daud, demikian: "Aku mengandung."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 6, 'Lalu Daud menyuruh orang kepada Yoab mengatakan: "Suruhlah Uria, orang Het itu, datang kepadaku." Maka Yoab menyuruh Uria menghadap Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 7, 'Ketika Uria masuk menghadap dia, bertanyalah Daud tentang keadaan Yoab dan tentara dan keadaan perang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 8, 'Kemudian berkatalah Daud kepada Uria: "Pergilah ke rumahmu dan basuhlah kakimu." Ketika Uria keluar dari istana, maka orang menyusul dia dengan membawa hadiah raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 9, 'Tetapi Uria membaringkan diri di depan pintu istana bersama-sama hamba tuannya dan tidak pergi ke rumahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 10, 'Diberitahukan kepada Daud, demikian: "Uria tidak pergi ke rumahnya." Lalu berkatalah Daud kepada Uria: "Bukankah engkau baru pulang dari perjalanan? Mengapa engkau tidak pergi ke rumahmu?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 11, 'Tetapi Uria berkata kepada Daud: "Tabut serta orang Israel dan orang Yehuda diam dalam pondok, juga tuanku Yoab dan hamba-hamba tuanku sendiri berkemah di padang; masakan aku pulang ke rumahku untuk makan minum dan tidur dengan isteriku? Demi hidupmu dan demi nyawamu, aku takkan melakukan hal itu!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 12, 'Kata Daud kepada Uria: "Tinggallah hari ini di sini. Besok aku akan melepas engkau pergi." Jadi Uria tinggal di Yerusalem pada hari itu. Keesokan harinya', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 13, 'Daud memanggil dia untuk makan dan minum dengan dia, dan Daud membuatnya mabuk. Pada waktu malam keluarlah Uria untuk berbaring tidur di tempat tidurnya, bersama-sama hamba-hamba tuannya. Ia tidak pergi ke rumahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 14, 'Paginya Daud menulis surat kepada Yoab dan mengirimkannya dengan perantaraan Uria.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 15, 'Ditulisnya dalam surat itu, demikian: "Tempatkanlah Uria di barisan depan dalam pertempuran yang paling hebat, kemudian kamu mengundurkan diri dari padanya, supaya ia terbunuh mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 16, 'Pada waktu Yoab mengepung kota Raba, ia menyuruh Uria pergi ke tempat yang diketahuinya ada lawan yang gagah perkasa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 17, 'Ketika orang-orang kota itu keluar menyerang dan berperang melawan Yoab, maka gugurlah beberapa orang dari tentara, dari anak buah Daud; juga Uria, orang Het itu, mati.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 18, 'Kemudian Yoab menyuruh orang memberitahukan kepada Daud jalannya pertempuran itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 19, 'Ia memerintahkan kepada suruhan itu, demikian: "Jika engkau sudah selesai mengabarkan jalannya pertempuran itu kepada raja,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 20, 'dan jikalau raja menjadi geram dan berkata kepadamu: Mengapa kamu demikian dekat ke kota itu untuk berperang? Tidakkah kamu tahu, bahwa orang akan memanah dari atas tembok?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 21, 'Siapakah yang menewaskan Abimelekh bin Yerubeset? Bukankah seorang perempuan menimpakan batu kilangan kepadanya dari atas tembok, sehingga ia mati di Tebes? Mengapa kamu demikian dekat ke tembok itu? ?maka haruslah engkau berkata: Juga hambamu Uria, orang Het itu, sudah mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 22, 'Lalu pergilah suruhan itu dan sesampainya ia memberitahukan kepada Daud segala yang diperintahkan Yoab kepadanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 23, 'Suruhan itu berkata kepada Daud: "Orang-orang itu lebih kuat dari pada kami dan keluar menyerang kami di padang. Tetapi kami mendesak mereka kembali sampai ke lobang pintu gerbang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 24, 'Pada waktu itu pemanah-pemanah menembak kepada hamba-hambamu dari atas tembok, sehingga beberapa dari hamba raja mati; juga hambamu Uria, orang Het itu, sudah mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 25, 'Kemudian berkatalah Daud kepada suruhan itu: "Beginilah kaukatakan kepada Yoab: Janganlah sebal hatimu karena perkara ini, sebab sudah biasa pedang makan orang ini atau orang itu. Sebab itu perhebatlah seranganmu terhadap kota itu dan runtuhkanlah itu. Demikianlah kau harus kuatkan hatinya!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 26, 'Ketika didengar isteri Uria, bahwa Uria, suaminya, sudah mati, maka merataplah ia karena kematian suaminya itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 11, 27, 'Setelah lewat waktu berkabung, maka Daud menyuruh membawa perempuan itu ke rumahnya. Perempuan itu menjadi isterinya dan melahirkan seorang anak laki-laki baginya. Tetapi hal yang telah dilakukan Daud itu adalah jahat di mata TUHAN.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 1, 'TUHAN mengutus Natan kepada Daud. Ia datang kepada Daud dan berkata kepadanya: "Ada dua orang dalam suatu kota: yang seorang kaya, yang lain miskin.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 2, 'Si kaya mempunyai sangat banyak kambing domba dan lembu sapi;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 3, 'si miskin tidak mempunyai apa-apa, selain dari seekor anak domba betina yang kecil, yang dibeli dan dipeliharanya. Anak domba itu menjadi besar padanya bersama-sama dengan anak-anaknya, makan dari suapnya dan minum dari pialanya dan tidur di pangkuannya, seperti seorang anak perempuan baginya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 4, 'Pada suatu waktu orang kaya itu mendapat tamu; dan ia merasa sayang mengambil seekor dari kambing dombanya atau lembunya untuk memasaknya bagi pengembara yang datang kepadanya itu. Jadi ia mengambil anak domba betina kepunyaan si miskin itu, dan memasaknya bagi orang yang datang kepadanya itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 5, 'Lalu Daud menjadi sangat marah karena orang itu dan ia berkata kepada Natan: "Demi TUHAN yang hidup: orang yang melakukan itu harus dihukum mati.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 6, 'Dan anak domba betina itu harus dibayar gantinya empat kali lipat, karena ia telah melakukan hal itu dan oleh karena ia tidak kenal belas kasihan."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 7, 'Kemudian berkatalah Natan kepada Daud: "Engkaulah orang itu! Beginilah firman TUHAN, Allah Israel: Akulah yang mengurapi engkau menjadi raja atas Israel dan Akulah yang melepaskan engkau dari tangan Saul.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 8, 'Telah Kuberikan isi rumah tuanmu kepadamu, dan isteri-isteri tuanmu ke dalam pangkuanmu. Aku telah memberikan kepadamu kaum Israel dan Yehuda; dan seandainya itu belum cukup, tentu Kutambah lagi ini dan itu kepadamu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 9, 'Mengapa engkau menghina TUHAN dengan melakukan apa yang jahat di mata-Nya? Uria, orang Het itu, kaubiarkan ditewaskan dengan pedang; isterinya kauambil menjadi isterimu, dan dia sendiri telah kaubiarkan dibunuh oleh pedang bani Amon.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 10, 'Oleh sebab itu, pedang tidak akan menyingkir dari keturunanmu sampai selamanya, karena engkau telah menghina Aku dan mengambil isteri Uria, orang Het itu, untuk menjadi isterimu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 11, 'Beginilah firman TUHAN: Bahwasanya malapetaka akan Kutimpakan ke atasmu yang datang dari kaum keluargamu sendiri. Aku akan mengambil isteri-isterimu di depan matamu dan memberikannya kepada orang lain; orang itu akan tidur dengan isteri-isterimu di siang hari.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 12, 'Sebab engkau telah melakukannya secara tersembunyi, tetapi Aku akan melakukan hal itu di depan seluruh Israel secara terang-terangan."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 13, 'Lalu berkatalah Daud kepada Natan: "Aku sudah berdosa kepada TUHAN." Dan Natan berkata kepada Daud: "TUHAN telah menjauhkan dosamu itu: engkau tidak akan mati.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 14, 'Walaupun demikian, karena engkau dengan perbuatan ini telah sangat menista TUHAN, pastilah anak yang lahir bagimu itu akan mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 15, 'Kemudian pergilah Natan ke rumahnya. Dan TUHAN menulahi anak yang dilahirkan bekas isteri Uria bagi Daud, sehingga sakit.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 16, 'Lalu Daud memohon kepada Allah oleh karena anak itu, ia berpuasa dengan tekun dan apabila ia masuk ke dalam, semalam-malaman itu ia berbaring di tanah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 17, 'Maka datanglah kepadanya para tua-tua yang di rumahnya untuk meminta ia bangun dari lantai, tetapi ia tidak mau; juga ia tidak makan bersama-sama dengan mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 18, 'Pada hari yang ketujuh matilah anak itu. Dan pegawai-pegawai Daud takut memberitahukan kepadanya, bahwa anak itu sudah mati. Sebab mereka berkata: "Ketika anak itu masih hidup, kita telah berbicara kepadanya, tetapi ia tidak menghiraukan perkataan kita. Bagaimana kita dapat mengatakan kepadanya: anak itu sudah mati? Jangan-jangan ia mencelakakan diri!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 19, 'Ketika Daud melihat, bahwa pegawai-pegawainya berbisik-bisik, mengertilah ia, bahwa anak itu sudah mati. Lalu Daud bertanya kepada pegawai-pegawainya: "Sudah matikah anak itu?" Jawab mereka: "Sudah."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 20, 'Lalu Daud bangun dari lantai, ia mandi dan berurap dan bertukar pakaian; ia masuk ke dalam rumah TUHAN dan sujud menyembah. Sesudah itu pulanglah ia ke rumahnya, dan atas permintaannya dihidangkan kepadanya roti, lalu ia makan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 21, 'Berkatalah pegawai-pegawainya kepadanya: "Apakah artinya hal yang kauperbuat ini? Oleh karena anak yang masih hidup itu, engkau berpuasa dan menangis, tetapi sesudah anak itu mati, engkau bangun dan makan!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 22, 'Jawabnya: "Selagi anak itu hidup, aku berpuasa dan menangis, karena pikirku: siapa tahu TUHAN mengasihani aku, sehingga anak itu tetap hidup.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 23, 'Tetapi sekarang ia sudah mati, mengapa aku harus berpuasa? Dapatkah aku mengembalikannya lagi? Aku yang akan pergi kepadanya, tetapi ia tidak akan kembali kepadaku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 24, 'Kemudian Daud menghibur hati Batsyeba, isterinya; ia menghampiri perempuan itu dan tidur dengan dia, dan perempuan itu melahirkan seorang anak laki-laki, lalu Daud memberi nama Salomo kepada anak itu. TUHAN mengasihi anak ini', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 25, 'dan dengan perantaraan nabi Natan Ia menyuruh menamakan anak itu Yedija, oleh karena TUHAN.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 26, 'Yoab berperang melawan Raba, kota bani Amon dan ia merebut kota kerajaan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 27, 'Lalu Yoab menyuruh orang kepada Daud dengan pesan: "Aku berperang melawan kota Raba, dan telah merebut pula kota air.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 28, 'Oleh sebab itu, kumpulkanlah sisa tentara, kepunglah kota itu dan rebutlah, supaya jangan aku yang merebut kota itu dan jangan namaku menjadi juga nama kota itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 29, 'Sesudah itu Daud mengumpulkan seluruh tentara, ia berangkat ke kota Raba dan berperang melawannya, lalu merebutnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 30, 'Ia mengambil mahkota dari kepala raja mereka, beratnya setalenta emas, bertatahkan sebuah batu permata yang mahal dan itu dikenakan pada kepala Daud. Juga diangkutnya banyak sekali jarahan dari kota itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 12, 31, 'Penduduk kota itu diangkutnya dan dipaksanya bekerja dengan gergaji, penggerek besi dan kapak; juga dipekerjakannya mereka di tempat pembuatan batu bata. Demikianlah juga diperlakukan Daud segala kota bani Amon. Sesudah itu pulanglah Daud dengan seluruh tentara ke Yerusalem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 1, 'Sesudah itu terjadilah yang berikut. Absalom bin Daud mempunyai seorang adik perempuan yang cantik, namanya Tamar; dan Amnon bin Daud jatuh cinta kepadanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 2, 'Hati Amnon sangat tergoda, sehingga ia jatuh sakit karena Tamar, saudaranya itu, sebab anak perempuan itu masih perawan dan menurut anggapan Amnon mustahil untuk melakukan sesuatu terhadap dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 3, 'Amnon mempunyai seorang sahabat bernama Yonadab, anak Simea kakak Daud. Yonadab itu seorang yang sangat cerdik.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 4, 'Katanya kepada Amnon: "Hai anak raja, mengapa engkau demikian merana setiap pagi? Tidakkah lebih baik engkau memberitahukannya kepadaku?" Kata Amnon kepadanya: "Aku cinta kepada Tamar, adik perempuan Absalom, saudaraku itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 5, 'Lalu berkatalah Yonadab kepadanya: "Berbaringlah di tempat tidurmu dan berbuat pura-pura sakit. Apabila ayahmu datang menengok engkau, maka haruslah engkau berkata kepadanya: Izinkanlah adikku Tamar datang memberi aku makan. Apabila ia menyediakan makanan di depan mataku, sehingga aku dapat melihatnya, maka aku akan memakannya dari tangannya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 6, 'Sesudah itu berbaringlah Amnon dan berbuat pura-pura sakit. Ketika raja datang menengok dia, berkatalah Amnon kepada raja: "Izinkanlah adikku Tamar datang membuat barang dua kue di depan mataku, supaya aku memakannya dari tangannya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 7, 'Lalu Daud menyuruh orang kepada Tamar, ke rumahnya, dengan pesan: "Pergilah ke rumah Amnon, kakakmu dan sediakanlah makanan baginya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 8, 'Maka Tamar pergi ke rumah Amnon, kakaknya, yang sedang berbaring-baring, lalu anak perempuan itu mengambil adonan, meremasnya dan membuat kue di depan matanya, kemudian dibakarnya kue itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 9, 'Sesudah itu gadis itu mengambil kuali dan mengeluarkan isinya di depan Amnon, tetapi ia tidak mau makan. Berkatalah Amnon: "Suruhlah setiap orang keluar meninggalkan aku." Lalu keluarlah setiap orang meninggalkan dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 10, 'Lalu berkatalah Amnon kepada Tamar: "Bawalah makanan itu ke dalam kamar, supaya aku memakannya dari tanganmu." Tamar mengambil kue yang disediakannya itu, lalu membawanya kepada Amnon, kakaknya, ke dalam kamar.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 11, 'Ketika gadis itu menghidangkannya kepadanya supaya ia makan, dipegangnyalah gadis itu dan berkata kepadanya: "Marilah tidur dengan aku, adikku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 12, 'Tetapi gadis itu berkata kepadanya: "Tidak kakakku, jangan perkosa aku, sebab orang tidak berlaku seperti itu di Israel. Janganlah berbuat noda seperti itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 13, 'Dan aku, ke manakah kubawa kecemaranku? Dan engkau ini, engkau akan dianggap sebagai orang yang bebal di Israel. Oleh sebab itu, berbicaralah dengan raja, sebab ia tidak akan menolak memberikan aku kepadamu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 14, 'Tetapi Amnon tidak mau mendengarkan perkataannya, dan sebab ia lebih kuat dari padanya, diperkosanyalah dia, lalu tidur dengan dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 15, 'Kemudian timbullah kebencian yang sangat besar pada Amnon terhadap gadis itu, bahkan lebih besar benci yang dirasanya kepada gadis itu dari pada cinta yang dirasanya sebelumnya. Lalu Amnon berkata kepadanya: "Bangunlah, enyahlah!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 16, 'Lalu berkatalah gadis itu kepadanya: "Tidak kakakku, sebab menyuruh aku pergi adalah lebih jahat dari pada apa yang telah kaulakukan kepadaku tadi." Tetapi Amnon tidak mau mendengarkan dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 17, 'Dipanggilnya orang muda yang melayani dia, katanya: "Suruhlah perempuan ini pergi dari padaku dan kuncilah pintu di belakangnya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 18, 'Gadis itu memakai baju kurung yang maha indah; sebab demikianlah puteri-puteri raja yang masih perawan berpakaikan baju kurung panjang. Kemudian pelayan itu menyuruh dia keluar, lalu mengunci pintu di belakangnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 19, 'Lalu Tamar menaruh abu di atas kepalanya, mengoyakkan baju kurung yang maha indah yang dipakainya, meletakkan tangannya di atas kepalanya dan pergilah ia sambil meratap dengan nyaring.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 20, 'Bertanyalah Absalom, kakaknya, kepadanya: "Apakah Amnon, kakakmu itu, bersetubuh dengan engkau? Maka sekarang, adikku, diamlah saja, bukankah ia kakakmu, janganlah begitu memikirkan perkara itu." Lalu Tamar tinggal di rumah Absalom, kakaknya itu, seorang diri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 21, 'Ketika segala perkara itu didengar raja Daud sangat marahlah ia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 22, 'Dan Absalom tidak berkata-kata dengan Amnon, baik tentang yang jahat maupun tentang yang baik, tetapi Absalom membenci Amnon, sebab ia telah memperkosa Tamar, adiknya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 23, 'Sesudah lewat dua tahun, Absalom mengadakan pengguntingan bulu domba di Baal-Hazor yang dekat kota Efraim. Lalu Absalom mengundang semua anak raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 24, 'Kemudian Absalom menghadap raja, lalu berkata: "Hambamu ini mengadakan pengguntingan bulu domba. Kiranya raja dan pegawai-pegawainya ikut bersama-sama dengan hambamu ini."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 25, 'Tetapi raja berkata kepada Absalom: "Maaf, anakku, jangan kami semua pergi, supaya kami jangan menyusahkan engkau." Lalu Absalom mendesak, tetapi raja tidak mau pergi, ia hanya memberi restu kepadanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 26, 'Kemudian berkatalah Absalom: "Kalau tidak, izinkanlah kakakku Amnon pergi beserta kami." Tetapi raja menjawabnya: "Apa gunanya ia pergi bersama-sama dengan engkau?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 27, 'Tetapi ketika Absalom mendesak, diizinkannyalah Amnon dan semua anak raja pergi beserta dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 28, 'Lalu Absalom memerintahkan orang-orangnya, demikian: "Perhatikan! Apabila hati Amnon menjadi gembira karena anggur, dan aku berkata kepadamu: Paranglah Amnon, maka haruslah kamu membunuh dia. Jangan takut. Bukankah aku yang memerintahkannya kepadamu? Kuatkanlah hatimu dan tunjukkanlah dirimu sebagai orang yang gagah perkasa!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 29, 'Orang-orang Absalom memperlakukan Amnon seperti yang diperintahkan Absalom. Lalu bangunlah semua anak raja itu, mereka menaiki bagalnya masing-masing dan melarikan diri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 30, 'Mereka masih di tengah jalan, ketika kabar sampai kepada Daud, demikian: "Absalom telah membunuh semua anak raja, tidak ada seorangpun dari mereka yang lolos."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 31, 'Lalu bangunlah raja, dikoyakkannya pakaiannya dan berbaring di lantai, dan semua pegawainya yang hadir padanya mengoyakkan pakaian mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 32, 'Maka berbicaralah Yonadab, anak Simea, kakak Daud, katanya: "Janganlah tuanku menyangka, bahwa semua orang muda anak-anak raja itu, telah dibunuh. Hanya Amnon yang mati, sebab hal itu telah terlihat pada air muka Absalom, sejak Amnon memperkosa Tamar, adiknya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 33, 'Jadi, janganlah tuanku raja menaruh pikiran dalam hatinya, bahwa semua anak raja itu sudah mati, sebab hanya Amnon yang mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 34, 'Absalom melarikan diri. Ketika orang yang berjaga-jaga melayangkan pandangnya, maka terlihatlah olehnya sejumlah besar orang datang dari jurusan Horonaim, sepanjang sisi pegunungan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 35, 'Berkatalah Yonadab kepada raja: "Lihat, anak-anak raja datang! Benar seperti kata hambamu ini."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 36, 'Baru saja ia habis berkata, datanglah anak-anak raja itu. Mereka menangis dengan suara nyaring. Juga raja dan semua pegawainya menangis dengan amat keras.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 37, 'Absalom telah melarikan diri dan telah pergi kepada Talmai bin Amihur, raja negeri Gesur. Dan Daud berdukacita berhari-hari lamanya karena anaknya itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 38, 'Absalom telah melarikan diri dan telah pergi ke Gesur; ia tinggal di sana tiga tahun lamanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 13, 39, 'Lalu raja tidak lagi marah terhadap Absalom, sebab kesedihan hatinya karena kematian Amnon telah surut.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 1, 'Ketika Yoab, anak Zeruya, mengetahui, bahwa hati raja merindukan Absalom,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 2, 'maka ia menyuruh orang ke Tekoa menjemput dari sana seorang perempuan yang bijaksana, lalu ia berkata kepada perempuan itu: "Berlakulah pura-pura berkabung, dan pakailah pakaian berkabung, janganlah berurap dengan minyak, dan berlakulah seperti seorang perempuan yang telah lama berkabung karena seorang mati.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 3, 'Kemudian masuklah menghadap raja dan berbicaralah kepadanya seperti ini" ?lalu Yoab menaruh perkataannya ke dalam mulut perempuan itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 4, 'Ketika perempuan Tekoa itu masuk menghadap raja, sujudlah ia dengan mukanya ke tanah dan menyembah, sambil berkata: "Tolonglah, ya tuanku raja!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 5, 'Raja bertanya kepadanya: "Ada apa?" Jawabnya: "Ah, aku ini seorang janda, sebab suamiku sudah mati.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 6, 'Hambamu ini mempunyai dua orang anak laki-laki; mereka berkelahi di padang dan karena tidak ada yang memisahkan, maka yang satu memukul yang lain dan membunuh dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 7, 'Dan sekarang seluruh kaum keluarga bangkit melawan hambamu ini, dan mereka berkata: Serahkanlah orang yang membunuh saudaranya itu, supaya kami menghukum dia mati ganti nyawa saudaranya yang telah dibunuhnya itu, dan supaya kami memunahkan juga ahli waris itu. Mereka hendak memunahkan keturunanku yang masih tersisa itu dengan tidak meninggalkan nama atau keturunan bagi suamiku di muka bumi."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 8, 'Lalu berbicaralah raja kepada perempuan itu: "Pulanglah ke rumahmu, mengenai engkau akan kuberi perintah."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 9, 'Perempuan Tekoa itu berkata kepada raja: "Aku dan keluargaku akan menanggung kesalahan itu, ya tuanku raja, tetapi raja dan takhtanya tak bersalah."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 10, 'Lalu berkatalah raja: "Jika ada orang yang mengatakan apa-apa lagi terhadap engkau, bawalah orang itu menghadap aku, maka ia tidak akan mengusik engkau lagi."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 11, 'Kata perempuan itu: "Kiranya raja ingat kepada TUHAN, Allahmu, supaya si penuntut tebusan darah jangan terlalu banyak menimbulkan kemusnahan dan supaya mereka jangan memunahkan anakku itu." Lalu berkatalah raja: "Demi TUHAN yang hidup?sehelai rambutpun dari kepala anakmu itu takkan jatuh ke bumi!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 12, 'Kemudian berkatalah perempuan itu: "Izinkanlah hambamu ini berkata sepatah kata lagi kepada tuanku raja." Jawabnya: "Katakanlah."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 13, 'Berkatalah perempuan itu: "Mengapa raja merancang hal yang demikian terhadap umat Allah? Oleh karena tuanku mengucapkan perkataan ini, maka tuanku sendirilah yang bersalah dengan tidak mengizinkan pulang orang yang telah dibuangnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 14, 'Sebab kita pasti mati, kita seperti air yang tercurah ke bumi, yang tidak terkumpulkan. Tetapi Allah tidak mengambil nyawa orang, melainkan Ia merancang supaya seorang yang terbuang jangan tinggal terbuang dari pada-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 15, 'Maka sekarang, aku datang mengatakan perkataan ini kepada tuanku raja karena orang banyak itu telah menakut-nakuti aku. Sebab itu pikir hambamu ini: baiklah aku berbicara dahulu dengan raja, mungkin raja mengabulkan permohonan hambanya ini;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 16, 'sebab raja akan mendengarkan aku dan akan melepaskan hambanya ini dari tangan orang yang hendak memunahkan aku dan anakku bersama-sama dari milik pusaka Allah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 17, 'Juga hambamu ini berpikir: perkataan tuanku raja tentulah akan menenangkan hati, sebab seperti malaikat Allah, demikianlah tuanku raja, yang dapat membeda-bedakan apa yang baik dan jahat. Dan TUHAN, Allahmu, kiranya menyertai tuanku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 18, 'Lalu raja menjawab, katanya kepada perempuan itu: "Baiklah jangan sembunyikan kepadaku apa yang hendak kutanyakan kepadamu." Kata perempuan itu: "Berkatalah kiranya tuanku raja!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 19, 'Kemudian bertanyalah raja: "Adakah Yoab campur tangan dengan engkau dalam semuanya ini?" Perempuan itu menjawab: "Demi hidupmu, tuanku raja, tidaklah mungkin untuk menyimpang ke kanan atau ke kiri dari segala yang tuanku raja katakan. Sesungguhnya hambamu Yoab yang memerintahkan daku; dialah yang menaruh ke dalam mulut hambamu segala perkataan ini.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 20, 'Dengan maksud untuk mengubah rupa perkara itu maka hambamu Yoab melakukan perkara ini. Tetapi tuanku bijaksana sama seperti malaikat Allah, sehingga mengetahui semua yang terjadi di bumi."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 21, 'Sesudah itu berkatalah raja kepada Yoab: "Baik, kukabulkan permohonan ini. Pergilah, bawalah kembali orang muda Absalom itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 22, 'Lalu sujudlah Yoab dengan mukanya ke tanah dan menyembah sambil memohon berkat bagi raja. Dan Yoab berkata: "Pada hari ini hambamu mengetahui bahwa tuanku raja suka kepada hamba, karena tuanku telah mengabulkan permohonan hambamu ini."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 23, 'Lalu bangunlah Yoab, ia pergi ke Gesur dan membawa Absalom ke Yerusalem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 24, 'Tetapi berkatalah raja: "Ia harus pergi ke rumahnya sendiri, jangan ia datang ke hadapanku." Jadi pergilah Absalom ke rumahnya sendiri dan tidak datang ke hadapan raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 25, 'Di seluruh Israel tidak ada yang begitu banyak dipuji kecantikannya seperti Absalom. Dari telapak kakinya sampai ujung kepalanya tidak ada cacat padanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 26, 'Apabila ia mencukur rambutnya?pada akhir tiap-tiap tahun ia mencukurnya karena menjadi terlalu berat baginya?maka ditimbangnya rambutnya itu, dua ratus syikal beratnya, menurut batu timbangan raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 27, 'Bagi Absalom lahir tiga orang anak laki-laki dan seorang anak perempuan, yang bernama Tamar. Ia seorang perempuan yang cantik.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 28, 'Setelah Absalom diam di Yerusalem genap dua tahun lamanya, dengan tidak datang ke hadapan raja,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 29, 'maka Absalom menyuruh memanggil Yoab untuk diutus kepada raja. Tetapi ia tidak mau datang kepadanya. Kemudian disuruhnya memanggil dia lagi, untuk kedua kalinya, tetapi ia tidak mau datang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 30, 'Lalu berkatalah ia kepada hamba-hambanya: "Lihat, ladang Yoab ada di sisi ladangku dan di sana ada jelainya. Pergilah, bakarlah itu." Maka hamba-hamba Absalom membakar ladang itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 31, 'Lalu Yoab pergi mendapatkan Absalom ke rumahnya, dan bertanya kepadanya: "Mengapa hamba-hambamu membakar ladang kepunyaanku itu?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 32, 'Jawab Absalom kepada Yoab: "Ya, aku telah menyuruh orang kepadamu mengatakan: datanglah ke mari, supaya aku mengutus engkau kepada raja untuk mengatakan: apa gunanya aku datang dari Gesur? Lebih baik aku masih tinggal di sana. Maka sekarang, aku mau datang ke hadapan raja. Jika aku bersalah, biarlah ia menghukum aku mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 14, 33, 'Kemudian masuklah Yoab menghadap raja dan memberitahukan hal itu kepadanya. Raja memanggil Absalom, dan ia masuk menghadap raja, lalu sujud ke hadapan raja dengan mukanya ke tanah; lalu raja mencium Absalom.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 1, 'Sesudah itu Absalom menyediakan baginya sebuah kereta serta kuda dan lima puluh orang yang berlari di depannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 2, 'Maka setiap pagi berdirilah Absalom di tepi jalan yang menuju pintu gerbang. Setiap orang yang mempunyai perkara dan yang mau masuk menghadap raja untuk diadili perkaranya, orang itu dipanggil Absalom dan ditanyai: "Dari kota manakah engkau?" Apabila ia menjawab: "Hambamu ini datang dari suku Israel anu,"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 3, 'maka berkatalah Absalom kepadanya: "Lihat, perkaramu itu baik dan benar, tetapi dari pihak raja tidak ada seorangpun yang mau mendengarkan engkau."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 4, 'Lagi kata Absalom: "Sekiranya aku diangkat menjadi hakim di negeri ini! Maka setiap orang yang mempunyai perkara atau pertikaian hukum boleh datang kepadaku, dan aku akan menyelesaikan perkaranya dengan adil."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 5, 'Apabila seseorang datang mendekat untuk sujud menyembah kepadanya, maka diulurkannyalah tangannya, dipegangnya orang itu dan diciumnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 6, 'Cara yang demikianlah diperbuat Absalom kepada semua orang Israel yang mau masuk menghadap untuk diadili perkaranya oleh raja, dan demikianlah Absalom mencuri hati orang-orang Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 7, 'Sesudah lewat empat tahun bertanyalah Absalom kepada raja: "Izinkanlah aku pergi, supaya di Hebron aku bayar nazarku, yang telah kuikrarkan kepada TUHAN.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 8, 'Sebab hambamu ini, ketika masih tinggal di Gesur, di Aram, telah bernazar, demikian: Jika TUHAN sungguh-sungguh memulangkan aku ke Yerusalem, maka aku akan beribadah kepada TUHAN."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 9, 'Lalu berkatalah raja kepadanya: "Pergilah dengan selamat." Maka berkemaslah Absalom dan pergi ke Hebron.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 10, 'Dalam pada itu Absalom telah mengirim utusan-utusan rahasia kepada segenap suku Israel dengan pesan: "Segera sesudah kamu mendengar bunyi sangkakala, berserulah: Absalom sudah menjadi raja di Hebron!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 11, 'Beserta Absalom turut pergi dua ratus orang dari Yerusalem, orang-orang undangan yang turut pergi tanpa curiga dan tanpa mengetahui apapun tentang perkara itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 12, 'Ketika Absalom hendak mempersembahkan korban, disuruhnya datang Ahitofel, orang Gilo itu, penasihat Daud, dari Gilo, kotanya. Demikianlah persepakatan gelap itu menjadi kuat, dan makin banyaklah rakyat yang memihak Absalom.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 13, 'Lalu datanglah seseorang mengabarkan kepada Daud, katanya: "Hati orang Israel telah condong kepada Absalom."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 14, 'Kemudian berbicaralah Daud kepada semua pegawainya yang ada bersama-sama dengan dia di Yerusalem: "Bersiaplah, marilah kita melarikan diri, sebab jangan-jangan kita tidak akan luput dari pada Absalom. Pergilah dengan segera, supaya ia jangan dapat lekas menyusul kita, dan mendatangkan celaka atas kita dan memukul kota ini dengan mata pedang!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 15, 'Para pegawai raja berkata kepada raja: "Terserah kepada tuanku raja! Hamba-hambamu ini siap!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 16, 'Lalu keluarlah raja dan seisi rumahnya mengiringi dia; sepuluh orang gundik ditinggalkan raja untuk menunggui istana.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 17, 'Maka keluarlah raja dan seluruh orang-orangnya mengiringi dia. Dekat rumah yang terakhir mereka berhenti', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 18, 'sedang semua pegawainya berjalan melewatinya, juga semua orang Kreti dan semua orang Pleti. Juga semua orang Gat, enam ratus orang banyaknya, yang mengiringi dia sejak dari Gat, berjalan melewati raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 19, 'Lalu bertanyalah raja kepada Itai, orang Gat itu: "Mengapa pula engkau berjalan beserta kami? Pulanglah dan tinggallah bersama-sama raja, sebab engkau orang asing, lagipula engkau orang buangan dari tempat asalmu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 20, 'Baru kemarin engkau datang, masakan pada hari ini aku akan membawa engkau mengembara bersama-sama kami, padahal aku harus pergi entah ke mana. Pulanglah dan bawalah juga saudara-saudaramu pulang; mudah-mudahan TUHAN menunjukkan kasih dan setia kepadamu!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 21, 'Tetapi Itai menjawab raja: "Demi TUHAN yang hidup, dan demi hidup tuanku raja, di mana tuanku raja ada, baik hidup atau mati, di situ hambamu juga ada."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 22, 'Lalu berkatalah Daud kepada Itai: "Jika demikian, berjalanlah lewat." Kemudian lewatlah Itai, orang Gat itu, bersama-sama dengan semua orangnya dan semua anak yang menyertai dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 23, 'Seluruh negeri menangis dengan suara keras, ketika seluruh rakyat berjalan lewat. Raja menyeberangi sungai Kidron dan seluruh rakyat berjalan ke arah padang gurun.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 24, 'Dan lihat, juga Zadok ada di sana beserta semua orang Lewi pengangkat tabut perjanjian Allah. Mereka meletakkan tabut Allah itu?juga Abyatar ikut datang?sampai seluruh rakyat dari kota selesai menyeberang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 25, 'Lalu berkatalah raja kepada Zadok: "Bawalah tabut Allah itu kembali ke kota; jika aku mendapat kasih karunia di mata TUHAN, maka Ia akan mengizinkan aku kembali, sehingga aku akan melihatnya lagi, juga tempat kediamannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 26, 'Tetapi jika Ia berfirman, begini: Aku tidak berkenan kepadamu, maka aku bersedia, biarlah dilakukan-Nya kepadaku apa yang baik di mata-Nya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 27, 'Lagi berkatalah raja kepada Zadok, imam itu: "Jadi, engkau dan Abyatar, pulanglah ke kota dengan selamat beserta anakmu masing-masing, yakni Ahimaas anakmu dan Yonatan, anak Abyatar.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 28, 'Ketahuilah, aku akan menanti di dekat tempat-tempat penyeberangan ke padang gurun, sampai ada kabar dari kamu untuk memberitahu aku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 29, 'Lalu Zadok dan Abyatar membawa tabut Allah itu kembali ke Yerusalem dan tinggallah mereka di sana.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 30, 'Daud mendaki bukit Zaitun sambil menangis, kepalanya berselubung dan ia berjalan dengan tidak berkasut. Juga seluruh rakyat yang bersama-sama dengan dia masing-masing berselubung kepalanya, dan mereka mendaki sambil menangis.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 31, 'Ketika kepada Daud dikabarkan, demikian: "Ahitofel ada di antara orang-orang yang bersepakat dengan Absalom," maka berkatalah Daud: "Gagalkanlah kiranya nasihat Ahitofel itu, ya TUHAN."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 32, 'Ketika Daud sampai ke puncak, ke tempat orang sujud menyembah kepada Allah, maka datanglah Husai, orang Arki, mendapatkan dia dengan jubah yang terkoyak dan dengan tanah di atas kepala.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 33, 'Berkatalah Daud kepadanya: "Jika engkau turut dengan aku, maka engkau menjadi beban kepadaku nanti,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 34, 'tetapi jika engkau kembali ke kota dan berkata kepada Absalom: Aku ini hambamu, ya raja, sejak dahulu aku hamba ayahmu, tetapi sekarang aku menjadi hambamu, ?dengan demikian engkau dapat membatalkan nasihat Ahitofel demi aku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 35, 'Bukankah Zadok dan Abyatar, imam-imam itu, ada bersama-sama engkau di sana? Jadi segala yang kaudengar dari dalam istana raja, haruslah kauberitahukan kepada Zadok dan Abyatar, imam-imam itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 36, 'Ingatlah, di sana bersama-sama dengan mereka ada kedua anak mereka, Ahimaas anak Zadok dan Yonatan anak Abyatar; dengan perantaraan mereka haruslah kamu kirimkan kepadaku segala hal yang kamu dengar."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 15, 37, 'Dan tibalah Husai, sahabat Daud, di Yerusalem tepat pada waktu Absalom masuk ke kota itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 1, 'Ketika Daud baru saja melewati puncak, datanglah Ziba, hamba Mefiboset, mendapatkan dia membawa sepasang keledai yang berpelana, dengan muatan dua ratus ketul roti, seratus buah kue kismis, seratus buah-buahan musim panas dan sebuyung anggur.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 2, 'Lalu bertanyalah raja kepada Ziba: "Apakah maksudmu dengan semuanya ini?" Jawab Ziba: "Keledai-keledai ini bagi keluarga raja untuk ditunggangi; roti dan buah-buahan ini bagi orang-orangmu untuk dimakan; dan anggur ini untuk diminum di padang gurun oleh orang-orang yang sudah lelah."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 3, 'Kemudian bertanyalah raja: "Di manakah anak tuanmu?" Jawab Ziba kepada raja: "Ia ada di Yerusalem, sebab katanya: Pada hari ini kaum Israel akan mengembalikan kepadaku kerajaan ayahku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 4, 'Lalu berkatalah raja kepada Ziba: "Kalau begitu, kepunyaanmulah segala kepunyaan Mefiboset." Kata Ziba: "Aku tunduk! Biarlah kiranya aku tetap mendapat kasih di matamu, ya tuanku raja."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 5, 'Ketika raja Daud telah sampai ke Bahurim, keluarlah dari sana seorang dari kaum keluarga Saul; ia bernama Simei bin Gera. Sambil mendekati raja, ia terus-menerus mengutuk.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 6, 'Daud dan semua pegawai raja Daud dilemparinya dengan batu, walaupun segenap tentara dan semua pahlawan berjalan di kiri kanannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 7, 'Beginilah perkataan Simei pada waktu ia mengutuk: "Enyahlah, enyahlah, engkau penumpah darah, orang dursila!', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 8, 'TUHAN telah membalas kepadamu segala darah keluarga Saul, yang engkau gantikan menjadi raja, TUHAN telah menyerahkan kedudukan raja kepada anakmu Absalom. Sesungguhnya, engkau sekarang dirundung malang, karena engkau seorang penumpah darah."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 9, 'Lalu berkatalah Abisai, anak Zeruya, kepada raja: "Mengapa anjing mati ini mengutuki tuanku raja? Izinkanlah aku menyeberang dan memenggal kepalanya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 10, 'Tetapi kata raja: "Apakah urusanku dengan kamu, hai anak-anak Zeruya? Biarlah ia mengutuk! Sebab apabila TUHAN berfirman kepadanya: Kutukilah Daud, siapakah yang akan bertanya: mengapa engkau berbuat demikian?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 11, 'Pula kata Daud kepada Abisai dan kepada semua pegawainya: "Sedangkan anak kandungku ingin mencabut nyawaku, terlebih lagi sekarang orang Benyamin ini! Biarkanlah dia dan biarlah ia mengutuk, sebab TUHAN yang telah berfirman kepadanya demikian.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 12, 'Mungkin TUHAN akan memperhatikan kesengsaraanku ini dan TUHAN membalas yang baik kepadaku sebagai ganti kutuk orang itu pada hari ini."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 13, 'Demikianlah Daud melanjutkan perjalanannya dengan orang-orangnya, sedang Simei berjalan terus di lereng gunung bertentangan dengan dia dan sambil berjalan ia mengutuk, melemparinya dengan batu dan menimbulkan debu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 14, 'Dengan lelah sampailah raja dan seluruh rakyat yang ada bersama-sama dengan dia ke Yordan, lalu mereka beristirahat di sana.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 15, 'Maka Absalom dan seluruh rakyat, orang-orang Israel, sampailah ke Yerusalem, dan Ahitofel ada bersama-sama dengan dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 16, 'Ketika Husai, orang Arki, sahabat Daud itu, sampai kepada Absalom, berkatalah Husai kepada Absalom: "Hiduplah raja! Hiduplah raja!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 17, 'Berkatalah Absalom kepada Husai: "Inikah kesetiaanmu kepada sahabatmu? Mengapa engkau tidak pergi menyertai sahabatmu itu?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 18, 'Lalu berkatalah Husai kepada Absalom: "Tidak, tetapi dia yang dipilih oleh TUHAN dan oleh rakyat ini dan oleh setiap orang Israel, dialah yang memiliki aku dan bersama-sama dengan dialah aku akan tinggal.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 19, 'Lagipula, kepada siapakah aku memperhambakan diri? Bukankah kepada anaknya? Sebagaimana aku memperhambakan diri kepada ayahmu, demikianlah aku memperhambakan diri kepadamu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 20, 'Kemudian berkatalah Absalom kepada Ahitofel: "Berilah nasihat; apakah yang harus kita perbuat?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 21, 'Lalu jawab Ahitofel kepada Absalom: "Hampirilah gundik-gundik ayahmu yang ditinggalkannya untuk menunggui istana. Apabila seluruh Israel mendengar, bahwa engkau telah membuat dirimu dibenci oleh ayahmu, maka segala orang yang menyertai engkau, akan dikuatkan hatinya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 22, 'Maka dibentangkanlah kemah bagi Absalom di atas sotoh, lalu Absalom menghampiri gundik-gundik ayahnya di depan mata seluruh Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 16, 23, 'Pada waktu itu nasihat yang diberikan Ahitofel adalah sama dengan petunjuk yang dimintakan dari pada Allah; demikianlah dinilai setiap nasihat Ahitofel, baik oleh Daud maupun oleh Absalom.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 1, 'Berkatalah Ahitofel kepada Absalom: "Izinkanlah aku memilih dua belas ribu orang, maka aku akan bersiap dan mengejar Daud pada malam ini juga.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 2, 'Aku akan mendatangi dia, selagi ia lesu dan lemah semangatnya, dan mengejutkan dia; seluruh rakyat yang ada bersama-sama dengan dia akan melarikan diri, maka aku dapat menewaskan raja sendiri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 3, 'Demikianlah aku akan membawa pulang seluruh rakyat itu kepadamu seperti seorang mempelai perempuan kembali kepada suaminya. Jadi, engkau mencari nyawa satu orang saja, sedang seluruh rakyat tetap selamat."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 4, 'Perkataan ini disetujui oleh Absalom dan oleh semua tua-tua Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 5, 'Tetapi berkatalah Absalom: "Panggillah juga Husai, orang Arki itu, supaya kita mendengar apa yang hendak dikatakannya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 6, 'Ketika Husai datang kepada Absalom, berkatalah Absalom kepadanya, demikian: "Beginilah perkataan yang dikatakan Ahitofel; apakah kita turut nasihatnya? Jika tidak, katakanlah."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 7, 'Lalu berkatalah Husai kepada Absalom: "Nasihat yang diberikan Ahitofel kali ini tidak baik."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 8, 'Kata Husai pula: "Engkau tahu, bahwa ayahmu dan orang-orangnya adalah pahlawan, dan bahwa mereka sakit hati seperti beruang yang kehilangan anak di padang. Lagipula ayahmu adalah seorang prajurit sejati; ia tidak akan membiarkan rakyat tidur.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 9, 'Tentulah ia sekarang bersembunyi dalam salah satu lobang atau di salah satu tempat. Apabila pada penyerangan pertama beberapa orang tewas dan ada orang mendengar hal itu, maka orang akan berkata: Rakyat yang telah mengikut Absalom sudah menderita kekalahan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 10, 'Maka seorang gagah perkasa sekalipun yang hatinya seperti hati singa akan tawar hati sama sekali, sebab seluruh Israel tahu, bahwa ayahmu itu seorang pahlawan dan orang-orang yang bersama-sama dia adalah orang gagah perkasa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 11, 'Sebab itu kunasihatkan: Suruhlah seluruh Israel dari Dan sampai Bersyeba berkumpul kepadamu, seperti pasir di tepi laut banyaknya dan engkau sendiri juga harus turut bertempur.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 12, 'Apabila kita mendatangi dia di salah satu tempat, di mana ia terdapat, maka kita akan menyergapnya, seperti embun jatuh ke bumi, sehingga tidak ada yang lolos, baik dia maupun orang-orang yang menyertainya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 13, 'Dan jika ia mengundurkan diri ke suatu kota, maka seluruh Israel akan mengikat kota itu dengan tali, dan kita akan menyeretnya sampai ke sungai, hingga batu kecilpun tidak terdapat lagi di sana."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 14, 'Lalu berkatalah Absalom dan setiap orang Israel: "Nasihat Husai, orang Arki itu, lebih baik dari pada nasihat Ahitofel." Sebab TUHAN telah memutuskan, bahwa nasihat Ahitofel yang baik itu digagalkan, dengan maksud supaya TUHAN mendatangkan celaka kepada Absalom.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 15, 'Sesudah itu berkatalah Husai kepada Zadok dan kepada Abyatar, imam-imam itu: "Ini dan itu dinasihatkan Ahitofel kepada Absalom dan kepada para tua-tua Israel, tetapi ini dan itu kunasihatkan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 16, 'Oleh sebab itu, suruhlah dengan segera memberitahukan kepada Daud, demikian: Pada malam ini janganlah bermalam di tempat-tempat penyeberangan ke padang gurun, tetapi menyeberanglah dengan segera, supaya jangan raja dan seluruh rakyat yang bersama-sama dengan dia itu ditelan habis."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 17, 'Yonatan dan Ahimaas menunggu di En-Rogel, dan setiap kali ada seorang budak perempuan yang datang membawa kabar kepada mereka; dan merekapun langsung memberitahu raja Daud, sebab mereka tidak boleh dilihat memasuki kota.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 18, 'Tetapi seorang anak melihat mereka, lalu memberitahu Absalom. Jadi pergilah keduanya dengan segera, dan sampailah mereka ke rumah seseorang di Bahurim yang mempunyai sumur di halamannya; maka turunlah mereka ke dalamnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 19, 'Kemudian perempuan itu mengambil kain tudungan, membentangkannya di atas mulut sumur itu dan menaburkan butir-butir gandum di atasnya, sehingga tidak kelihatan apa-apa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 20, 'Sampailah orang-orang Absalom kepada perempuan itu di rumahnya, lalu bertanya: "Di manakah Ahimaas dan Yonatan?" Jawab perempuan itu kepada mereka: "Mereka telah menyeberangi sungai itu." Kemudian mereka mencari, tetapi tidak mendapatnya, lalu pulanglah mereka ke Yerusalem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 21, 'Setelah orang-orang itu pergi, keluarlah keduanya dari sumur, lalu pergi memberitahu raja Daud, kata mereka kepada Daud: "Bersiaplah dan seberangilah dengan segera sungai ini, sebab ini dan itu dinasihatkan Ahitofel terhadap kamu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 22, 'Lalu bersiaplah Daud dan seluruh rakyat yang bersama-sama dengan dia, dan mereka menyeberangi sungai Yordan. Pada waktu fajar tidak ada seorangpun yang ketinggalan, yang tidak menyeberangi sungai Yordan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 23, 'Ketika dilihat Ahitofel, bahwa nasihatnya tidak dipedulikan, dipasangnyalah pelana keledainya, lalu berangkatlah ia ke rumahnya, ke kotanya; ia mengatur urusan rumah tangganya, kemudian menggantung diri. Demikianlah ia mati, lalu ia dikuburkan dalam kuburan ayahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 24, 'Maka sampailah Daud ke Mahanaim, ketika Absalom menyeberangi sungai Yordan dengan seluruh orang Israel yang menyertainya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 25, 'Absalom telah mengangkat Amasa menggantikan Yoab untuk mengepalai tentara. Amasa adalah anak seorang yang bernama Yitra, seorang Ismael yang telah memperisteri Abigal binti Nahas, saudara perempuan Zeruya ibu Yoab.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 26, 'Lalu orang Israel dan Absalom berkemah di tanah Gilead.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 27, 'Ketika Daud tiba di Mahanaim, maka Sobi bin Nahas, dari Raba, kota bani Amon, dan Makhir bin Amiel, dari Lodebar, dan Barzilai, orang Gilead, dari Rogelim, membawa', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 28, 'tempat tidur, pasu, periuk belanga, juga gandum, jelai, tepung, bertih gandum, kacang babi, kacang merah besar, kacang merah kecil,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 17, 29, 'madu, dadih, kambing domba dan keju lembu bagi Daud dan bagi rakyat yang bersama-sama dengan dia, untuk dimakan, sebab kata mereka: "Rakyat ini tentu telah menjadi lapar, lelah dan haus di padang gurun."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 1, 'Daud memeriksa barisan tentara yang bersama-sama dengan dia, kemudian ia mengangkat kepala pasukan seribu dan kepala pasukan seratus atas mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 2, 'Lalu Daud menyuruh tentara itu maju berperang, sepertiga di bawah perintah Yoab, sepertiga lagi di bawah perintah Abisai, anak Zeruya, adik Yoab, dan sepertiga lainnya di bawah perintah Itai, orang Gat itu. Lalu berkatalah raja kepada rakyat: "Aku juga akan maju berperang bersama-sama dengan kamu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 3, 'Tetapi tentara itu berkata: "Janganlah tuanku maju berperang; sebab apabila kami terpaksa melarikan diri, maka mereka tidak akan menghiraukan kami; bahkan sekalipun mati separuh dari pada kami, mereka tidak akan menghiraukan kami; tetapi tuanku sama harganya dengan sepuluh ribu orang dari pada kami. Sebab itu, adalah lebih baik, bahwa tuanku bersedia menolong kami dari kota."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 4, 'Kemudian berkatalah raja kepada mereka: "Apa yang kamu pandang baik akan kuperbuat." Lalu berdirilah raja di sisi pintu gerbang dan seluruh tentara itu berjalan ke luar, beratus-ratus dan beribu-ribu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 5, 'Dan raja memerintahkan kepada Yoab, Abisai dan Itai, demikian: "Perlakukanlah Absalom, orang muda itu dengan lunak karena aku." Dan seluruh tentara mendengar, ketika raja memberi perintah itu kepada semua kepala pasukan mengenai Absalom.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 6, 'Lalu tentara itu maju ke padang menyerang orang Israel, dan terjadilah pertempuran di hutan Efraim.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 7, 'Tentara Israel terpukul kalah di sana oleh orang-orang Daud, dan pada hari itu terjadilah di sana pertumpahan darah yang dahsyat: dua puluh ribu orang tewas.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 8, 'Kemudian pertempuran meluas dari sana meliputi seluruh daerah itu, dan hutan itu memakan lebih banyak orang di antara tentara dari pada yang dimakan pedang pada hari itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 9, 'Kebetulan Absalom bertemu dengan orang-orang Daud. Adapun Absalom menunggangi bagal. Ketika bagal itu lewat di bawah jalinan dahan-dahan pohon tarbantin yang besar, tersangkutlah kepalanya pada pohon tarbantin itu, sehingga ia tergantung antara langit dan bumi, sedang bagal yang dikendarainya berlari terus.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 10, 'Seseorang melihatnya, lalu memberitahu Yoab, katanya: "Aku melihat Absalom tergantung pada pohon tarbantin."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 11, 'Yoab berkata kepada orang yang memberitahu kepadanya itu: "Apa? Jika engkau melihatnya, mengapa engkau tidak membanting dia ke tanah di tempat itu juga? Maka selayaknya aku memberi engkau sepuluh syikal perak dan satu ikat pinggang."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 12, 'Tetapi orang itu berkata kepada Yoab: "Sekalipun aku mendapat seribu syikal perak di telapak tanganku, takkan aku menjamah anak raja itu, sebab di depan telinga kamilah raja memberi perintah kepadamu dan kepada Abisai dan kepada Itai, katanya: Lindungilah Absalom orang muda itu, karena aku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 13, 'Sebaliknya, jika aku mencabut nyawanya dengan khianat tidak ada sesuatupun yang tinggal tersembunyi kepada raja?maka engkau akan menjauhkan diri."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 14, 'Tetapi Yoab berkata: "Aku tidak mau membuang-buang waktu dengan kau seperti ini." Lalu diambilnyalah tiga lembing dalam tangannya dan ditikamkannya ke dada Absalom, sedang ia masih hidup di tengah-tengah dahan pohon tarbantin itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 15, 'Kemudian sepuluh bujang, pembawa senjata Yoab, mengelilingi Absalom, lalu memukul dan membunuh dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 16, 'Sesudah itu Yoab meniup sangkakala, sehingga tentara berhenti mengejar orang Israel; sebab Yoab mau menahan tentaranya itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 17, 'Lalu mereka mengambil mayat Absalom dan melemparkannya ke dalam lobang yang besar di hutan itu, kemudian mereka mendirikan di atasnya timbunan batu yang sangat besar. Dan seluruh orang Israel melarikan diri, masing-masing ke kemahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 18, 'Sewaktu hidupnya Absalom telah mendirikan bagi dirinya sendiri tugu yang sekarang ada di Lembah Raja, sebab katanya: "Aku tidak ada anak laki-laki untuk melanjutkan ingatan kepada namaku." Dan ia telah menamai tugu itu menurut namanya sendiri; sebab itu sampai hari ini tugu itu dinamai orang: tugu peringatan Absalom.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 19, 'Kemudian berkatalah Ahimaas bin Zadok: "Biarlah aku berlari menyampaikan kabar yang baik itu kepada raja, bahwa TUHAN telah memberi keadilan kepadanya dengan melepaskan dia dari tangan musuhnya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 20, 'Tetapi berkatalah Yoab kepadanya: "Pada hari ini bukan engkau yang menjadi pembawa kabar, pada hari lain boleh engkau yang menyampaikan kabar, tetapi pada hari ini engkau tidak akan menyampaikan kabar karena anak raja sudah mati."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 21, 'Lalu berkatalah Yoab kepada seorang Etiopia: "Pergilah, beritahukanlah kepada raja apa yang kaulihat." Orang Etiopia itu sujud menyembah kepada Yoab, lalu berlari pergi.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 22, 'Tetapi berkatalah sekali lagi Ahimaas bin Zadok kepada Yoab: "Apapun yang terjadi, izinkanlah juga aku berlari pergi menyusul orang Etiopia itu." Tetapi kata Yoab: "Mengapa juga engkau mau berlari pergi, anakku? Apakah engkau membawa kabar yang menguntungkanmu?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 23, 'Jawabnya: "Apapun yang terjadi, aku mau berlari pergi." Lalu berkatalah Yoab kepadanya: "Kalau demikian larilah." Maka berlarilah Ahimaas mengambil jalan dari Lembah Yordan, sehingga ia mendahului orang Etiopia itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 24, 'Adapun Daud duduk di antara kedua pintu gerbang sedang penjaga naik ke sotoh pintu gerbang itu, di atas tembok. Ketika ia melayangkan pandangnya, dilihatnyalah orang datang berlari, seorang diri saja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 25, 'Berserulah penjaga memberitahu raja, lalu raja berkata: "Jika ia seorang diri, maka kabar yang baiklah disampaikannya." Sementara orang itu mendekat,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 26, 'penjaga itu melihat seorang lain datang berlari, lalu penjaga itu menyerukan kepada penunggu pintu gerbang, katanya: "Lihat, ada lagi orang datang berlari, seorang diri." Berkatalah raja: "Itupun pembawa kabar yang baik."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 27, 'Sesudah itu berkatalah penjaga: "Aku lihat cara berlari orang yang pertama itu seperti cara berlari Ahimaas bin Zadok." Berkatalah raja: "Itu orang baik, ia datang membawa kabar yang baik."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 28, 'Lalu Ahimaas berseru, katanya kepada raja: "Selamat!" Kemudian sujudlah ia menyembah kepada raja dengan mukanya ke tanah serta berkata: "Terpujilah TUHAN, Allahmu, yang telah menyerahkan orang-orang yang menggerakkan tangannya melawan tuanku raja."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 29, 'Lalu bertanyalah raja: "Selamatkah Absalom, orang muda itu?" Jawab Ahimaas: "Aku melihat keributan yang besar, ketika Yoab menyuruh pergi hamba raja, hambamu ini, tetapi aku tidak tahu apa itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 30, 'Kemudian berkatalah raja: "Pergilah ke samping, berdirilah di sini." Ia pergi ke samping dan tinggal berdiri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 31, 'Maka datanglah orang Etiopia itu. Kata orang Etiopia itu: "Tuanku raja mendapat kabar yang baik, sebab TUHAN telah memberi keadilan kepadamu pada hari ini dengan melepaskan tuanku dari tangan semua orang yang bangkit menentang tuanku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 32, 'Tetapi bertanyalah raja kepada orang Etiopia itu: "Selamatkah Absalom, orang muda itu?" Jawab orang Etiopia itu: "Biarlah seperti orang muda itu musuh tuanku raja dan semua orang yang bangkit menentang tuanku untuk berbuat jahat."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 18, 33, 'Maka terkejutlah raja dan dengan sedih ia naik ke anjung pintu gerbang lalu menangis. Dan beginilah perkataannya sambil berjalan: "Anakku Absalom, anakku, anakku Absalom! Ah, kalau aku mati menggantikan engkau, Absalom, anakku, anakku!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 1, 'Lalu diberitahukanlah kepada Yoab: "Ketahuilah, raja menangis dan berkabung karena Absalom."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 2, 'Pada hari itulah kemenangan menjadi perkabungan bagi seluruh tentara, sebab pada hari itu tentara itu mendengar orang berkata: "Raja bersusah hati karena anaknya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 3, 'Sebab itu tentara itu masuk kota dengan diam-diam pada hari itu, seperti tentara yang kena malu kembali dengan diam-diam karena melarikan diri dari pertempuran.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 4, 'Raja menyelubungi mukanya, dan dengan suara nyaring merataplah raja: "Anakku Absalom, Absalom, anakku, anakku!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 5, 'Lalu masuklah Yoab menghadap raja di kediamannya serta berkata: "Pada hari ini engkau mempermalukan semua hambamu, yang telah menyelamatkan nyawamu pada hari ini dan nyawa anak-anakmu laki-laki dan perempuan dan nyawa isteri-isterimu dan nyawa gundik-gundikmu,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 6, 'dengan mencintai orang-orang yang benci kepadamu, dan dengan membenci orang-orang yang cinta kepadamu! Karena pada hari ini engkau menunjukkan bahwa panglima-panglima dan anak buah tidak berarti apa-apa bagimu. Bahkan aku mengerti pada hari ini, bahwa seandainya Absalom masih hidup dan kami semua mati pada hari ini, maka hal itu kaupandang baik.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 7, 'Oleh sebab itu, bangunlah, pergilah ke luar dan berbicaralah menenangkan hati orang-orangmu. Sebab aku bersumpah demi TUHAN, apabila engkau tidak keluar, maka seorangpun tidak akan ada yang tinggal bersama-sama dengan engkau pada malam ini; dan hal ini berarti celaka bagimu melebihi segala celaka yang telah kaualami sejak kecilmu sampai sekarang."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 8, 'Lalu bangunlah raja dan duduk di pintu gerbang. Maka diberitahukanlah kepada seluruh rakyat, demikian: "Ketahuilah, raja duduk di pintu gerbang." Kemudian datanglah seluruh rakyat itu menghadap raja. Adapun orang Israel sudah melarikan diri, masing-masing ke kemahnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 9, 'Seluruh rakyat dari semua suku Israel berbantah-bantah, katanya: "Raja telah melepaskan kita dari tangan musuh kita, dialah yang telah menyelamatkan kita dari tangan orang Filistin. Dan sekarang ia sudah melarikan diri dari dalam negeri karena Absalom;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 10, 'tetapi Absalom yang telah kita urapi untuk memerintah kita, sudah mati dalam pertempuran. Maka sekarang, mengapa kamu berdiam diri dengan tidak membawa raja kembali?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 11, 'Raja Daud telah menyuruh orang kepada Zadok dan Abyatar, imam-imam itu, dengan pesan: "Berbicaralah kepada para tua-tua Yehuda, demikian: Mengapa kamu menjadi yang terakhir untuk membawa raja kembali ke istananya?" Sebab perkataan seluruh Israel telah sampai kepada raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 12, '"Kamulah saudara-saudaraku, kamulah darah dagingku; mengapa kamu menjadi yang terakhir untuk membawa raja kembali?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 13, 'Dan kepada Amasa haruslah kamu katakan: Bukankah engkau darah dagingku? Beginilah kiranya Allah menghukum aku, bahkan lebih lagi dari pada itu, jika engkau tidak tetap menjadi panglimaku menggantikan Yoab."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 14, 'Demikianlah dibelokkannya hati semua orang Yehuda secara serentak, sehingga mereka menyuruh menyampaikan kepada raja pesan ini: "Kembalilah, tuanku dan semua anak buahmu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 15, 'Lalu berangkatlah raja pulang dan sampailah ia ke tepi sungai Yordan. Sementara itu orang Yehuda telah sampai ke Gilgal untuk menyongsong raja dan untuk membawa raja menyeberang sungai Yordan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 16, 'Juga Simei bin Gera, orang Benyamin yang dari Bahurim itu, cepat-cepat datang bersama-sama dengan orang-orang Yehuda untuk menyongsong raja Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 17, 'Juga ada seribu orang dari daerah Benyamin bersama-sama dengan dia. Dan Ziba, hamba keluarga Saul, dan kelima belas anaknya laki-laki dan kedua puluh hambanya bersama-sama dengan dia datang tergesa-gesa ke sungai Yordan mendahului raja,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 18, 'lalu menyeberang dari tempat penyeberangan untuk menyeberangkan keluarga raja dan untuk melakukan apa yang dipandangnya baik. Maka Simei bin Gera sujud di depan raja, ketika raja hendak menyeberangi sungai Yordan,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 19, 'dan berkata kepada raja: "Janganlah kiranya tuanku tetap memandang aku bersalah, dan janganlah kiranya tuanku mengingat kesalahan yang dilakukan hambamu ini pada hari tuanku raja keluar dari Yerusalem; janganlah kiranya raja memperhatikannya lagi.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 20, 'Sebab hambamu ini tahu bahwa hamba telah berbuat dosa; dan lihatlah, pada hari ini akulah yang pertama-tama datang dari seluruh keturunan Yusuf untuk menyongsong tuanku raja."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 21, 'Lalu berbicaralah Abisai, anak Zeruya, katanya: "Bukankah Simei patut dihukum mati karena ia telah mengutuki orang yang diurapi TUHAN?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 22, 'Tetapi Daud berkata: "Apakah urusanku dengan kamu, hai anak-anak Zeruya, sehingga kamu pada hari ini menjadi lawanku? Masakan pada hari ini seorang dihukum mati di Israel! Sebab bukankah aku tahu, bahwa aku pada hari ini adalah raja atas Israel?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 23, 'Kemudian berkatalah raja kepada Simei: "Engkau tidak akan mati." Lalu raja bersumpah kepadanya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 24, 'Juga Mefiboset bin Saul menyongsong raja. Ia tidak membersihkan kakinya dan tidak memelihara janggutnya dan pakaiannya tidak dicucinya sejak raja pergi sampai hari ia pulang dengan selamat.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 25, 'Ketika ia dari Yerusalem menyongsong raja, bertanyalah raja kepadanya: "Mengapa engkau tidak pergi bersama-sama dengan aku, Mefiboset?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 26, 'Jawabnya: "Ya tuanku raja, aku ditipu hambaku. Sebab hambamu ini berkata kepadanya: Pelanailah keledai bagiku, supaya aku menungganginya dan pergi bersama-sama dengan raja! ?sebab hambamu ini timpang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 27, 'Ia telah memfitnahkan hambamu ini kepada tuanku raja. Tetapi tuanku raja adalah seperti malaikat Allah; sebab itu perbuatlah apa yang tuanku pandang baik.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 28, 'Walaupun seluruh kaum keluargaku tidak lain dari orang-orang yang patut dihukum mati oleh tuanku raja, tuanku telah mengangkat hambamu ini di antara orang-orang yang menerima rezeki dari istanamu. Apakah hakku lagi dan untuk apa aku mengadakan tuntutan lagi kepada raja?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 29, 'Tetapi raja berkata kepadanya: "Apa gunanya engkau berkata-kata lagi tentang halmu? Aku telah memutuskan: Engkau dan Ziba harus berbagi ladang itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 30, 'Lalu berkatalah Mefiboset kepada raja: "Biarlah ia mengambil semuanya, sebab tuanku raja sudah pulang dengan selamat."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 31, 'Juga Barzilai, orang Gilead itu, telah datang dari Ragelim dan ikut bersama-sama raja ke sungai Yordan untuk mengantarkannya sampai di sana.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 32, 'Barzilai itu sudah sangat tua, delapan puluh tahun umurnya. Ia menyediakan makanan bagi raja selama ia tinggal di Mahanaim, sebab ia seorang yang sangat kaya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 33, 'Berkatalah raja kepada Barzilai: "Ikutlah aku, aku akan memelihara engkau di tempatku di Yerusalem."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 34, 'Tetapi Barzilai menjawab raja: "Berapa tahun lagikah aku hidup, sehingga aku harus pergi bersama-sama dengan raja ke Yerusalem?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 35, 'Sekarang ini aku telah berumur delapan puluh tahun; masakan aku masih dapat membedakan antara yang baik dan yang tidak baik? Atau masih dapatkah hambamu ini merasai apa yang hamba makan atau apa yang hamba minum? Atau masih dapatkah aku mendengarkan suara penyanyi laki-laki dan penyanyi perempuan? Apa gunanya hambamu ini lagi menjadi beban bagi tuanku raja?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 36, 'Sepotong jalan saja hambamu ini berjalan ke seberang sungai Yordan bersama-sama dengan raja. Mengapa raja memberikan ganjaran yang sedemikian kepadaku?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 37, 'Biarkanlah hambamu ini pulang, sehingga aku dapat mati di kotaku sendiri, dekat kubur ayahku dan ibuku. Tetapi inilah hambamu Kimham, ia boleh ikut dengan tuanku raja; perbuatlah kepadanya apa yang tuanku pandang baik."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 38, 'Lalu berbicaralah raja: "Baiklah Kimham ikut dengan aku; aku akan berbuat kepadanya apa yang kaupandang baik, dan segala yang kaukehendaki dari padaku akan kulakukan untukmu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 39, 'Kemudian seluruh rakyat menyeberangi sungai Yordan. Juga raja menyeberang, setelah berpamitan dengan Barzilai dengan ciuman. Lalu orang inipun pulanglah ke tempat kediamannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 40, 'Sesudah itu berjalanlah raja terus ke Gilgal, dan Kimham ikut dengan dia. Seluruh rakyat Yehuda bersama-sama setengah dari rakyat Israel telah mengantarkan raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 41, 'Tetapi seluruh orang Israel datang menghadap raja dan berkata kepada raja: "Mengapa saudara-saudara kami, orang-orang Yehuda itu, menculik raja dan membawa dia menyeberangi sungai Yordan dengan keluarganya dan semua orang Daud yang menyertai dia?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 42, 'Lalu semua orang Yehuda menjawab orang-orang Israel itu: "Oleh karena raja kerabat kami. Mengapa kamu menjadi marah karena hal ini? Apakah kami makan apa-apa atas biaya raja? Apakah kami mendapat keuntungan?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 19, 43, 'Tetapi orang-orang Israel itu menjawab orang-orang Yehuda: "Kami sepuluh kali lebih berhak atas raja. Sebagai anak sulung kami melebihi kamu. Mengapa kamu memandang kami rendah? Bukankah kami yang pertama-tama harus membawa raja kami kembali?" Tetapi perkataan orang-orang Yehuda itu lebih pedas dari pada perkataan orang-orang Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 1, 'Kebetulan ada di sana seorang dursila, bernama Seba bin Bikri, orang Benyamin. Ia meniup sangkakala serta berkata: "Kita tidak memperoleh bagian dari pada Daud. Kita tidak memperoleh warisan dari anak Isai itu. Masing-masing ke kemahnya, hai orang Israel!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 2, 'Lalu semua orang Israel itu meninggalkan Daud dan mengikuti Seba bin Bikri, sedangkan orang-orang Yehuda tetap berpaut kepada raja mereka, mengikutinya dari sungai Yordan sampai Yerusalem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 3, 'Sampailah Daud ke istananya di Yerusalem, lalu raja mengambil kesepuluh gundik yang ditinggalkannya untuk menunggui istana, kemudian dimasukkannya mereka dalam sebuah rumah di bawah penjagaan. Ia memelihara mereka, tetapi tidak dihampirinya. Mereka tetap terasing seperti janda sampai hari mati mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 4, 'Berkatalah raja kepada Amasa: "Kerahkanlah bagiku orang-orang Yehuda dalam tiga hari, kemudian menghadaplah lagi ke mari!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 5, 'Lalu pergilah Amasa mengerahkan orang Yehuda, tetapi ia menunda-nunda tugas itu sampai melewati waktu yang ditetapkan raja baginya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 6, 'Lalu berkatalah Daud kepada Abisai: "Sekarang Seba bin Bikri lebih berbahaya bagi kita dari pada Absalom; jadi engkau, bawalah orang-orang tuanmu ini dan kejarlah dia, supaya jangan ia mencapai kota yang berkubu, dan dengan demikian ia luput dari pada kita."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 7, 'Lalu Yoab, orang Kreti dan orang Pleti dan semua pahlawan keluar menyusul dia. Mereka keluar dari Yerusalem untuk mengejar Seba bin Bikri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 8, 'Ketika mereka sampai ke batu besar yang di Gibeon, maka Amasa sudah tiba di sana lebih dahulu dari pada mereka. Adapun Yoab mengenakan pakaian perang dan di luarnya ada ikat pinggang dengan pedang bersarung terpaut pada pinggangnya. Ketika ia tampil ke muka terjatuhlah pedang itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 9, 'Berkatalah Yoab kepada Amasa: "Engkau baik-baik, saudaraku?" Sementara itu tangan kanan Yoab memegang janggut Amasa untuk mencium dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 10, 'Amasa tidak awas terhadap pedang yang ada di tangan Yoab itu; Yoab menikam pedang itu ke perutnya, sehingga isi perutnya tertumpah ke tanah. Tidak usah dia ditikamnya dua kali, sebab ia sudah mati. Lalu Yoab dan Abisai, adiknya, terus mengejar Seba bin Bikri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 11, 'Dan seorang dari orang-orang Yoab tinggal berdiri di dekat mayat itu, sambil berkata: "Siapa yang suka kepada Yoab dan siapa yang memihak kepada Daud, baiklah mengikuti Yoab!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 12, 'Dalam pada itu Amasa terguling mati dalam darahnya di tengah-tengah jalan raya. Ketika orang itu melihat, bahwa seluruh rakyat berdiri menonton, maka disingkirkannya mayat Amasa dari jalan raya ke padang, lalu dihamparkannya kain di atasnya, karena dilihatnya, bahwa setiap orang yang datang ke sana berdiri menonton.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 13, 'Setelah dijauhkannya mayat itu dari jalan raya, maka semua orang itu berjalan terus mengikuti Yoab untuk mengejar Seba bin Bikri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 14, 'Seba telah melintasi daerah semua suku Israel menuju Abel-Bet-Maakha. Dan semua orang Bikri telah berkumpul dan mengikuti dia.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 15, 'Tetapi sampailah orang-orang Yoab, lalu mengepung dia di Abel-Bet-Maakha; mereka menimbun tanah menjadi tembok terhadap kota ini dan tembok ini merapat sampai ke tembok luar sedang seluruh rakyat yang bersama-sama dengan Yoab menggali tembok kota itu untuk meruntuhkannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 16, 'Lalu berserulah seorang perempuan bijaksana dari kota itu: "Dengar! Dengar! Katakanlah kepada Yoab: Mendekatlah ke mari, supaya aku berbicara dengan engkau."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 17, 'Maka mendekatlah Yoab kepada perempuan itu. Bertanyalah perempuan itu: "Engkaukah Yoab?" Jawabnya: "Benar!" Lalu berkatalah perempuan itu kepadanya: "Dengarkanlah perkataan hambamu ini!" Jawabnya: "Baik!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 18, 'Kemudian berkatalah perempuan itu: "Dahulu biasa orang berkata begini: Baiklah orang minta petunjuk di Abel dan di Dan, apakah sudah dihapuskan', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 19, 'apa yang telah ditetapkan oleh orang-orang yang setia di Israel! Tetapi engkau ini berikhtiar membinasakan suatu kota, apalagi suatu kota induk di Israel. Mengapa engkau hendak menelan habis milik pusaka TUHAN?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 20, 'Lalu Yoab menjawab: "Jauhlah, jauhlah dari padaku untuk menelan dan memusnahkan!', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 21, 'Bukanlah begitu halnya. Tetapi seorang dari pegunungan Efraim, yang bernama Seba bin Bikri, telah menggerakkan tangannya melawan raja Daud; serahkanlah dia seorang diri, maka aku akan undur dari kota ini." Lalu berkatalah perempuan itu kepada Yoab: "Baik, kepalanya akan dilemparkan kepadamu dari belakang tembok ini."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 22, 'Kemudian masuklah pula perempuan itu dan berbicara kepada seluruh rakyat dengan bijaksana; sesudah itu mereka memenggal kepala Seba bin Bikri dan melemparkannya kepada Yoab. Yoab meniup sangkakala, lalu berserak-seraklah mereka meninggalkan kota itu, masing-masing ke tempatnya. Maka pulanglah Yoab ke Yerusalem kepada raja.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 23, 'Yoab menjadi kepala atas segenap tentara Israel, dan Benaya bin Yoyada menjadi kepala atas orang Kreti dan orang Pleti.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 24, 'Adoram menjadi kepala orang rodi dan Yosafat bin Ahilud menjadi bendahara negara.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 25, 'Seya menjadi panitera negara; Zadok dan Abyatar menjadi imam.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 20, 26, 'Juga Ira, orang Yair itu menjadi imam pada Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 1, 'Dalam zaman Daud terjadilah kelaparan selama tiga tahun berturut-turut, lalu Daud pergi menanyakan petunjuk TUHAN. Berfirmanlah TUHAN: "Pada Saul dan keluarganya melekat hutang darah, karena ia telah membunuh orang-orang Gibeon."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 2, 'Lalu raja memanggil orang-orang Gibeon dan berkata kepada mereka, ?orang-orang Gibeon itu tidak termasuk orang Israel, tetapi termasuk sisa-sisa orang Amori dan walaupun orang Israel telah bersumpah kepada mereka, Saul berikhtiar membasmi mereka dalam kegiatannya untuk kepentingan orang Israel dan Yehuda, ?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 3, 'Daud berkata kepada orang-orang Gibeon itu: "Apakah yang dapat kuperbuat bagimu dan dengan apakah dapat kuadakan penebusan, supaya kamu memberkati milik pusaka TUHAN?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 4, 'Lalu berkatalah orang-orang Gibeon itu kepadanya: "Bukanlah perkara emas dan perak urusan kami dengan Saul serta keluarganya, juga bukanlah urusan kami untuk membunuh seseorang di antara orang Israel." Tetapi kata Daud: "Apakah yang kamu kehendaki akan kuperbuat bagimu?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 5, 'Sesudah itu berkatalah mereka kepada raja: "Dari orang yang hendak membinasakan kami dan yang bermaksud memunahkan kami, sehingga kami tidak mendapat tempat di manapun di daerah Israel,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 6, 'biarlah diserahkan tujuh orang anaknya laki-laki kepada kami, supaya kami menggantung mereka di hadapan TUHAN di Gibeon, di bukit TUHAN." Lalu berkatalah raja: "Aku akan menyerahkan mereka."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 7, 'Tetapi raja merasa sayang kepada Mefiboset bin Yonatan bin Saul, karena sumpah demi TUHAN ada di antara mereka, di antara Daud dan Yonatan bin Saul.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 8, 'Lalu raja mengambil kedua anak laki-laki Rizpa binti Aya, yang dilahirkannya bagi Saul, yakni Armoni dan Mefiboset, dan kelima anak laki-laki Merab binti Saul, yang dilahirkannya bagi Adriel bin Barzilai, orang Mehola itu,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 9, 'kemudian diserahkannyalah mereka ke dalam tangan orang-orang Gibeon itu. Orang-orang ini menggantung mereka di atas bukit, di hadapan TUHAN. Ketujuh orang itu tewas bersama-sama. Mereka telah dihukum mati pada awal musim menuai, pada permulaan musim menuai jelai.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 10, 'Lalu Rizpa binti Aya mengambil kain karung, dan membentangkannya bagi dirinya di atas gunung batu, dari permulaan musim menuai sampai tercurah air dari langit ke atas mayat mereka; ia tidak membiarkan burung-burung di udara mendatangi mayat mereka pada siang hari, ataupun binatang-binatang di hutan pada malam hari.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 11, 'Ketika diberitahukan kepada Daud apa yang diperbuat Rizpa binti Aya, gundik Saul itu,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 12, 'maka pergilah Daud mengambil tulang-tulang Saul dan tulang-tulang Yonatan, anaknya, dari warga-warga kota Yabesh-Gilead, yang telah mencuri tulang-tulang itu dari tanah lapang di Bet-San, tempat orang Filistin menggantung mereka, ketika orang Filistin memukul Saul kalah di Gilboa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 13, 'Ia membawa dari sana tulang-tulang Saul dan tulang-tulang Yonatan, anaknya. Dikumpulkanlah juga tulang-tulang orang-orang yang digantung tadi,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 14, 'lalu dikuburkan bersama-sama tulang-tulang Saul dan Yonatan, anaknya, di tanah Benyamin, di Zela, di dalam kubur Kish, ayahnya. Orang melakukan segala sesuatu yang diperintahkan raja, maka sesudah itu Allah mengabulkan doa untuk negeri itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 15, 'Ketika terjadi lagi peperangan antara orang Filistin dan orang Israel, maka berangkatlah Daud bersama-sama dengan orang-orangnya, lalu berperang melawan orang Filistin, sampai Daud menjadi letih lesu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 16, 'Yisbi-Benob, yang termasuk keturunan raksasa?berat tombaknya tiga ratus syikal tembaga dan ia menyandang pedang yang baru?menyangka dapat menewaskan Daud.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 17, 'Tetapi Abisai, anak Zeruya, datang menolong Daud, lalu merobohkan dan membunuh orang Filistin itu. Pada waktu itu orang-orang Daud memohon dengan sangat kepadanya, kata mereka: "Janganlah lagi engkau maju berperang bersama-sama dengan kami, supaya keturunan Israel jangan punah bersama-sama engkau."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 18, 'Sesudah itu terjadi lagi pertempuran melawan orang Filistin di Gob; pada waktu itu Sibkhai, orang Husa, memukul kalah Saf, yang termasuk keturunan raksasa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 19, 'Dan terjadi lagi pertempuran melawan orang Filistin, di Gob; Elhanan bin Yaare-Oregim, orang Betlehem itu, menewaskan Goliat, orang Gat itu, yang gagang tombaknya seperti pesa tukang tenun.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 20, 'Lalu terjadi lagi pertempuran di Gat; dan di sana ada seorang yang tinggi perawakannya, yang tangannya dan kakinya masing-masing berjari enam: dua puluh empat seluruhnya; juga orang ini termasuk keturunan raksasa.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 21, 'Ia mengolok-olok orang Israel, maka Yonatan, anak Simea kakak Daud, menewaskannya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 21, 22, 'Keempat orang ini termasuk keturunan raksasa di Gat; mereka tewas oleh tangan Daud dan oleh tangan orang-orangnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 1, 'Daud mengatakan perkataan nyanyian ini kepada TUHAN pada waktu TUHAN telah melepaskan dia dari cengkeraman semua musuhnya dan dari cengkeraman Saul.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 2, 'Ia berkata: "Ya, TUHAN, bukit batuku, kubu pertahananku dan penyelamatku,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 3, 'Allahku, gunung batuku, tempat aku berlindung, perisaiku, tanduk keselamatanku, kota bentengku, tempat pelarianku, juruselamatku; Engkau menyelamatkan aku dari kekerasan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 4, 'Terpujilah TUHAN, seruku; maka akupun selamat dari pada musuhku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 5, 'Sesungguhnya gelora-gelora maut telah mengelilingi aku, banjir-banjir jahanam telah menimpa aku,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 6, 'tali-tali dunia orang mati telah membelit aku, perangkap-perangkap maut terpasang di depanku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 7, 'Ketika aku dalam kesesakan, aku berseru kepada TUHAN, kepada Allahku aku berseru. Dan Ia mendengar suaraku dari bait-Nya, teriakku minta tolong masuk ke telinga-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 8, 'Lalu bergoyang dan bergoncanglah bumi, dasar-dasar langit gemetar dan bergoyang, oleh karena bernyala-nyala murka-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 9, 'Asap membubung dari hidung-Nya, api menjilat keluar dari mulut-Nya, bara menyala keluar dari pada-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 10, 'Ia menekukkan langit, lalu turun, kekelaman ada di bawah kaki-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 11, 'Ia mengendarai kerub, lalu terbang, dan tampak di atas sayap angin.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 12, 'Dan Ia membuat kegelapan di sekeliling-Nya menjadi pondok-Nya: air hujan yang gelap, awan yang tebal.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 13, 'Karena sinar kilat di hadapan-Nya bara api menjadi menyala.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 14, 'TUHAN mengguntur dari langit, Yang Mahatinggi memperdengarkan suara-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 15, 'Dilepaskan-Nya panah-panah, sehingga diserakkan-Nya mereka, yakni kilat-kilat, sehingga dikacaukan-Nya mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 16, 'Lalu kelihatanlah dasar-dasar laut, alas-alas dunia tersingkap karena hardikan TUHAN karena hembusan nafas dari hidung-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 17, 'Ia menjangkau dari tempat tinggi, mengambil aku, menarik aku dari banjir.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 18, 'Ia melepaskan aku dari musuhku yang gagah, dari pada orang-orang yang membenci aku, karena mereka terlalu kuat bagiku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 19, 'Mereka menghadang aku pada hari sialku, tetapi TUHAN adalah sandaran bagiku;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 20, 'Ia membawa aku keluar ke tempat lapang, Ia menyelamatkan aku, karena Ia berkenan kepadaku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 21, 'TUHAN memperlakukan aku sesuai dengan kebenaranku; Ia membalas kepadaku sesuai dengan kesucian tanganku,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 22, 'sebab aku tetap mengikuti jalan TUHAN dan tidak menjauhkan diri dari Allahku sebagai orang fasik.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 23, 'Sebab segala hukum-Nya kuperhatikan, dan dari ketetapan-Nya aku tidak menyimpang;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 24, 'aku berlaku tidak bercela kepada-Nya dan menjaga diri terhadap kesalahan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 25, 'Karena itu TUHAN membalas kepadaku sesuai dengan kebenaranku, sesuai dengan kesucianku di depan mata-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 26, 'Terhadap orang yang setia Engkau berlaku setia, terhadap orang yang tidak bercela Engkau berlaku tidak bercela,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 27, 'terhadap orang yang suci Engkau berlaku suci, tetapi terhadap orang yang bengkok Engkau berlaku belat-belit.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 28, 'Bangsa yang tertindas Engkau selamatkan, tetapi mata-Mu melawan orang-orang yang tinggi hati, supaya mereka Kaurendahkan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 29, 'Karena Engkaulah pelitaku, ya TUHAN, dan TUHAN menyinari kegelapanku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 30, 'Karena dengan Engkau aku berani menghadapi gerombolan, dengan Allahku aku berani melompati tembok.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 31, 'Adapun Allah, jalan-Nya sempurna; sabda TUHAN itu murni; Dia menjadi perisai bagi semua orang yang berlindung pada-Nya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 32, 'Sebab siapakah Allah selain dari TUHAN, dan siapakah gunung batu selain dari Allah kita?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 33, 'Allah, Dialah yang menjadi tempat pengungsianku yang kuat dan membuat jalanku rata;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 34, 'yang membuat kakiku seperti kaki rusa dan membuat aku berdiri di bukit;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 35, 'yang mengajar tanganku berperang, sehingga lenganku dapat melengkungkan busur tembaga.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 36, 'Juga Kauberikan kepadaku perisai keselamatan-Mu, dan kebaikan-Mu telah membuat aku besar.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 37, 'Kauberikan tempat lapang untuk langkahku, dan mata kakiku tidak goyah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 38, 'Aku mengejar musuhku sampai mereka kupunahkan, dan tidak berbalik sebelum mereka kuhabiskan;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 39, 'aku menghabiskan dan meremukkan mereka, sehingga mereka tidak bangkit lagi, dan mereka rebah di bawah kakiku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 40, 'Engkau telah mengikat pinggangku dengan keperkasaan untuk berperang, Engkau tundukkan ke bawah kuasaku orang yang bangkit melawan aku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 41, 'Kaubuat musuhku lari dari padaku, orang-orang yang membenci aku, mereka kubinasakan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 42, 'Mereka berteriak minta tolong, tetapi tidak ada yang menyelamatkan, mereka berteriak kepada TUHAN, tetapi Ia tidak menjawab mereka.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 43, 'Aku menggiling mereka halus-halus seperti debu tanah, aku menumbuk mereka dan menginjak-injak mereka seperti lumpur di jalan.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 44, 'Dan Engkau meluputkan aku dari perbantahan bangsaku; Engkau memelihara aku sebagai kepala atas bangsa-bangsa; bangsa yang tidak kukenal menjadi hambaku;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 45, 'orang-orang asing tunduk menjilat kepadaku, baru saja telinga mereka mendengar, mereka taat kepadaku.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 46, 'Orang-orang asing pucat layu dan keluar dari kota kubunya dengan gemetar.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 47, 'TUHAN hidup! Terpujilah gunung batuku, dan ditinggikanlah kiranya Allah gunung batu keselamatanku,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 48, 'Allah, yang telah mengadakan pembalasan bagiku, yang telah membawa bangsa-bangsa ke bawah kuasaku,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 49, 'dan yang telah membebaskan aku dari pada musuhku. Dan Engkau telah meninggikan aku mengatasi mereka yang bangkit melawan aku; Engkau telah melepaskan aku dari para penindas.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 50, 'Sebab itu aku mau menyanyikan syukur bagi-Mu, ya TUHAN, di antara bangsa-bangsa, dan aku mau menyanyikan mazmur bagi nama-Mu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 22, 51, 'Ia mengaruniakan keselamatan yang besar kepada raja yang diangkat-Nya, dan menunjukkan kasih setia kepada orang yang diurapi-Nya, kepada Daud dan anak cucunya untuk selamanya."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 1, 'Inilah perkataan Daud yang terakhir: "Tutur kata Daud bin Isai dan tutur kata orang yang diangkat tinggi, orang yang diurapi Allah Yakub, pemazmur yang disenangi di Israel:', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 2, 'Roh TUHAN berbicara dengan perantaraanku, firman-Nya ada di lidahku;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 3, 'Allah Israel berfirman, gunung batu Israel berkata kepadaku: Apabila seorang memerintah manusia dengan adil, memerintah dengan takut akan Allah,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 4, 'ia bersinar seperti fajar di waktu pagi, pagi yang tidak berawan, yang sesudah hujan membuat berkilauan rumput muda di tanah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 5, 'Bukankah seperti itu keluargaku di hadapan Allah? Sebab Ia menegakkan bagiku suatu perjanjian kekal, teratur dalam segala-galanya dan terjamin. Sebab segala keselamatanku dan segala kesukaanku bukankah Dia yang menumbuhkannya?', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 6, 'Tetapi orang-orang yang dursila mereka semuanya seperti duri yang dihamburkan; sesungguhnya, mereka tidak terpegang oleh tangan:', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 7, 'tidak ada orang yang dapat mengusik mereka, kecuali dengan sebatang besi atau gagang tombak, dan dengan api mereka dibakar habis!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 8, 'Inilah nama para pahlawan yang mengiringi Daud: Isybaal, orang Hakhmoni, kepala triwira; ia mengayunkan tombaknya melawan delapan ratus orang yang tertikam mati dalam satu pertempuran.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 9, 'Dan sesudah dia, Eleazar anak Dodo, anak seorang Ahohi; ia termasuk ketiga pahlawan itu. Ia ada bersama-sama Daud, ketika mereka mengolok-olok orang Filistin, yang telah berkumpul di sana untuk berperang, padahal orang-orang Israel telah mengundurkan diri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 10, 'Tetapi ia bangkit dan membunuh demikian banyak orang Filistin sampai tangannya lesu dan tinggal melekat pada pedangnya. TUHAN memberikan pada hari itu kemenangan yang besar. Rakyat datang kembali mengikuti dia, hanya untuk merampas.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 11, 'Sesudah dia, Sama, anak Age, orang Harari. Ketika orang Filistin berkumpul di Lehi?di sana ada sebidang tanah ladang penuh kacang merah?dan tentara telah melarikan diri dari hadapan orang Filistin,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 12, 'maka berdirilah ia di tengah-tengah ladang itu, ia dapat mempertahankannya dan memukul kalah orang Filistin. Demikianlah diberikan TUHAN kemenangan yang besar.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 13, 'Sekali datanglah tiga orang dari ketiga puluh kepala mendapatkan Daud, menjelang musim menuai, dekat gua Adulam, sedang sepasukan orang Filistin berkemah di lembah Refaim.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 14, 'Pada waktu itu Daud ada di dalam kubu gunung dan pasukan pendudukan orang Filistin pada waktu itu ada di Betlehem.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 15, 'Lalu timbullah keinginan pada Daud, dan ia berkata: "Sekiranya ada orang yang memberi aku minum air dari perigi Betlehem yang ada dekat pintu gerbang!"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 16, 'Lalu ketiga pahlawan itu menerobos perkemahan orang Filistin, mereka menimba air dari perigi Betlehem yang ada dekat pintu gerbang, mengangkatnya dan membawanya kepada Daud. Tetapi Daud tidak mau meminumnya, melainkan mempersembahkannya sebagai korban curahan kepada TUHAN,', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 17, 'katanya: "Jauhlah dari padaku, ya TUHAN, untuk berbuat demikian! Bukankah ini darah orang-orang yang telah pergi dengan mempertaruhkan nyawanya?" Dan tidak mau ia meminumnya. Itulah yang dilakukan ketiga pahlawan itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 18, 'Abisai, adik Yoab, anak Zeruya, dialah kepala ketiga puluh orang itu. Dan dialah yang mengayunkan tombaknya melawan tiga ratus orang yang mati ditikamnya; ia mendapat nama di antara ketiga puluh orang itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 19, 'Bukankah ia yang paling dihormati di antara ketiga puluh orang itu? Memang ia menjadi pemimpin mereka, tetapi ia tidak dapat menyamai triwira itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 20, 'Selanjutnya Benaya bin Yoyada, anak seorang yang gagah perkasa, yang besar jasanya, yang berasal dari Kabzeel; ia menewaskan kedua pahlawan besar dari Moab. Juga pernah ia turun ke dalam lobang dan membunuh seekor singa pada suatu hari bersalju.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 21, 'Pula ia membunuh seorang Mesir, seorang yang tinggi perawakannya; di tangan orang Mesir itu ada tombak, tetapi ia mendatanginya dengan tongkat, merampas tombak itu dari tangan orang Mesir itu, lalu membunuh orang itu dengan tombaknya sendiri.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 22, 'Itulah yang diperbuat Benaya bin Yoyada; ia mendapat nama di antara ketiga puluh pahlawan itu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 23, 'Di antara ketiga puluh orang itu ia paling dihormati, tetapi ia tidak dapat menyamai triwira. Dan Daud mengangkat dia mengepalai pengawalnya.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 24, 'Asael, saudara Yoab, ada di antara ketiga puluh orang itu; selanjutnya Elhanan bin Dodo, dari Betlehem;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 25, 'Sama, orang Harod; Elika, orang Harod;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 26, 'Heles, orang Palti; Ira anak Ikesh orang Tekoa;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 27, 'Abiezer, orang Anatot; Mebunai, orang Husa;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 28, 'Zalmon, orang Ahohi; Maharai, orang Netofa;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 29, 'Heleb anak Baana orang Netofa; Itai bin Ribai, dari Gibea orang Benyamin;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 30, 'Benaya, orang Piraton; Hidai dari lembah-lembah Gaas;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 31, 'Abialbon, orang Bet-Araba; Azmawet, orang Bahurim;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 32, 'Elyahba, orang Saalbon; Yasyen, orang Guni; Yonatan', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 33, 'anak Sama orang Harari; Ahiam bin Sarar, orang Harari;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 34, 'Elifelet anak Ahasbai orang Maakha; Eliam anak Ahitofel orang Gilo;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 35, 'Hezrai, orang Karmel; Paerai, orang Arbi;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 36, 'Yigal bin Natan, dari Zoba; Bani, orang Gad;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 37, 'Zelek, orang Amon; Naharai, orang Beerot, pembawa senjata Yoab anak Zeruya;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 38, 'Ira, orang Yetri; Gareb, orang Yetri;', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 23, 39, 'Uria, orang Het, semuanya tiga puluh tujuh orang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 1, 'Bangkitlah pula murka TUHAN terhadap orang Israel; Ia menghasut Daud melawan mereka, firman-Nya: "Pergilah, hitunglah orang Israel dan orang Yehuda."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 2, 'Lalu berkatalah raja kepada Yoab dan para panglima tentara yang bersama-sama dengan dia: "Jelajahilah segenap suku Israel dari Dan sampai Bersyeba; adakanlah pendaftaran di antara rakyat, supaya aku tahu jumlah mereka."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 3, 'Lalu berkatalah Yoab kepada raja: "Kiranya TUHAN, Allahmu, menambahi rakyat seratus kali lipat dari pada yang ada sekarang, dan semoga mata tuanku raja sendiri melihatnya. Tetapi mengapa tuanku raja menghendaki hal ini?"', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 4, 'Namun titah raja itu terpaksa diikuti oleh Yoab dan oleh para panglima tentara. Maka pergilah Yoab dan panglima-panglima tentara itu atas perintah raja untuk mengadakan pendaftaran di antara bangsa Israel.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 5, 'Mereka menyeberangi sungai Yordan, lalu mulai dari Aroer dan dari kota yang terletak di tengah-tengah lembah ke arah Gad dan Yaezer.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 6, 'Kemudian sampailah mereka ke Gilead dan ke Kadesh di negeri orang Het. Selanjutnya sampailah mereka ke Dan dan dari Dan mengambil jurusan Sidon.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 7, 'Kemudian sampailah mereka ke tempat yang berkubu, Tirus, dan ke segala kota orang Hewi dan orang Kanaan; akhirnya tibalah mereka di bagian selatan Yehuda, di Bersyeba.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 8, 'Setelah mereka menjelajah seluruh negeri itu, sampailah mereka kembali ke Yerusalem setelah lewat sembilan bulan dan dua puluh hari.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 9, 'Lalu Yoab memberitahukan kepada raja hasil pendaftaran rakyat. Orang Israel ada delapan ratus ribu orang perangnya yang dapat memegang pedang; dan orang Yehuda ada lima ratus ribu.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 10, 'Tetapi berdebar-debarlah hati Daud, setelah ia menghitung rakyat, lalu berkatalah Daud kepada TUHAN: "Aku telah sangat berdosa karena melakukan hal ini; maka sekarang, TUHAN, jauhkanlah kiranya kesalahan hamba-Mu, sebab perbuatanku itu sangat bodoh."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 11, 'Setelah Daud bangun dari pada waktu pagi, datanglah firman TUHAN kepada nabi Gad, pelihat Daud, demikian:', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 12, '"Pergilah, katakanlah kepada Daud: Beginilah firman TUHAN: tiga perkara Kuhadapkan kepadamu; pilihlah salah satu dari padanya, maka Aku akan melakukannya kepadamu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 13, 'Kemudian datanglah Gad kepada Daud, memberitahukan kepadanya dengan berkata kepadanya: "Akan datangkah menimpa engkau tiga tahun kelaparan di negerimu? Atau maukah engkau melarikan diri tiga bulan lamanya dari hadapan lawanmu, sedang mereka itu mengejar engkau? Atau, akan adakah tiga hari penyakit sampar di negerimu? Maka sekarang, pikirkanlah dan timbanglah, jawab apa yang harus kusampaikan kepada Yang mengutus aku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 14, 'Lalu berkatalah Daud kepada Gad: "Sangat susah hatiku, biarlah kiranya kita jatuh ke dalam tangan TUHAN, sebab besar kasih sayang-Nya; tetapi janganlah aku jatuh ke dalam tangan manusia."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 15, 'Jadi TUHAN mendatangkan penyakit sampar kepada orang Israel dari pagi hari sampai waktu yang ditetapkan, maka matilah dari antara bangsa itu, dari Dan sampai Bersyeba, tujuh puluh ribu orang.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 16, 'Ketika malaikat mengacungkan tangannya ke Yerusalem untuk memusnahkannya, maka menyesallah TUHAN karena malapetaka itu, lalu Ia berfirman kepada malaikat yang mendatangkan kemusnahan kepada bangsa itu: "Cukup! Turunkanlah sekarang tanganmu itu." Pada waktu itu malaikat TUHAN itu ada dekat tempat pengirikan Arauna, orang Yebus.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 17, 'Dan berkatalah Daud kepada TUHAN, ketika dilihatnya malaikat yang tengah memusnahkan bangsa itu, demikian: "Sesungguhnya, aku telah berdosa, dan aku telah membuat kesalahan, tetapi domba-domba ini, apakah yang dilakukan mereka? Biarlah kiranya tangan-Mu menimpa aku dan kaum keluargaku."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 18, 'Pada hari itu datanglah Gad kepada Daud dan berkata kepadanya: "Pergilah, dirikanlah mezbah bagi TUHAN di tempat pengirikan Arauna, orang Yebus itu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 19, 'Lalu pergilah Daud, sesuai dengan perkataan Gad, seperti yang diperintahkan TUHAN.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 20, 'Ketika Arauna menjenguk dan melihat raja dengan pegawai-pegawainya mendapatkannya, pergilah Arauna ke luar, lalu sujud kepada raja dengan mukanya ke tanah.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 21, 'Bertanyalah Arauna: "Mengapa tuanku raja datang kepada hambanya ini?" Jawab Daud: "Untuk membeli tempat pengirikan ini dari padamu dengan maksud mendirikan mezbah bagi TUHAN, supaya tulah ini berhenti menimpa rakyat."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 22, 'Lalu berkatalah Arauna kepada Daud: "Baiklah tuanku raja mengambilnya dan mempersembahkan apa yang dipandangnya baik; lihatlah, itu ada lembu-lembu untuk korban bakaran, dan eretan-eretan pengirik dan alat perkakas lembu untuk kayu bakar.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 23, 'Semuanya ini, ya raja, diberikan Arauna kepada raja." Arauna berkata pula kepada raja: "Kiranya TUHAN, Allahmu, berkenan kepadamu."', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 24, 'Tetapi berkatalah raja kepada Arauna: "Bukan begitu, melainkan aku mau membelinya dari padamu dengan membayar harganya, sebab aku tidak mau mempersembahkan kepada TUHAN, Allahku, korban bakaran dengan tidak membayar apa-apa." Sesudah itu Daud membeli tempat pengirikan dan lembu-lembu itu dengan harga lima puluh syikal perak.', 'id', 'TB'),
  ('10', '2sam', '2 Samuel', 24, 25, 'Lalu Daud mendirikan di sana mezbah bagi TUHAN dan mempersembahkan korban bakaran dan korban keselamatan. Maka TUHAN mengabulkan doa untuk negeri itu, dan tulah itu berhenti menimpa orang Israel.', 'id', 'TB')
